-- Page access enforcement in the database.
--
-- The role editor's None / View / Edit matrix (migration 0155) is enforced here, so a role can't read or change what its
-- pages don't grant by calling the API directly. Each data function below is re-created with one extra line at the top of
-- its body: require_page_access_any(<facility>, <keys>), which raises 42501 unless the caller holds at least one key.
-- Service-role callers (edge functions, webhooks: no end user) are exempt. Owners hold every key.
--
-- It also adds the coach scope: for a non-owner whose role carries COACHING_OWN_ONLY the coaching reads return only
-- their own coach profile, sessions, programs and students, and the facility-wide coaching stats / reports are refused.
--
-- GENERATED by scripts/gen-access-enforcement.cjs from the current function definitions — re-run it rather than editing.

create or replace function require_page_access_any(p_facility uuid, p_permissions text[])
returns void
language plpgsql stable security definer set search_path = public
as $$
begin
  if auth.uid() is null or p_facility is null then
    return; -- service role / internal call, or an id that doesn't exist (the function reports that itself)
  end if;
  if exists (select 1 from unnest(p_permissions) k where has_permission(p_facility, k)) then
    return;
  end if;
  raise exception 'You don''t have access to this page.' using errcode = '42501';
end;
$$;
grant execute on function require_page_access_any(uuid, text[]) to authenticated;

-- get_reports_overview (was 0141_reports_overview_counts_follow_dates.sql)
create or replace function get_reports_overview(
  p_facility_id uuid,
  p_start_date date,
  p_end_date date,
  p_facility_sport_ids uuid[] default null
) returns jsonb
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  gross bigint;
  refunded bigint;
  spent bigint;
  coaching_spent bigint;
  rev jsonb;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, 'CUSTOM', p_start_date, p_end_date);
  tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');

  select (coalesce(sum(p.amount_inr), 0) * 100)::bigint into gross
    from payments p
   where p.facility_id = p_facility_id and p.status = 'paid'
     and range_ @> coalesce(p.paid_at, p.created_at)
     and payment_in_sports(p.id, p_facility_sport_ids);

  select coalesce(sum(r.amount_minor), 0)::bigint into refunded
    from refunds r
   where r.facility_id = p_facility_id and r.status = 'PROCESSED'
     and r.processed_at is not null and range_ @> r.processed_at
     and payment_order_in_sports(r.payment_order_id, p_facility_sport_ids);

  select coalesce(sum(e.amount_minor), 0)::bigint,
         coalesce(sum(e.amount_minor) filter (where lower(c.name) = 'coaching'), 0)::bigint
    into spent, coaching_spent
    from expenses e join expense_categories c on c.id = e.category_id
   where e.facility_id = p_facility_id and e.status = 'RECORDED'
     and range_ @> (e.spent_on::timestamp at time zone tz);

  select jsonb_build_object(
           'guest', coalesce(sum(v.amount_minor) filter (where v.source_type = 'GUEST_BOOKING'), 0),
           'membership', coalesce(sum(v.amount_minor) filter (where v.source_type = 'MEMBERSHIP'), 0),
           'coaching', coalesce(sum(v.amount_minor) filter (where v.source_type = 'COACHING'), 0))
    into rev
    from finance_transactions_view v
   where v.facility_id = p_facility_id and v.status = 'paid' and range_ @> v.effective_at
     and payment_in_sports(v.id, p_facility_sport_ids);

  return jsonb_build_object(
    'totalRevenueMinor', gross - refunded,
    'totalExpensesMinor', spent,
    'netRevenueMinor', gross - refunded - spent,
    'guestBookings', (
      select count(*) from bookings b
       where b.facility_id = p_facility_id and b.customer_type = 'GUEST' and range_ @> b.start_time
         and booking_in_sports(b.id, p_facility_sport_ids)
    ),
    -- Members: people whose membership ran at any point in the dates (it started by the last day and had not ended
    -- before the first day), cancelled ones left out.
    'members', (
      select count(distinct m.member_id) from memberships m
       where m.facility_id = p_facility_id and m.status <> 'cancelled'
         and m.start_date <= p_end_date and m.end_date >= p_start_date
         and membership_in_sports(m.id, p_facility_sport_ids)
    ),
    -- Programs: those that were running at any point in the dates.
    'programs', (
      select count(*) from coaching_programs cp
       where cp.facility_id = p_facility_id and cp.status in ('ACTIVE', 'COMPLETED', 'PAUSED')
         and coalesce(cp.start_date, (cp.created_at at time zone tz)::date) <= p_end_date
         and coalesce(cp.end_date, p_end_date) >= p_start_date
         and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids))
    ),
    -- Coaches: those who had joined by the last day of the dates (and are not marked inactive).
    'coaches', (
      select count(*) from coaches c
       where c.facility_id = p_facility_id and c.status in ('ACTIVE', 'ON_LEAVE')
         and coalesce(c.joined_on, (c.created_at at time zone tz)::date) <= p_end_date
         and (p_facility_sport_ids is null
              or exists (select 1 from coach_sports cs where cs.coach_id = c.id and cs.facility_sport_id = any (p_facility_sport_ids)))
    ),
    -- Students: people enrolled at any point in the dates (started by the last day; not stopped or finished before the first).
    'students', (
      select count(distinct e.member_id) from coaching_enrollments e join coaching_programs cp on cp.id = e.program_id
       where e.facility_id = p_facility_id
         and e.start_date <= p_end_date
         and coalesce(e.cancelled_at at time zone tz, e.end_date, p_end_date)::date >= p_start_date
         and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids))
    ),
    'guestBookingRevenueMinor', (rev ->> 'guest')::bigint,
    'membershipRevenueMinor', (rev ->> 'membership')::bigint,
    'coachingRevenueMinor', (rev ->> 'coaching')::bigint,
    'coachingExpensesMinor', coaching_spent
  );
end;
$$;

-- get_reports_overview_trend (was 0140_reports_overview.sql)
create or replace function get_reports_overview_trend(
  p_facility_id uuid,
  p_metric text,
  p_start_date date,
  p_end_date date,
  p_granularity text default 'daily',
  p_facility_sport_ids uuid[] default null
) returns table (bucket_date date, value bigint)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  unit text;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if p_granularity not in ('daily', 'weekly', 'monthly') then
    raise exception 'Unknown granularity: %', p_granularity using errcode = '22023';
  end if;
  unit := case p_granularity when 'daily' then 'day' when 'weekly' then 'week' else 'month' end;
  range_ := resolve_finance_date_range(p_facility_id, 'CUSTOM', p_start_date, p_end_date);
  tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');

  -- Money in, by what it was for (payments received, by day received).
  if p_metric in ('GUEST_BOOKING_REVENUE', 'MEMBERSHIP_REVENUE', 'COACHING_REVENUE') then
    return query
    select date_trunc(unit, v.effective_at at time zone tz)::date, coalesce(sum(v.amount_minor), 0)::bigint
      from finance_transactions_view v
     where v.facility_id = p_facility_id and v.status = 'paid' and range_ @> v.effective_at
       and v.source_type = case p_metric when 'GUEST_BOOKING_REVENUE' then 'GUEST_BOOKING' when 'MEMBERSHIP_REVENUE' then 'MEMBERSHIP' else 'COACHING' end
       and payment_in_sports(v.id, p_facility_sport_ids)
     group by 1 order by 1;

  -- Revenue = payments less refunds; net = revenue less expenses.
  elsif p_metric in ('REVENUE', 'NET') then
    return query
    with pay as (
      select date_trunc(unit, v.effective_at at time zone tz)::date as b, sum(v.amount_minor) as amt
        from finance_transactions_view v
       where v.facility_id = p_facility_id and v.status = 'paid' and range_ @> v.effective_at
         and payment_in_sports(v.id, p_facility_sport_ids)
       group by 1
    ), ref as (
      select date_trunc(unit, r.processed_at at time zone tz)::date as b, sum(r.amount_minor) as amt
        from refunds r
       where r.facility_id = p_facility_id and r.status = 'PROCESSED' and r.processed_at is not null and range_ @> r.processed_at
         and payment_order_in_sports(r.payment_order_id, p_facility_sport_ids)
       group by 1
    ), exp as (
      select date_trunc(unit, e.spent_on::timestamp)::date as b, sum(e.amount_minor) as amt
        from expenses e
       where e.facility_id = p_facility_id and e.status = 'RECORDED' and range_ @> (e.spent_on::timestamp at time zone tz)
       group by 1
    ), buckets as (
      select b from pay union select b from ref union select b from exp
    )
    select k.b,
           (coalesce(pay.amt, 0) - coalesce(ref.amt, 0) - case when p_metric = 'NET' then coalesce(exp.amt, 0) else 0 end)::bigint
      from buckets k
      left join pay on pay.b = k.b left join ref on ref.b = k.b left join exp on exp.b = k.b
     order by k.b;

  -- Expenses (facility-wide): all, or the "Coaching" category only.
  elsif p_metric in ('EXPENSES', 'COACHING_EXPENSES') then
    return query
    select date_trunc(unit, e.spent_on::timestamp)::date, coalesce(sum(e.amount_minor), 0)::bigint
      from expenses e join expense_categories c on c.id = e.category_id
     where e.facility_id = p_facility_id and e.status = 'RECORDED' and range_ @> (e.spent_on::timestamp at time zone tz)
       and (p_metric = 'EXPENSES' or lower(c.name) = 'coaching')
     group by 1 order by 1;

  elsif p_metric = 'GUEST_BOOKINGS' then
    return query
    select date_trunc(unit, b.start_time at time zone tz)::date, count(*)::bigint
      from bookings b
     where b.facility_id = p_facility_id and b.customer_type = 'GUEST' and range_ @> b.start_time
       and booking_in_sports(b.id, p_facility_sport_ids)
     group by 1 order by 1;

  -- "Now" counts, charted as how many were added in each bucket.
  elsif p_metric = 'MEMBERS' then
    return query
    select date_trunc(unit, m.start_date::timestamp)::date, count(*)::bigint
      from memberships m
     where m.facility_id = p_facility_id and m.status <> 'cancelled'
       and range_ @> (m.start_date::timestamp at time zone tz) and membership_in_sports(m.id, p_facility_sport_ids)
     group by 1 order by 1;

  elsif p_metric = 'PROGRAMS' then
    return query
    select date_trunc(unit, cp.start_date::timestamp)::date, count(*)::bigint
      from coaching_programs cp
     where cp.facility_id = p_facility_id and cp.start_date is not null and cp.status in ('ACTIVE', 'COMPLETED', 'PAUSED')
       and range_ @> (cp.start_date::timestamp at time zone tz)
       and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids))
     group by 1 order by 1;

  elsif p_metric = 'COACHES' then
    return query
    select date_trunc(unit, coalesce(c.joined_on, (c.created_at at time zone tz)::date)::timestamp)::date, count(*)::bigint
      from coaches c
     where c.facility_id = p_facility_id and c.status in ('ACTIVE', 'ON_LEAVE')
       and range_ @> (coalesce(c.joined_on, (c.created_at at time zone tz)::date)::timestamp at time zone tz)
       and (p_facility_sport_ids is null
            or exists (select 1 from coach_sports cs where cs.coach_id = c.id and cs.facility_sport_id = any (p_facility_sport_ids)))
     group by 1 order by 1;

  elsif p_metric = 'STUDENTS' then
    return query
    select date_trunc(unit, e.start_date::timestamp)::date, count(*)::bigint
      from coaching_enrollments e join coaching_programs cp on cp.id = e.program_id
     where e.facility_id = p_facility_id and e.status <> 'CANCELLED'
       and range_ @> (e.start_date::timestamp at time zone tz)
       and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids))
     group by 1 order by 1;

  else
    raise exception 'Unknown overview metric: %', p_metric using errcode = '22023';
  end if;
end;
$$;

-- get_analytics_overview (was 0138_reports_sport_scope.sql)
create or replace function get_analytics_overview(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  gross_revenue_minor bigint,
  booking_revenue_minor bigint,
  membership_revenue_minor bigint,
  expenses_minor bigint,
  net_revenue_minor bigint,
  outstanding_minor bigint,
  total_bookings bigint,
  completed_bookings bigint,
  cancelled_bookings bigint,
  overall_utilization_pct numeric
)
language plpgsql
stable
as $$
declare
  v_gross bigint;
  v_exp bigint;
  v_net bigint;
  v_out bigint;
  v_membership bigint;
  v_member_book bigint;
  v_guest_book bigint;
  v_total bigint;
  v_completed bigint;
  v_cancelled bigint;
  v_util numeric;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;

  select s.gross_revenue_minor, s.expenses_minor, s.net_revenue_minor, s.outstanding_minor
    into v_gross, v_exp, v_net, v_out
    from get_finance_summary(p_facility_id, p_preset, p_start_date, p_end_date, p_facility_sport_ids) s;

  select b.membership_revenue_minor, b.member_booking_revenue_minor, b.guest_booking_revenue_minor
    into v_membership, v_member_book, v_guest_book
    from get_revenue_breakdown(p_facility_id, p_preset, p_start_date, p_end_date, p_facility_sport_ids) b;

  select a.total, a.completed, a.cancelled
    into v_total, v_completed, v_cancelled
    from get_booking_analytics(
      p_facility_id, p_preset, p_start_date, p_end_date, p_facility_sport_id, p_court_id, p_facility_sport_ids
    ) a;

  select u.utilization_pct
    into v_util
    from get_overall_utilization(
      p_facility_id, p_preset, p_start_date, p_end_date, p_facility_sport_id, p_court_id, p_facility_sport_ids
    ) u;

  return query select
    coalesce(v_gross, 0),
    (coalesce(v_member_book, 0) + coalesce(v_guest_book, 0))::bigint,
    coalesce(v_membership, 0),
    coalesce(v_exp, 0),
    coalesce(v_net, 0),
    coalesce(v_out, 0),
    coalesce(v_total, 0),
    coalesce(v_completed, 0),
    coalesce(v_cancelled, 0),
    coalesce(v_util, 0);
end;
$$;

-- get_booking_analytics (was 0138_reports_sport_scope.sql)
create or replace function get_booking_analytics(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  total bigint,
  completed bigint,
  confirmed bigint,
  pending bigint,
  cancelled bigint,
  guest_count bigint,
  member_count bigint,
  avg_guest_booking_value_minor bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_OVERVIEW_VIEW', 'REPORT_UTILIZATION_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with b as (
    select bk.status::text as status, bk.customer_type, bk.amount_minor, bk.payment_status
    from bookings bk
    where bk.facility_id = p_facility_id
      and range_ @> bk.start_time
      and (p_facility_sport_id is null or bk.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or bk.facility_sport_id = any (p_facility_sport_ids))
      and (p_court_id is null or bk.court_id = p_court_id)
  )
  select
    count(*)::bigint,
    count(*) filter (where status = 'completed')::bigint,
    count(*) filter (where status = 'confirmed')::bigint,
    count(*) filter (where status = 'pending')::bigint,
    count(*) filter (where status = 'cancelled')::bigint,
    count(*) filter (where customer_type = 'GUEST')::bigint,
    count(*) filter (where customer_type = 'MEMBER')::bigint,
    coalesce(
      round(
        avg(amount_minor) filter (
          where customer_type = 'GUEST' and payment_status = 'PAID' and status <> 'cancelled'
        )
      )::bigint,
      0
    )
  from b;
end;
$$;

-- get_booking_source_split (was 0138_reports_sport_scope.sql)
create or replace function get_booking_source_split(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  source text,
  booking_count bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_OVERVIEW_VIEW', 'REPORT_UTILIZATION_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with b as (
    select bk.customer_type
    from bookings bk
    where bk.facility_id = p_facility_id
      and range_ @> bk.start_time
      and (p_facility_sport_id is null or bk.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or bk.facility_sport_id = any (p_facility_sport_ids))
      and (p_court_id is null or bk.court_id = p_court_id)
  )
  select s.source, coalesce(count(b.customer_type), 0)::bigint
  from (values ('GUEST'), ('MEMBER')) as s(source)
  left join b on b.customer_type = s.source
  group by s.source
  order by s.source;
end;
$$;

-- get_booking_trend (was 0138_reports_sport_scope.sql)
create or replace function get_booking_trend(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_granularity text default 'daily',
  p_facility_sport_ids uuid[] default null
) returns table (
  bucket_date date,
  total bigint,
  completed bigint,
  cancelled bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  unit text;
  step interval;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_OVERVIEW_VIEW', 'REPORT_UTILIZATION_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if p_granularity not in ('daily', 'weekly', 'monthly') then
    raise exception 'Unknown granularity: %', p_granularity using errcode = '22023';
  end if;
  unit := case p_granularity when 'daily' then 'day' when 'weekly' then 'week' else 'month' end;
  step := case p_granularity when 'daily' then interval '1 day' when 'weekly' then interval '1 week' else interval '1 month' end;

  select coalesce(timezone, 'Asia/Kolkata') into tz from facilities where id = p_facility_id;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with buckets as (
    select generate_series(
      date_trunc(unit, lower(range_) at time zone tz),
      date_trunc(unit, (upper(range_) - interval '1 microsecond') at time zone tz),
      step
    )::date as bucket
  ),
  grouped as (
    select date_trunc(unit, bk.start_time at time zone tz)::date as bucket,
           count(*) as total,
           count(*) filter (where bk.status = 'completed') as completed,
           count(*) filter (where bk.status = 'cancelled') as cancelled
    from bookings bk
    where bk.facility_id = p_facility_id
      and range_ @> bk.start_time
      and (p_facility_sport_id is null or bk.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or bk.facility_sport_id = any (p_facility_sport_ids))
      and (p_court_id is null or bk.court_id = p_court_id)
    group by 1
  )
  select b.bucket,
         coalesce(g.total, 0)::bigint,
         coalesce(g.completed, 0)::bigint,
         coalesce(g.cancelled, 0)::bigint
  from buckets b
  left join grouped g on g.bucket = b.bucket
  order by b.bucket;
end;
$$;

-- get_bookings_by_sport (was 0138_reports_sport_scope.sql)
create or replace function get_bookings_by_sport(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  facility_sport_id uuid,
  sport_name text,
  booking_count bigint
)
language plpgsql
stable
as $$
#variable_conflict use_column
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_OVERVIEW_VIEW', 'REPORT_UTILIZATION_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  select
    fs.id,
    coalesce(fs.custom_sport_name, sp.name),
    count(bk.id)::bigint
  from facility_sports fs
  join sports sp on sp.id = fs.sport_id
  left join bookings bk
    on bk.facility_sport_id = fs.id
    and range_ @> bk.start_time
    and (p_court_id is null or bk.court_id = p_court_id)
  where fs.facility_id = p_facility_id
    and fs.is_active
    and (p_facility_sport_id is null or fs.id = p_facility_sport_id)
      and (p_facility_sport_ids is null or fs.id = any (p_facility_sport_ids))
  group by fs.id, coalesce(fs.custom_sport_name, sp.name)
  order by count(bk.id) desc, coalesce(fs.custom_sport_name, sp.name);
end;
$$;

-- get_demand_heatmap (was 0138_reports_sport_scope.sql)
create or replace function get_demand_heatmap(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  dow smallint,
  hour smallint,
  open_minutes integer,
  booked_minutes integer,
  demand_pct numeric
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_OVERVIEW_VIEW', 'REPORT_UTILIZATION_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with scope as (
    select c.id
    from courts c
    where c.facility_id = p_facility_id
      and not c.archived
      and (p_facility_sport_id is null or c.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or c.facility_sport_id = any (p_facility_sport_ids))
      and (p_court_id is null or c.id = p_court_id)
  ),
  open_c as (
    select w.dow, w.hour, sum(w.minutes) as m
    from scope cross join lateral analytics_court_open_minutes_by_cell(scope.id, range_) w
    group by w.dow, w.hour
  ),
  book_c as (
    select w.dow, w.hour, sum(w.minutes) as m
    from scope cross join lateral analytics_court_booked_minutes_by_cell(scope.id, range_) w
    group by w.dow, w.hour
  )
  select
    o.dow,
    o.hour,
    round(o.m)::integer,
    round(coalesce(b.m, 0))::integer,
    least(100, round((coalesce(b.m, 0) / o.m) * 100, 1))
  from open_c o
  left join book_c b on b.dow = o.dow and b.hour = o.hour
  where o.m > 0
  order by o.dow, o.hour;
end;
$$;

