-- get_revenue_breakdown (was 0137_finance_sport_scope.sql)
create or replace function get_revenue_breakdown(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  membership_revenue_minor bigint,
  member_booking_revenue_minor bigint,
  guest_booking_revenue_minor bigint,
  refunds_minor bigint,
  net_revenue_minor bigint,
  membership_included_usage_count bigint,
  coaching_revenue_minor bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  refunded bigint;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_REVENUE_VIEW', 'REPORT_OVERVIEW_VIEW', 'FINANCE_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  select coalesce(sum(r.amount_minor), 0)::bigint into refunded
    from refunds r
    where r.facility_id = p_facility_id and r.status = 'PROCESSED'
      and r.processed_at is not null and range_ @> r.processed_at and payment_order_in_sports(r.payment_order_id, p_facility_sport_ids);

  return query
  with classified as (
    select v.source_type, v.amount_minor
    from finance_transactions_view v
    where v.facility_id = p_facility_id and v.status = 'paid' and range_ @> v.effective_at
      and payment_in_sports(v.id, p_facility_sport_ids)
  )
  select
    coalesce(sum(amount_minor) filter (where source_type = 'MEMBERSHIP'), 0)::bigint,
    coalesce(sum(amount_minor) filter (where source_type = 'MEMBER_BOOKING'), 0)::bigint,
    coalesce(sum(amount_minor) filter (where source_type = 'GUEST_BOOKING'), 0)::bigint,
    refunded::bigint,
    (coalesce(sum(amount_minor), 0) - refunded)::bigint,
    (
      select count(*) from membership_session_bookings msb
      where msb.facility_id = p_facility_id and msb.participant_type = 'MEMBER'
        and msb.status = 'CONFIRMED' and range_ @> msb.created_at
        and session_booking_in_sports(msb.id, p_facility_sport_ids)
    )::bigint,
    coalesce(sum(amount_minor) filter (where source_type = 'COACHING'), 0)::bigint
  from classified;
end;
$$;

-- get_revenue_by_court (was 0150_court_removal_integrity.sql)
create or replace function get_revenue_by_court(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  court_id uuid,
  court_name text,
  facility_sport_id uuid,
  sport_name text,
  revenue_minor bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_REVENUE_VIEW', 'REPORT_OVERVIEW_VIEW', 'FINANCE_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with rev as (
    select
      coalesce(b.court_id, ms.court_id) as court_id,
      (p.amount_inr * 100)::bigint as amount_minor
    from payments p
    left join bookings b on b.id = p.booking_id
    left join membership_session_bookings msb on msb.id = p.membership_session_booking_id
    left join membership_sessions ms on ms.id = msb.session_id
    where p.facility_id = p_facility_id
      and p.status = 'paid'
      and range_ @> coalesce(p.paid_at, p.created_at)
      and coalesce(b.court_id, ms.court_id) is not null
  )
  select
    c.id,
    c.name,
    c.facility_sport_id,
    coalesce(fs.custom_sport_name, sp.name),
    coalesce(sum(rev.amount_minor), 0)::bigint
  from courts c
  join facility_sports fs on fs.id = c.facility_sport_id
  join sports sp on sp.id = fs.sport_id
  left join rev on rev.court_id = c.id
  where c.facility_id = p_facility_id
    -- A removed court stays in the figures for the period it earned in, so the rows still add up to the total.
    and (not c.archived or exists (select 1 from rev h where h.court_id = c.id))
    and (p_facility_sport_id is null or c.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or c.facility_sport_id = any (p_facility_sport_ids))
    and (p_court_id is null or c.id = p_court_id)
  group by c.id, c.name, c.facility_sport_id, coalesce(fs.custom_sport_name, sp.name)
  order by coalesce(sum(rev.amount_minor), 0) desc, c.name;
end;
$$;

-- get_revenue_by_sport (was 0144_revenue_by_sport_all_sources.sql)
create or replace function get_revenue_by_sport(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  facility_sport_id uuid,
  sport_name text,
  revenue_minor bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_REVENUE_VIEW', 'REPORT_OVERVIEW_VIEW', 'FINANCE_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with received as (
    select p.id, p.amount_inr
      from payments p
     where p.facility_id = p_facility_id
       and p.status = 'paid'
       and range_ @> coalesce(p.paid_at, p.created_at)
       -- a court filter keeps only what was paid for that court (its bookings, or a membership slot held on it)
       and (p_court_id is null
            or exists (select 1 from bookings b where b.id = p.booking_id and b.court_id = p_court_id)
            or exists (select 1 from membership_session_bookings msb join membership_sessions ms on ms.id = msb.session_id
                        where msb.id = p.membership_session_booking_id and ms.court_id = p_court_id))
  ), per_sport as (
    select fs.id as fsid,
           coalesce(fs.custom_sport_name, sp.name) as nm,
           (coalesce((select sum(r.amount_inr) from received r where payment_in_sports(r.id, array[fs.id])), 0) * 100)::bigint as amt,
           0 as ord
      from facility_sports fs
      join sports sp on sp.id = fs.sport_id
     where fs.facility_id = p_facility_id
       and fs.is_active
       and (p_facility_sport_id is null or fs.id = p_facility_sport_id)
       and (p_facility_sport_ids is null or fs.id = any (p_facility_sport_ids))
  ), unlinked as (
    select null::uuid as fsid,
           'Not linked to a sport'::text as nm,
           (coalesce(sum(r.amount_inr), 0) * 100)::bigint as amt,
           1 as ord
      from received r
     where p_facility_sport_id is null and p_facility_sport_ids is null and p_court_id is null
       and not exists (select 1 from facility_sports f2
                        where f2.facility_id = p_facility_id and f2.is_active and payment_in_sports(r.id, array[f2.id]))
  ), all_rows as (
    select * from per_sport
    union all
    select * from unlinked where amt > 0
  )
  select a.fsid, a.nm, a.amt
    from all_rows a
   order by a.ord, a.amt desc, a.nm;
end;
$$;

-- get_revenue_trend (was 0137_finance_sport_scope.sql)
create or replace function get_revenue_trend(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_granularity text default 'daily',
  p_facility_sport_ids uuid[] default null
) returns table (
  bucket_date date,
  gross_minor bigint,
  refund_minor bigint,
  net_minor bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  trunc_unit text;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_REVENUE_VIEW', 'REPORT_OVERVIEW_VIEW', 'FINANCE_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if p_granularity not in ('daily', 'weekly', 'monthly') then
    raise exception 'Unknown granularity: %', p_granularity using errcode = '22023';
  end if;
  trunc_unit := case p_granularity when 'daily' then 'day' when 'weekly' then 'week' else 'month' end;

  select timezone into tz from facilities where id = p_facility_id;
  tz := coalesce(tz, 'Asia/Kolkata');
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with gross as (
    select date_trunc(trunc_unit, v.effective_at at time zone tz)::date as bucket,
           coalesce(sum(v.amount_minor), 0)::bigint as amount
    from finance_transactions_view v
    where v.facility_id = p_facility_id and v.status = 'paid' and range_ @> v.effective_at
      and payment_in_sports(v.id, p_facility_sport_ids)
    group by 1
  ),
  refund as (
    select date_trunc(trunc_unit, r.processed_at at time zone tz)::date as bucket,
           coalesce(sum(r.amount_minor), 0)::bigint as amount
    from refunds r
    where r.facility_id = p_facility_id and r.status = 'PROCESSED'
      and r.processed_at is not null and range_ @> r.processed_at
      and payment_order_in_sports(r.payment_order_id, p_facility_sport_ids)
    group by 1
  ),
  buckets as (
    select bucket from gross union select bucket from refund
  )
  select
    b.bucket,
    coalesce(g.amount, 0)::bigint,
    coalesce(rf.amount, 0)::bigint,
    (coalesce(g.amount, 0) - coalesce(rf.amount, 0))::bigint
  from buckets b
  left join gross g on g.bucket = b.bucket
  left join refund rf on rf.bucket = b.bucket
  order by b.bucket;
end;
$$;

-- get_payment_method_breakdown (was 0137_finance_sport_scope.sql)
create or replace function get_payment_method_breakdown(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_ids uuid[] default null
)
returns table (
  payment_method text,
  amount_minor bigint,
  payment_count bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_REVENUE_VIEW', 'REPORT_OVERVIEW_VIEW', 'FINANCE_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  select
    coalesce(nullif(trim(p.payment_method), ''), 'Unknown') as payment_method,
    (coalesce(sum(p.amount_inr), 0) * 100)::bigint as amount_minor,
    count(*)::bigint as payment_count
  from payments p
  where p.facility_id = p_facility_id
    and p.status = 'paid'
    and range_ @> coalesce(p.paid_at, p.created_at)
    and payment_in_sports(p.id, p_facility_sport_ids)
  group by 1
  order by 2 desc;
end;
$$;

-- get_finance_summary (was 0137_finance_sport_scope.sql)
create or replace function get_finance_summary(
  p_facility_id uuid,
  p_preset text default null,
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_ids uuid[] default null
)
returns table (
  gross_revenue_minor bigint,
  refunds_minor bigint,
  expenses_minor bigint,
  net_revenue_minor bigint,
  outstanding_minor bigint,
  transaction_count bigint,
  successful_payment_count bigint,
  failed_payment_count bigint,
  pending_payment_count bigint,
  pending_refund_count bigint,
  settlement_exception_count bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  gross bigint;
  refunded bigint;
  spent bigint;
  outstanding bigint;
  pending bigint;
  succ bigint;
  failed bigint;
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_VIEW', 'REPORT_REVENUE_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);
  tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');

  select (coalesce(sum(p.amount_inr), 0) * 100)::bigint, count(*)::bigint
    into gross, succ
    from payments p
    where p.facility_id = p_facility_id and p.status = 'paid' and range_ @> coalesce(p.paid_at, p.created_at)
      and payment_in_sports(p.id, p_facility_sport_ids);

  select coalesce(sum(r.amount_minor), 0)::bigint
    into refunded
    from refunds r
    where r.facility_id = p_facility_id and r.status = 'PROCESSED'
      and r.processed_at is not null and range_ @> r.processed_at and payment_order_in_sports(r.payment_order_id, p_facility_sport_ids);

  select coalesce(sum(e.amount_minor), 0)::bigint
    into spent
    from expenses e
    where e.facility_id = p_facility_id and e.status = 'RECORDED'
      and range_ @> (e.spent_on::timestamp at time zone tz);

  select count(*) filter (where po.status = 'FAILED')
    into failed
    from payment_orders po
    where po.facility_id = p_facility_id and range_ @> po.created_at
      and payment_order_in_sports(po.id, p_facility_sport_ids);

  with obligations as (
    select
      coalesce(b.amount_minor, 0)::bigint as total_minor,
      coalesce((
        select sum(p.amount_inr) * 100 from payments p
        where p.booking_id = b.id and p.status = 'paid'
      ), 0)::bigint as paid_minor
    from bookings b
    where b.facility_id = p_facility_id
      and b.status in ('pending', 'confirmed', 'completed')
      and booking_in_sports(b.id, p_facility_sport_ids)

    union all

    select
      (coalesce(ms.total_amount_inr, 0) * 100)::bigint,
      coalesce((
        select sum(p.amount_inr) * 100 from payments p
        where p.membership_id = ms.id and p.status = 'paid'
      ), 0)::bigint
    from memberships ms
    where ms.facility_id = p_facility_id
      and ms.status <> 'cancelled'
      and membership_in_sports(ms.id, p_facility_sport_ids)

    union all

    select
      coalesce(e.price_minor, 0)::bigint,
      coalesce((
        select sum(p.amount_inr) * 100 from payments p
        where p.coaching_enrollment_id = e.id and p.status = 'paid'
      ), 0)::bigint
    from coaching_enrollments e
    where e.facility_id = p_facility_id
      and e.status <> 'CANCELLED'
      and enrollment_in_sports(e.id, p_facility_sport_ids)
  ),
  owed as (
    select (o.total_minor - o.paid_minor) as amount
    from obligations o
    where o.total_minor > 0 and o.paid_minor < o.total_minor
  )
  select coalesce(sum(amount), 0)::bigint, count(*)::bigint
    into outstanding, pending
    from owed;

  return query select
    gross::bigint,
    refunded::bigint,
    spent::bigint,
    (gross - refunded - spent)::bigint,
    outstanding::bigint,
    (succ + failed + pending)::bigint,
    succ::bigint,
    failed::bigint,
    pending::bigint,
    (select count(*) from refunds r2 where r2.facility_id = p_facility_id and r2.status in ('REQUESTED', 'PROCESSING', 'PENDING') and payment_order_in_sports(r2.payment_order_id, p_facility_sport_ids))::bigint,
    (select count(*) from settlement_exceptions se where se.facility_id = p_facility_id and se.status = 'OPEN')::bigint;
end;
$$;

-- get_membership_analytics (was 0138_reports_sport_scope.sql)
create or replace function get_membership_analytics(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  active_members bigint,
  new_memberships bigint,
  expiring_soon bigint,
  membership_revenue_minor bigint,
  paid_count bigint,
  partially_paid_count bigint,
  pending_count bigint,
  outstanding_minor bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  today date;
  v_rev bigint;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_MEMBERSHIPS_VIEW', 'MEMBERSHIPS_VIEW', 'MEMBERSHIP_SESSIONS_VIEW', 'REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  select coalesce(timezone, 'Asia/Kolkata') into tz from facilities where id = p_facility_id;
  today := (now() at time zone tz)::date;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  select b.membership_revenue_minor into v_rev
    from get_revenue_breakdown(p_facility_id, p_preset, p_start_date, p_end_date, p_facility_sport_ids) b;

  return query
  with new_m as (
    select
      mm.id,
      (coalesce(mm.total_amount_inr, mm.membership_fee_inr, mp.price_inr, 0) * 100)::bigint as total_minor,
      (coalesce(
        (select sum(pp.amount_inr) from payments pp where pp.membership_id = mm.id and pp.status = 'paid'),
        0
      ) * 100)::bigint as paid_minor
    from memberships mm
    left join membership_plans mp on mp.id = mm.plan_id
    where mm.facility_id = p_facility_id
      and range_ @> mm.created_at
      and membership_in_sports(mm.id, p_facility_sport_ids)
  )
  select
    (select count(*) from memberships where facility_id = p_facility_id and status = 'active' and membership_in_sports(memberships.id, p_facility_sport_ids))::bigint,
    (select count(*) from new_m)::bigint,
    (select count(*) from memberships
       where facility_id = p_facility_id and status = 'active'
         and end_date >= today and end_date <= today + 30
         and membership_in_sports(memberships.id, p_facility_sport_ids))::bigint,
    coalesce(v_rev, 0),
    (select count(*) from new_m where total_minor > 0 and paid_minor >= total_minor)::bigint,
    (select count(*) from new_m where paid_minor > 0 and paid_minor < total_minor)::bigint,
    (select count(*) from new_m where paid_minor = 0 and total_minor > 0)::bigint,
    (select coalesce(sum(greatest(total_minor - paid_minor, 0)), 0) from new_m)::bigint;
end;
$$;

-- get_memberships_by_type (was 0138_reports_sport_scope.sql)
create or replace function get_memberships_by_type(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  membership_type text,
  plan_name text,
  count bigint,
  revenue_minor bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_MEMBERSHIPS_VIEW', 'MEMBERSHIPS_VIEW', 'MEMBERSHIP_SESSIONS_VIEW', 'REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with m as (
    select
      mm.membership_type,
      coalesce(mp.name, '—') as plan_name,
      (coalesce(
        (select sum(pp.amount_inr) from payments pp where pp.membership_id = mm.id and pp.status = 'paid'),
        0
      ) * 100)::bigint as paid_minor
    from memberships mm
    left join membership_plans mp on mp.id = mm.plan_id
    where mm.facility_id = p_facility_id
      and range_ @> mm.created_at
      and membership_in_sports(mm.id, p_facility_sport_ids)
  )
  select m.membership_type, m.plan_name, count(*)::bigint, coalesce(sum(m.paid_minor), 0)::bigint
  from m
  group by m.membership_type, m.plan_name
  order by count(*) desc, m.membership_type;
end;
$$;

-- get_membership_session_analytics (was 0138_reports_sport_scope.sql)
create or replace function get_membership_session_analytics(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  session_count bigint,
  total_capacity bigint,
  member_allocations bigint,
  guest_released bigint,
  guest_booked bigint,
  remaining_released bigint,
  unused_capacity bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  start_d date;
  end_d date;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_MEMBERSHIPS_VIEW', 'MEMBERSHIPS_VIEW', 'MEMBERSHIP_SESSIONS_VIEW', 'REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  select coalesce(timezone, 'Asia/Kolkata') into tz from facilities where id = p_facility_id;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);
  start_d := (lower(range_) at time zone tz)::date;
  end_d := ((upper(range_) - interval '1 microsecond') at time zone tz)::date;

  return query
  with s as (
    select
      ms.capacity,
      ms.released_capacity,
      (select count(*) from membership_session_bookings b
         where b.session_id = ms.id and b.participant_type = 'MEMBER' and b.status = 'CONFIRMED') as member_cnt,
      (select count(*) from membership_session_bookings b
         where b.session_id = ms.id and b.participant_type = 'GUEST' and b.status = 'CONFIRMED') as guest_cnt
    from membership_sessions ms
    where ms.facility_id = p_facility_id
      and ms.session_date >= start_d
      and ms.session_date <= end_d
      and (p_facility_sport_id is null or ms.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or ms.facility_sport_id = any (p_facility_sport_ids))
      and (p_court_id is null or ms.court_id = p_court_id)
  )
  select
    count(*)::bigint,
    coalesce(sum(capacity), 0)::bigint,
    coalesce(sum(member_cnt), 0)::bigint,
    coalesce(sum(released_capacity), 0)::bigint,
    coalesce(sum(guest_cnt), 0)::bigint,
    coalesce(sum(released_capacity) - sum(guest_cnt), 0)::bigint,
    coalesce(sum(capacity) - sum(member_cnt) - sum(guest_cnt), 0)::bigint
  from s;
end;
$$;

-- get_membership_member_counts (was 0146_membership_member_counts_registered.sql)
create or replace function get_membership_member_counts(
  p_facility_id uuid,
  p_start_date date,
  p_end_date date,
  p_facility_sport_ids uuid[] default null
) returns table (as_of date, total_members bigint, active_members bigint, inactive_members bigint)
language plpgsql
stable
as $$
declare
  tz text;
  asof date;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_MEMBERSHIPS_VIEW', 'MEMBERSHIPS_VIEW', 'MEMBERSHIP_SESSIONS_VIEW', 'REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if p_start_date is null or p_end_date is null or p_end_date < p_start_date then
    raise exception 'A custom date range requires a valid start and end date.' using errcode = '22023';
  end if;
  tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');
  asof := least(p_end_date, (now() at time zone tz)::date);

  return query
  with scoped as (
    select m.member_id,
           (m.status <> 'cancelled' and m.end_date >= asof) as covers
      from memberships m
     where m.facility_id = p_facility_id
       and (
             ((m.created_at at time zone tz)::date between p_start_date and p_end_date)
          or (m.start_date <= p_end_date and m.end_date >= p_start_date)
       )
       and membership_in_sports(m.id, p_facility_sport_ids)
  ), people as (
    select member_id, bool_or(covers) as active from scoped group by member_id
  )
  select asof,
         count(*)::bigint,
         (count(*) filter (where active))::bigint,
         (count(*) filter (where not active))::bigint
    from people;
end;
$$;

-- get_membership_batch_breakdown (was 0147_membership_batch_breakdown.sql)
create or replace function get_membership_batch_breakdown(
  p_facility_id uuid,
  p_start_date date,
  p_end_date date,
  p_facility_sport_ids uuid[] default null
) returns table (
  facility_sport_id uuid,
  sport_name text,
  court_id uuid,
  court_name text,
  batch_id uuid,
  batch_name text,
  days_of_week smallint[],
  start_time time,
  end_time time,
  capacity integer,
  members bigint,
  active_members bigint,
  court_members bigint,
  sport_members bigint
)
language plpgsql
stable
as $$
declare
  tz text;
  asof date;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_MEMBERSHIPS_VIEW', 'MEMBERSHIPS_VIEW', 'MEMBERSHIP_SESSIONS_VIEW', 'REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if p_start_date is null or p_end_date is null or p_end_date < p_start_date then
    raise exception 'A custom date range requires a valid start and end date.' using errcode = '22023';
  end if;
  tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');
  asof := least(p_end_date, (now() at time zone tz)::date);

  return query
  with rel as (
    select m.member_id, (m.status <> 'cancelled' and m.end_date >= asof) as covers
      from memberships m
     where m.facility_id = p_facility_id
       and (((m.created_at at time zone tz)::date between p_start_date and p_end_date)
            or (m.start_date <= p_end_date and m.end_date >= p_start_date))
  ), rel_member as (
    select r.member_id, bool_or(r.covers) as active from rel r group by r.member_id
  ), batches as (
    select mb.id as bid, mb.facility_sport_id as fsid, coalesce(fs.custom_sport_name, sp.name) as sname,
           mb.court_id as cid, c.name as cname, mb.name as bname, mb.days_of_week as dows,
           mb.start_time as st, mb.end_time as et, mb.capacity as cap
      from membership_batches mb
      join courts c on c.id = mb.court_id
      join facility_sports fs on fs.id = mb.facility_sport_id
      join sports sp on sp.id = fs.sport_id
     where mb.facility_id = p_facility_id
       and mb.status in ('ACTIVE', 'EXPIRED')
       and mb.start_date <= p_end_date
       and (mb.end_date is null or mb.end_date >= p_start_date)
       and (p_facility_sport_ids is null or mb.facility_sport_id = any (p_facility_sport_ids))
  ), roster as (
    select bm.batch_id as bid, bm.member_id, rm.active
      from membership_batch_members bm
      join batches b on b.bid = bm.batch_id
      join rel_member rm on rm.member_id = bm.member_id
  ), rows_ as (
    select b.fsid, b.sname, b.cid, b.cname, b.bid, b.bname, b.dows, b.st, b.et, b.cap,
           (select count(distinct r.member_id) from roster r where r.bid = b.bid)::bigint as m_all,
           (select count(distinct r.member_id) from roster r where r.bid = b.bid and r.active)::bigint as m_active,
           (select count(distinct r.member_id) from roster r join batches b2 on b2.bid = r.bid where b2.cid = b.cid)::bigint as m_court,
           (select count(distinct r.member_id) from roster r join batches b2 on b2.bid = r.bid where b2.fsid = b.fsid)::bigint as m_sport,
           0 as ord
      from batches b
    union all
    select null::uuid, 'Not assigned to a session'::text, null::uuid, null::text, null::uuid, null::text, null::smallint[],
           null::time, null::time, null::integer,
           (select count(*) from rel_member rm where not exists (select 1 from membership_batch_members bm where bm.member_id = rm.member_id))::bigint,
           (select count(*) from rel_member rm where rm.active and not exists (select 1 from membership_batch_members bm where bm.member_id = rm.member_id))::bigint,
           0::bigint, 0::bigint, 1
     where p_facility_sport_ids is null
       and exists (select 1 from rel_member rm where not exists (select 1 from membership_batch_members bm where bm.member_id = rm.member_id))
  )
  select x.fsid, x.sname, x.cid, x.cname, x.bid, x.bname, x.dows, x.st, x.et, x.cap, x.m_all, x.m_active, x.m_court, x.m_sport
    from rows_ x
   order by x.ord, x.sname, x.cname, x.st;
end;
$$;

-- get_guest_booking_analytics (was 0151_guest_booking_completed_by_time.sql)
create or replace function get_guest_booking_analytics(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  total bigint,
  completed bigint,
  confirmed bigint,
  pending bigint,
  cancelled bigint,
  revenue_minor bigint,
  avg_booking_value_minor bigint,
  collected_minor bigint,
  outstanding_minor bigint,
  collection_rate_pct numeric
)
language plpgsql
stable
as $$
#variable_conflict use_column
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_GUESTS_VIEW', 'GUEST_BOOKINGS_VIEW', 'REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with gb as (
    select
      b.id,
      b.status::text as status,
      b.end_time,
      coalesce(b.amount_minor, 0) as amount_minor,
      b.payment_status,
      coalesce((
        select sum(p.amount_inr) * 100 from payments p where p.booking_id = b.id and p.status = 'paid'
      ), 0)::bigint as collected_minor
    from bookings b
    where b.facility_id = p_facility_id
      and b.customer_type = 'GUEST'
      and range_ @> b.start_time
      and (p_facility_sport_id is null or b.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or b.facility_sport_id = any (p_facility_sport_ids))
      and (p_court_id is null or b.court_id = p_court_id)
  ),
  agg as (
    select
      count(*) as total,
      count(*) filter (where gb.status <> 'cancelled' and (gb.status = 'completed' or gb.end_time <= now())) as completed,
      count(*) filter (where gb.status = 'confirmed' and gb.end_time > now()) as confirmed,
      count(*) filter (where gb.status = 'pending' and gb.end_time > now()) as pending,
      count(*) filter (where gb.status = 'cancelled') as cancelled,
      coalesce(sum(gb.collected_minor), 0) as collected,
      coalesce(sum(gb.amount_minor) filter (
        where gb.payment_status = 'PAID' and gb.status <> 'cancelled'
      ), 0) as paid_value,
      count(*) filter (where gb.payment_status = 'PAID' and gb.status <> 'cancelled') as paid_count,
      coalesce(sum(greatest(gb.amount_minor - gb.collected_minor, 0)) filter (where gb.status <> 'cancelled'), 0) as outstanding
    from gb
  )
  select
    agg.total::bigint,
    agg.completed::bigint,
    agg.confirmed::bigint,
    agg.pending::bigint,
    agg.cancelled::bigint,
    agg.collected::bigint,
    case when agg.paid_count > 0 then round(agg.paid_value / agg.paid_count)::bigint else 0 end,
    agg.collected::bigint,
    agg.outstanding::bigint,
    case when (agg.collected + agg.outstanding) > 0
      then round((agg.collected::numeric / (agg.collected + agg.outstanding)) * 100, 1)
      else 0 end
  from agg;
end;
$$;

-- get_guest_bookings_by_court (was 0150_court_removal_integrity.sql)
create or replace function get_guest_bookings_by_court(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  court_id uuid,
  court_name text,
  sport_name text,
  booking_count bigint,
  revenue_minor bigint
)
language plpgsql
stable
as $$
#variable_conflict use_column
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_GUESTS_VIEW', 'GUEST_BOOKINGS_VIEW', 'REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  with gb as (
    select
      b.court_id,
      coalesce((
        select sum(p.amount_inr) * 100 from payments p where p.booking_id = b.id and p.status = 'paid'
      ), 0)::bigint as collected_minor
    from bookings b
    where b.facility_id = p_facility_id
      and b.customer_type = 'GUEST'
      and range_ @> b.start_time
  )
  select
    c.id,
    c.name,
    coalesce(fs.custom_sport_name, sp.name),
    count(gb.court_id)::bigint,
    coalesce(sum(gb.collected_minor), 0)::bigint
  from courts c
  join facility_sports fs on fs.id = c.facility_sport_id
  join sports sp on sp.id = fs.sport_id
  left join gb on gb.court_id = c.id
  where c.facility_id = p_facility_id
    -- A removed court stays in the figures for the period it earned in, so the rows still add up to the total.
    and (not c.archived or exists (select 1 from gb h where h.court_id = c.id))
    and (p_facility_sport_id is null or c.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or c.facility_sport_id = any (p_facility_sport_ids))
    and (p_court_id is null or c.id = p_court_id)
  group by c.id, c.name, coalesce(fs.custom_sport_name, sp.name)
  order by count(gb.court_id) desc, c.name;
end;
$$;

