-- get_guest_release_analytics (was 0138_reports_sport_scope.sql)
create or replace function get_guest_release_analytics(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_facility_sport_ids uuid[] default null
) returns table (
  released bigint,
  booked bigint,
  remaining bigint,
  revenue_minor bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  start_d date;
  end_d date;
  v_released bigint;
  v_booked bigint;
  v_rev bigint;
begin
  perform require_page_access_any(p_facility_id, array['REPORT_GUESTS_VIEW', 'GUEST_BOOKINGS_VIEW', 'REPORT_OVERVIEW_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  select coalesce(timezone, 'Asia/Kolkata') into tz from facilities where id = p_facility_id;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);
  start_d := (lower(range_) at time zone tz)::date;
  end_d := ((upper(range_) - interval '1 microsecond') at time zone tz)::date;

  select
    coalesce(sum(ms.released_capacity), 0),
    coalesce(sum((
      select count(*) from membership_session_bookings b
      where b.session_id = ms.id and b.participant_type = 'GUEST' and b.status = 'CONFIRMED'
    )), 0)
  into v_released, v_booked
  from membership_sessions ms
  where ms.facility_id = p_facility_id
    and ms.session_date >= start_d
    and ms.session_date <= end_d
    and (p_facility_sport_id is null or ms.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or ms.facility_sport_id = any (p_facility_sport_ids))
    and (p_court_id is null or ms.court_id = p_court_id);

  select coalesce(sum(p.amount_inr), 0) * 100
  into v_rev
  from payments p
  join membership_session_bookings msb on msb.id = p.membership_session_booking_id
  join membership_sessions ms on ms.id = msb.session_id
  where p.facility_id = p_facility_id
    and p.status = 'paid'
    and range_ @> coalesce(p.paid_at, p.created_at)
    and (p_facility_sport_id is null or ms.facility_sport_id = p_facility_sport_id)
      and (p_facility_sport_ids is null or ms.facility_sport_id = any (p_facility_sport_ids))
    and (p_court_id is null or ms.court_id = p_court_id);

  return query select
    v_released::bigint,
    v_booked::bigint,
    greatest(v_released - v_booked, 0)::bigint,
    v_rev::bigint;
end;
$$;

-- list_finance_transactions (was 0137_finance_sport_scope.sql)
create or replace function list_finance_transactions(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_source_type text default null,
  p_status text default null,
  p_search text default null,
  p_limit integer default 20,
  p_offset integer default 0,
  p_facility_sport_ids uuid[] default null
) returns setof finance_transactions_view
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_TRANSACTIONS_VIEW', 'FINANCE_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);

  return query
  select v.* from finance_transactions_view v
  where v.facility_id = p_facility_id
    and range_ @> v.effective_at
    and payment_in_sports(v.id, p_facility_sport_ids)
    and (p_source_type is null or v.source_type = p_source_type)
    and (p_status is null or v.status = p_status)
    and (
      p_search is null or trim(p_search) = ''
      or v.reference ilike '%' || p_search || '%'
      or v.id::text ilike '%' || p_search || '%'
      or v.razorpay_payment_id ilike '%' || p_search || '%'
      or v.razorpay_order_id ilike '%' || p_search || '%'
      or (v.booking_id is not null and v.booking_id::text = p_search)
      or (v.membership_id is not null and v.membership_id::text = p_search)
      or v.customer_name ilike '%' || p_search || '%'
    )
  order by v.effective_at desc
  limit greatest(1, least(p_limit, 100))
  offset greatest(0, p_offset);
end;
$$;

