-- list_finance_ledger (was 0137_finance_sport_scope.sql)
create or replace function list_finance_ledger(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_txn_type text default null,
  p_category text default null,
  p_payment_method text default null,
  p_status text default null,
  p_search text default null,
  p_limit integer default 10,
  p_offset integer default 0,
  p_facility_sport_ids uuid[] default null
)
returns table (
  id uuid,
  reference text,
  occurred_at timestamptz,
  description text,
  category text,
  txn_type text,
  payment_method text,
  amount_minor bigint,
  currency text,
  status text,
  source_type text,
  booking_id uuid,
  membership_id uuid,
  expense_id uuid,
  total_count bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
  cur text;
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_TRANSACTIONS_VIEW', 'FINANCE_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);
  select coalesce(f.timezone, 'Asia/Kolkata'), coalesce(f.currency, 'INR')
    into tz, cur
    from facilities f where f.id = p_facility_id;

  return query
  with ledger as (
    select
      v.id,
      v.reference,
      v.effective_at as occurred_at,
      trim(
        initcap(replace(v.source_type, '_', ' '))
        || coalesce(' — ' || v.customer_name, '')
      ) as description,
      case v.source_type
        when 'GUEST_BOOKING' then 'Guest Booking Revenue'
        when 'MEMBERSHIP' then 'Membership Revenue'
        when 'MEMBER_BOOKING' then 'Court Booking Revenue'
        when 'COACHING' then 'Coaching Revenue'
        else 'Other Revenue'
      end as category,
      'INCOME'::text as txn_type,
      v.payment_method,
      v.amount_minor::bigint,
      v.currency,
      v.status,
      v.source_type,
      v.booking_id,
      v.membership_id,
      null::uuid as expense_id
    from finance_transactions_view v
    where v.facility_id = p_facility_id
      and payment_in_sports(v.id, p_facility_sport_ids)

    union all

    select
      r.id,
      'RFD-' || upper(substr(r.id::text, 1, 8)),
      r.processed_at,
      'Refund'::text,
      'Booking Refund'::text,
      'REFUND'::text,
      null::text,
      r.amount_minor::bigint,
      cur,
      lower(r.status::text),
      'REFUND'::text,
      null::uuid,
      null::uuid,
      null::uuid
    from refunds r
    where r.facility_id = p_facility_id
      and r.status = 'PROCESSED'
      and r.processed_at is not null
      and payment_order_in_sports(r.payment_order_id, p_facility_sport_ids)

    union all

    select
      e.id,
      'EXP-' || upper(substr(e.id::text, 1, 8)),
      (e.spent_on::timestamp at time zone tz),
      trim(coalesce(e.vendor, c.name) || coalesce(' — ' || e.notes, '')),
      c.name,
      'EXPENSE'::text,
      e.payment_method,
      e.amount_minor::bigint,
      e.currency,
      case e.payment_status when 'PAID' then 'paid' when 'PARTIAL' then 'partial' else 'pending' end,
      'EXPENSE'::text,
      null::uuid,
      null::uuid,
      e.id
    from expenses e
    join expense_categories c on c.id = e.category_id
    where e.facility_id = p_facility_id
      and e.status = 'RECORDED'
      -- expenses are not tied to a sport: left out while a sport is selected
      and p_facility_sport_ids is null
  ),
  filtered as (
    select * from ledger l
    where range_ @> l.occurred_at
      and (p_txn_type is null or l.txn_type = p_txn_type)
      and (p_category is null or l.category = p_category)
      and (p_payment_method is null or l.payment_method = p_payment_method)
      and (p_status is null or l.status = p_status)
      and (
        p_search is null or trim(p_search) = ''
        or l.reference ilike '%' || trim(p_search) || '%'
        or l.description ilike '%' || trim(p_search) || '%'
        or l.category ilike '%' || trim(p_search) || '%'
      )
  )
  select f.*, count(*) over () as total_count
  from filtered f
  order by f.occurred_at desc
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- list_finance_payment_methods (was 0049_finance_ledger.sql)
create or replace function list_finance_payment_methods(p_facility_id uuid)
returns table (payment_method text)
language plpgsql
stable
as $$
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_TRANSACTIONS_VIEW', 'FINANCE_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;

  return query
  select distinct m.payment_method from (
    select p.payment_method from payments p
     where p.facility_id = p_facility_id and p.payment_method is not null
    union
    select e.payment_method from expenses e
     where e.facility_id = p_facility_id and e.payment_method is not null
  ) m
  where trim(m.payment_method) <> ''
  order by 1;
end;
$$;

-- list_pending_payments (was 0137_finance_sport_scope.sql)
create or replace function list_pending_payments(
  p_facility_id uuid,
  p_search text default null,
  p_source_type text default null,
  p_status text default 'ALL_OUTSTANDING',
  p_from date default null,
  p_to date default null,
  p_sort text default 'DUE_DATE',
  p_limit integer default 20,
  p_offset integer default 0,
  p_source_id uuid default null,
  p_facility_sport_ids uuid[] default null
)
returns table (
  source_type text,
  source_id uuid,
  reference text,
  customer_name text,
  customer_phone text,
  description text,
  facility_name text,
  court_name text,
  starts_at timestamptz,
  ends_at timestamptz,
  total_minor bigint,
  paid_minor bigint,
  outstanding_minor bigint,
  status text,
  payment_method text,
  due_on date,
  total_count bigint
)
language plpgsql
stable
as $$
declare
  tz text;
  fac_name text;
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_PAYMENTS_VIEW', 'FINANCE_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  select coalesce(f.timezone, 'Asia/Kolkata'), f.name
    into tz, fac_name
    from facilities f where f.id = p_facility_id;

  return query
  with obligations as (
    select
      case when b.customer_type = 'GUEST' then 'GUEST_BOOKING' else 'BOOKING' end as source_type,
      b.id as source_id,
      'BOOK-' || upper(substr(replace(b.id::text, '-', ''), 1, 6)) as reference,
      coalesce(b.guest_name, mem.full_name, 'Guest') as customer_name,
      coalesce(b.guest_phone, mem.phone) as customer_phone,
      concat_ws(' • ', c.name, to_char(b.start_time at time zone tz, 'DD Mon • HH12:MI AM')) as description,
      fac_name as facility_name,
      c.name as court_name,
      b.start_time as starts_at,
      b.end_time as ends_at,
      coalesce(b.amount_minor, 0)::bigint as total_minor,
      greatest(
        coalesce((
          select sum(p.amount_inr) * 100 from payments p
          where p.booking_id = b.id and p.status = 'paid'
        ), 0),
        case when b.payment_status = 'PAID' then coalesce(b.amount_minor, 0) else 0 end
      )::bigint as paid_minor,
      b.payment_method,
      (b.start_time at time zone tz)::date as due_on
    from bookings b
    left join courts c on c.id = b.court_id
    left join members mem on mem.id = b.member_id
    where b.facility_id = p_facility_id
      and b.status in ('pending', 'confirmed', 'completed')

    union all

    select
      'MEMBERSHIP',
      ms.id,
      'MEM-' || upper(substr(replace(ms.id::text, '-', ''), 1, 6)),
      coalesce(mem2.full_name, 'Member'),
      mem2.phone,
      coalesce(ms.name, mp.name, 'Membership'),
      fac_name,
      null::text,
      null::timestamptz,
      null::timestamptz,
      (coalesce(ms.total_amount_inr, 0) * 100)::bigint,
      coalesce((
        select sum(p.amount_inr) * 100 from payments p
        where p.membership_id = ms.id and p.status = 'paid'
      ), 0)::bigint,
      null::text,
      -- A running AutoPay that has already collected a charge is next due on its current period's end, not on the
      -- day the membership started; otherwise the start date, as before.
      coalesce(
        (
          select s.current_end
          from membership_subscriptions s
          where s.membership_id = ms.id
            and s.status::text in ('created', 'authenticated', 'active', 'pending')
            and s.charge_count > 0
            and s.current_end is not null
        ),
        ms.start_date
      )
    from memberships ms
    left join members mem2 on mem2.id = ms.member_id
    left join membership_plans mp on mp.id = ms.plan_id
    where ms.facility_id = p_facility_id
      and ms.status <> 'cancelled'

    union all

    -- Coaching enrollments. Cancelled ones are not owed; a zero-priced
    -- (membership-included) enrollment falls out at `total_minor > 0`.
    select
      'COACHING_ENROLLMENT',
      e.id,
      'COACH-' || upper(substr(replace(e.id::text, '-', ''), 1, 6)),
      coalesce(mem3.full_name, 'Member'),
      mem3.phone,
      concat_ws(' • ', cp.name, 'from ' || to_char(e.start_date, 'DD Mon')),
      fac_name,
      null::text,
      null::timestamptz,
      null::timestamptz,
      coalesce(e.price_minor, 0)::bigint,
      coalesce((
        select sum(p.amount_inr) * 100 from payments p
        where p.coaching_enrollment_id = e.id and p.status = 'paid'
      ), 0)::bigint,
      null::text,
      -- Same rule for a monthly coaching subscription: once the first charge is collected, the next due date is
      -- the subscription's current period end (e.g. paid 18 Oct -> next due 17 Nov), not the enrollment start.
      coalesce(
        (
          select b.current_end
          from coaching_enrollment_billing b
          where b.enrollment_id = e.id
            and b.kind = 'SUBSCRIPTION'
            and b.status in ('CREATED', 'AUTHENTICATED', 'ACTIVE', 'PENDING')
            and b.charge_count > 0
            and b.current_end is not null
        ),
        e.start_date
      )
    from coaching_enrollments e
    left join members mem3 on mem3.id = e.member_id
    left join coaching_programs cp on cp.id = e.program_id
    where e.facility_id = p_facility_id
      and e.status <> 'CANCELLED'
  ),
  scored as (
    select
      o.*,
      (o.total_minor - o.paid_minor) as outstanding_minor,
      case
        when o.paid_minor >= o.total_minor then 'PAID'
        when o.paid_minor > 0 then 'PARTIALLY_PAID'
        else 'PENDING'
      end as settle_status
    from obligations o
    where o.total_minor > 0
  ),
  filtered as (
    select
      s.*,
      (s.settle_status <> 'PAID' and s.due_on < (now() at time zone tz)::date) as is_overdue
    from scored s
    where
      (p_source_id is not null and s.source_id = p_source_id)
      or (
        p_source_id is null
        and case coalesce(p_status, 'ALL_OUTSTANDING')
          when 'PAID' then s.settle_status = 'PAID'
          when 'PENDING' then s.settle_status = 'PENDING'
          when 'PARTIALLY_PAID' then s.settle_status = 'PARTIALLY_PAID'
          when 'OVERDUE' then s.settle_status <> 'PAID' and s.due_on < (now() at time zone tz)::date
          else s.settle_status <> 'PAID'
        end
        and (p_source_type is null or s.source_type = p_source_type)
        and obligation_in_sports(s.source_type, s.source_id, p_facility_sport_ids)
        and (p_from is null or s.due_on >= p_from)
        and (p_to is null or s.due_on <= p_to)
        and (
          p_search is null or trim(p_search) = ''
          or s.customer_name ilike '%' || trim(p_search) || '%'
          or s.customer_phone ilike '%' || trim(p_search) || '%'
          or s.reference ilike '%' || trim(p_search) || '%'
          or s.description ilike '%' || trim(p_search) || '%'
        )
      )
  )
  select
    f.source_type,
    f.source_id,
    f.reference,
    f.customer_name,
    f.customer_phone,
    f.description,
    f.facility_name,
    f.court_name,
    f.starts_at,
    f.ends_at,
    f.total_minor,
    f.paid_minor,
    f.outstanding_minor,
    case when f.is_overdue then 'OVERDUE' else f.settle_status end,
    f.payment_method,
    f.due_on,
    count(*) over () as total_count
  from filtered f
  order by
    case when p_sort = 'AMOUNT' then f.outstanding_minor end desc nulls last,
    case when p_sort = 'CUSTOMER' then f.customer_name end asc nulls last,
    case when p_sort = 'NEWEST' then f.due_on end desc nulls last,
    f.due_on asc
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- get_pending_payments_summary (was 0137_finance_sport_scope.sql)
create or replace function get_pending_payments_summary(
  p_facility_id uuid,
  p_from date default null,
  p_to date default null,
  p_facility_sport_ids uuid[] default null
)
returns table (
  outstanding_minor bigint,
  pending_minor bigint,
  partially_paid_minor bigint,
  overdue_minor bigint,
  obligation_count bigint
)
language plpgsql
stable
as $$
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_PAYMENTS_VIEW', 'FINANCE_VIEW', 'DASHBOARD_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;

  return query
  with rows as (
    select * from list_pending_payments(
      p_facility_id, null, null, 'ALL_OUTSTANDING', p_from, p_to, 'DUE_DATE', 100000, 0, null, p_facility_sport_ids
    )
  )
  select
    coalesce(sum(r.outstanding_minor), 0)::bigint,
    coalesce(sum(r.outstanding_minor) filter (where r.status = 'PENDING'), 0)::bigint,
    coalesce(sum(r.outstanding_minor) filter (where r.status = 'PARTIALLY_PAID'), 0)::bigint,
    coalesce(sum(r.outstanding_minor) filter (where r.status = 'OVERDUE'), 0)::bigint,
    count(*)::bigint
  from rows r;
end;
$$;

-- list_expenses (was 0069_finance_expense_payments.sql)
create or replace function list_expenses(
  p_facility_id uuid,
  p_preset text default null,
  p_start_date date default null,
  p_end_date date default null,
  p_category_id uuid default null,
  p_limit integer default 25,
  p_offset integer default 0,
  p_search text default null,
  p_payment_status text default null,
  p_payment_method text default null,
  p_vendor text default null,
  p_min_minor integer default null,
  p_max_minor integer default null,
  p_include_void boolean default true
)
returns table (
  id uuid,
  category_id uuid,
  category_name text,
  amount_minor integer,
  amount_paid_minor integer,
  currency text,
  payment_method text,
  payment_status text,
  spent_on date,
  due_on date,
  vendor text,
  reference text,
  notes text,
  receipt_path text,
  status text,
  created_by_name text,
  created_at timestamptz,
  total_count bigint
)
language plpgsql
stable
as $$
declare
  range_ tstzrange;
  tz text;
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_EXPENSES_VIEW', 'FINANCE_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, coalesce(p_preset, 'THIS_MONTH'), p_start_date, p_end_date);
  tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');

  return query
  with rows as (
    select e.id, e.category_id, c.name as category_name, e.amount_minor, e.amount_paid_minor,
           e.currency, e.payment_method, e.payment_status, e.spent_on, e.due_on, e.vendor,
           e.reference, e.notes, e.receipt_path, e.status, pr.full_name as created_by_name, e.created_at
    from expenses e
    join expense_categories c on c.id = e.category_id
    left join profiles pr on pr.id = e.created_by
    where e.facility_id = p_facility_id
      and range_ @> (e.spent_on::timestamp at time zone tz)
      and (p_category_id is null or e.category_id = p_category_id)
      and (p_include_void or e.status = 'RECORDED')
      and (p_payment_status is null or e.payment_status = p_payment_status)
      and (p_payment_method is null or e.payment_method = p_payment_method)
      and (p_vendor is null or e.vendor ilike '%' || trim(p_vendor) || '%')
      and (p_min_minor is null or e.amount_minor >= p_min_minor)
      and (p_max_minor is null or e.amount_minor <= p_max_minor)
      and (
        p_search is null or trim(p_search) = ''
        or e.vendor ilike '%' || trim(p_search) || '%'
        or e.reference ilike '%' || trim(p_search) || '%'
        or e.notes ilike '%' || trim(p_search) || '%'
        or c.name ilike '%' || trim(p_search) || '%'
      )
  )
  select r.*, count(*) over () as total_count
  from rows r
  order by r.spent_on desc, r.created_at desc
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- list_daily_closings (was 0070_finance_daily_closing.sql)
create or replace function list_daily_closings(
  p_facility_id uuid,
  p_preset text default 'THIS_MONTH',
  p_start_date date default null,
  p_end_date date default null,
  p_limit integer default 60,
  p_offset integer default 0
)
returns table (
  id uuid,
  closing_date date,
  opening_cash_minor integer,
  total_collected_minor integer,
  total_expense_minor integer,
  expected_cash_minor integer,
  actual_cash_minor integer,
  variance_minor integer,
  status text,
  closed_at timestamptz,
  closed_by_name text,
  total_count bigint
)
language plpgsql
stable
as $$
declare
  tz text;
  d0 date;
  d1 date;
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_CLOSING_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');
  if p_preset = 'CUSTOM' then
    d0 := p_start_date; d1 := p_end_date;
  else
    d0 := lower(resolve_finance_date_range(p_facility_id, coalesce(p_preset, 'THIS_MONTH'), null, null)) at time zone tz;
    d1 := (upper(resolve_finance_date_range(p_facility_id, coalesce(p_preset, 'THIS_MONTH'), null, null)) at time zone tz)::date - 1;
  end if;

  return query
  with rows as (
    select d.id, d.closing_date, d.opening_cash_minor, d.total_collected_minor,
           d.total_expense_minor, d.expected_cash_minor, d.actual_cash_minor,
           d.variance_minor, d.status, d.closed_at, pr.full_name as closed_by_name
    from daily_closings d
    left join profiles pr on pr.id = d.closed_by
    where d.facility_id = p_facility_id
      and (d0 is null or d.closing_date >= d0)
      and (d1 is null or d.closing_date <= d1)
  )
  select r.*, count(*) over () as total_count
  from rows r
  order by r.closing_date desc
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- get_daily_closing_summary (was 0070_finance_daily_closing.sql)
create or replace function get_daily_closing_summary(
  p_facility_id uuid,
  p_date date default null
)
returns table (
  closing_date date,
  opening_cash_minor bigint,
  cash_collected_minor bigint,
  upi_collected_minor bigint,
  card_collected_minor bigint,
  online_collected_minor bigint,
  bank_transfer_collected_minor bigint,
  other_collected_minor bigint,
  total_collected_minor bigint,
  cash_expense_minor bigint,
  other_expense_minor bigint,
  total_expense_minor bigint,
  expected_cash_minor bigint,
  payment_count bigint,
  expense_count bigint,
  pending_payment_count bigint,
  closing_id uuid,
  status text,
  actual_cash_minor bigint,
  variance_minor bigint,
  variance_reason text,
  closed_at timestamptz
)
language plpgsql
stable
as $$
declare
  tz text;
  the_date date;
  day_range tstzrange;
  prior_close integer;
  existing daily_closings;
begin
  perform require_page_access_any(p_facility_id, array['FINANCE_CLOSING_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;

  tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');
  the_date := coalesce(p_date, (now() at time zone tz)::date);
  day_range := tstzrange(
    the_date::timestamp at time zone tz,
    (the_date + 1)::timestamp at time zone tz, '[)');

  select * into existing from daily_closings d
    where d.facility_id = p_facility_id and d.closing_date = the_date;

  -- Opening cash: an explicit value on the existing row wins; otherwise the
  -- most recent closed day's counted drawer; otherwise zero.
  select dc.actual_cash_minor into prior_close
    from daily_closings dc
    where dc.facility_id = p_facility_id
      and dc.closing_date < the_date
      and dc.status in ('CLOSED', 'REOPENED')
      and dc.actual_cash_minor is not null
    order by dc.closing_date desc
    limit 1;

  return query
  with pay as (
    select finance_method_bucket(p.payment_method) as bucket, (p.amount_inr * 100)::bigint as amt
    from payments p
    where p.facility_id = p_facility_id and p.status = 'paid'
      and day_range @> coalesce(p.paid_at, p.created_at)
  ),
  pay_agg as (
    select
      coalesce(sum(amt) filter (where bucket = 'CASH'), 0)::bigint as cash,
      coalesce(sum(amt) filter (where bucket = 'UPI'), 0)::bigint as upi,
      coalesce(sum(amt) filter (where bucket = 'CARD'), 0)::bigint as card,
      coalesce(sum(amt) filter (where bucket = 'ONLINE'), 0)::bigint as online,
      coalesce(sum(amt) filter (where bucket = 'BANK_TRANSFER'), 0)::bigint as bank,
      coalesce(sum(amt) filter (where bucket = 'OTHER'), 0)::bigint as other,
      coalesce(sum(amt), 0)::bigint as total,
      count(*)::bigint as cnt
    from pay
  ),
  exp as (
    select
      coalesce(sum(ep.amount_minor) filter (where finance_method_bucket(ep.payment_method) = 'CASH'), 0)::bigint as cash_exp,
      coalesce(sum(ep.amount_minor), 0)::bigint as total_exp,
      count(distinct ep.expense_id)::bigint as cnt
    from expense_payments ep
    join expenses e on e.id = ep.expense_id
    where ep.facility_id = p_facility_id and e.status = 'RECORDED'
      and ep.paid_on = the_date
  ),
  pend as (
    select count(*)::bigint as cnt
    from bookings b
    where b.facility_id = p_facility_id
      and b.status in ('pending', 'confirmed', 'completed')
      and b.payment_status <> 'PAID'
      and day_range @> b.start_time
  )
  select
    the_date,
    coalesce(existing.opening_cash_minor, prior_close, 0)::bigint,
    pay_agg.cash, pay_agg.upi, pay_agg.card, pay_agg.online, pay_agg.bank, pay_agg.other,
    pay_agg.total,
    exp.cash_exp,
    (exp.total_exp - exp.cash_exp)::bigint,
    exp.total_exp,
    (coalesce(existing.opening_cash_minor, prior_close, 0) + pay_agg.cash - exp.cash_exp)::bigint,
    pay_agg.cnt,
    exp.cnt,
    pend.cnt,
    existing.id,
    coalesce(existing.status, 'NOT_STARTED'),
    existing.actual_cash_minor::bigint,
    existing.variance_minor::bigint,
    existing.variance_reason,
    existing.closed_at
  from pay_agg, exp, pend;
end;
$$;

-- list_refunds (was 0024_finance.sql)
create or replace function list_refunds(
  p_facility_id uuid,
  p_status text default null,
  p_source_type text default null,
  p_preset text default null,
  p_start_date date default null,
  p_end_date date default null,
  p_limit integer default 100,
  p_offset integer default 0
) returns setof refunds
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REFUNDS_VIEW', 'FINANCE_VIEW']);
  if p_preset is not null then
    range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);
  end if;

  return query
  select * from refunds
  where facility_id = p_facility_id
    and (p_status is null or status::text = p_status)
    and (p_source_type is null or source_type::text = p_source_type)
    and (range_ is null or range_ @> created_at)
  order by created_at desc
  limit greatest(1, least(p_limit, 200))
  offset greatest(0, p_offset);
end;
$$;

-- list_settlement_exceptions (was 0024_finance.sql)
create or replace function list_settlement_exceptions(
  p_facility_id uuid,
  p_status text default 'OPEN',
  p_source_type text default null,
  p_preset text default null,
  p_start_date date default null,
  p_end_date date default null
) returns setof settlement_exceptions
language plpgsql
stable
as $$
declare
  range_ tstzrange;
begin
  perform require_page_access_any(p_facility_id, array['REFUNDS_VIEW', 'FINANCE_VIEW']);
  if p_preset is not null then
    range_ := resolve_finance_date_range(p_facility_id, p_preset, p_start_date, p_end_date);
  end if;

  return query
  select * from settlement_exceptions
  where facility_id = p_facility_id
    and (p_status is null or status = p_status)
    and (p_source_type is null or source_type::text = p_source_type)
    and (range_ is null or range_ @> created_at)
  order by created_at desc;
end;
$$;

-- get_finance_transaction (was 0024_finance.sql)
create or replace function get_finance_transaction(p_transaction_id uuid) returns finance_transactions_view
language plpgsql
stable
as $$
declare
  result finance_transactions_view;
begin
  perform require_page_access_any((select t.facility_id from finance_transactions_view t where t.id = p_transaction_id), array['FINANCE_TRANSACTIONS_VIEW', 'FINANCE_VIEW']);
  select * into result from finance_transactions_view where id = p_transaction_id;
  if result.id is null then
    raise exception 'Transaction not found.' using errcode = 'P0002';
  end if;
  if not has_facility_role(result.facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  return result;
end;
$$;

-- get_transaction_details (was 0085_coaching_finance.sql)
create or replace function get_transaction_details(p_transaction_id uuid)
returns jsonb
language plpgsql
stable
as $$
declare
  v finance_transactions_view;
  fac facilities;
  v_recorded_by text;
  v_booking_code text;
  v_description text;
  v_enrollment uuid;
begin
  perform require_page_access_any((select t.facility_id from finance_transactions_view t where t.id = p_transaction_id), array['FINANCE_TRANSACTIONS_VIEW', 'FINANCE_VIEW']);
  select * into v from finance_transactions_view where id = p_transaction_id;
  if v.id is null then
    raise exception 'Transaction not found.' using errcode = 'P0002';
  end if;
  if not has_facility_role(v.facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;

  select * into fac from facilities where id = v.facility_id;

  select pr.full_name, p.coaching_enrollment_id into v_recorded_by, v_enrollment
    from payments p left join profiles pr on pr.id = p.recorded_by
   where p.id = v.id;

  if v.booking_id is not null then
    select
      'BOOK-' || upper(substr(replace(b.id::text, '-', ''), 1, 6)),
      concat_ws(' ',
        case when b.customer_type = 'GUEST' then 'Guest booking' else 'Court booking' end,
        'payment for', c.name)
      into v_booking_code, v_description
      from bookings b
      left join courts c on c.id = b.court_id
     where b.id = v.booking_id;
  elsif v.membership_id is not null then
    select 'MEM-' || upper(substr(replace(ms.id::text, '-', ''), 1, 6)),
           concat_ws(' ', 'Membership payment —', coalesce(ms.name, mp.name, 'Membership'))
      into v_booking_code, v_description
      from memberships ms
      left join membership_plans mp on mp.id = ms.plan_id
     where ms.id = v.membership_id;
  elsif v_enrollment is not null then
    select 'COACH-' || upper(substr(replace(e.id::text, '-', ''), 1, 6)),
           concat_ws(' ', 'Coaching payment —', cp.name)
      into v_booking_code, v_description
      from coaching_enrollments e
      left join coaching_programs cp on cp.id = e.program_id
     where e.id = v_enrollment;
  end if;

  return jsonb_build_object(
    'id', v.id,
    'reference', v.reference,
    'sourceType', v.source_type,
    'category', case v.source_type
      when 'GUEST_BOOKING' then 'Guest Booking Revenue'
      when 'MEMBERSHIP' then 'Membership Revenue'
      when 'MEMBER_BOOKING' then 'Court Booking Revenue'
      when 'COACHING' then 'Coaching Revenue'
      else 'Other Revenue' end,
    'type', 'INCOME',
    'amountMinor', v.amount_minor,
    'currency', v.currency,
    'status', v.status,
    'paymentMethod', v.payment_method,
    'occurredAt', v.effective_at,
    'createdAt', v.created_at,
    'recordedBy', v_recorded_by,
    'description', coalesce(v_description, 'Payment'),
    'sourceReference', v_booking_code,
    'customerName', v.customer_name,
    'customerPhone', v.customer_phone,
    'facilityName', fac.name,
    'facilityId', v.facility_id,
    'bookingId', v.booking_id,
    'membershipId', v.membership_id,
    'coachingEnrollmentId', v_enrollment,
    'refundedMinor', v.refunded_minor,
    'netMinor', v.net_minor,
    'history', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id,
        'paidAt', coalesce(p.paid_at, p.created_at),
        'amountMinor', (p.amount_inr * 100),
        'paymentMethod', p.payment_method,
        'reference', p.reference,
        'status', p.status::text,
        'isThisOne', p.id = v.id
      ) order by coalesce(p.paid_at, p.created_at))
      from payments p
      where p.status = 'paid'
        and ((v.booking_id is not null and p.booking_id = v.booking_id)
          or (v.membership_id is not null and p.membership_id = v.membership_id)
          or (v_enrollment is not null and p.coaching_enrollment_id = v_enrollment)
          or (v.booking_id is null and v.membership_id is null and v_enrollment is null and p.id = v.id))
    ), '[]'::jsonb)
  );
end;
$$;

-- initiate_manual_refund (was 0023_cancellation_refunds.sql)
create or replace function initiate_manual_refund(
  p_payment_order_id uuid,
  p_amount_minor integer,
  p_reason refund_reason,
  p_override_reason text default null
) returns refunds
language plpgsql
as $$
declare
  po payment_orders;
  src_id uuid;
begin
  perform require_page_access_any((select t.facility_id from payment_orders t where t.id = p_payment_order_id), array['FINANCE_REFUND']);
  select * into po from payment_orders where id = p_payment_order_id;
  if po.id is null then
    raise exception 'Payment order not found.' using errcode = 'P0002';
  end if;
  src_id := coalesce(po.booking_id, po.membership_session_booking_id, po.member_id);
  return request_refund(po.id, p_amount_minor, p_reason, po.source_type, src_id, p_override_reason is not null, p_override_reason, null);
end;
$$;

-- request_refund (was 0023_cancellation_refunds.sql)
create or replace function request_refund(
  p_payment_order_id uuid,
  p_amount_minor integer,
  p_reason refund_reason,
  p_source_type payment_source_type,
  p_source_id uuid,
  p_is_override boolean default false,
  p_override_reason text default null,
  p_policy_percent_applied integer default null
) returns refunds
language plpgsql
as $$
declare
  po payment_orders;
  txn payments;
  max_refundable integer;
  result refunds;
begin
  perform require_page_access_any((select t.facility_id from payment_orders t where t.id = p_payment_order_id), array['FINANCE_REFUND']);
  select * into po from payment_orders where id = p_payment_order_id for update;
  if po.id is null then
    raise exception 'Payment order not found.' using errcode = 'P0002';
  end if;
  if po.status not in ('COMPLETED', 'SETTLEMENT_EXCEPTION', 'PARTIALLY_REFUNDED') then
    raise exception 'This payment is not eligible for a refund.' using errcode = '23514';
  end if;
  if po.razorpay_payment_id is null then
    raise exception 'This payment has no captured Razorpay payment to refund.' using errcode = '23514';
  end if;
  if p_amount_minor is null or p_amount_minor <= 0 then
    raise exception 'Refund amount must be positive.' using errcode = '23514';
  end if;

  max_refundable := refundable_amount(po.id);
  if p_amount_minor > max_refundable then
    raise exception 'The maximum refundable amount is %.', max_refundable using errcode = '23514';
  end if;

  select id into txn from payments where payment_order_id = po.id order by created_at desc limit 1;

  begin
    insert into refunds (
      facility_id, payment_order_id, transaction_id, source_type, source_id,
      razorpay_payment_id, amount_minor, currency, reason, status,
      initiated_by, is_override, override_reason, policy_percent_applied
    ) values (
      po.facility_id, po.id, txn.id, p_source_type, p_source_id,
      po.razorpay_payment_id, p_amount_minor, po.currency, p_reason, 'REQUESTED',
      auth.uid(), p_is_override, p_override_reason, p_policy_percent_applied
    ) returning * into result;
  exception when unique_violation then
    -- §41/§60: a second concurrent/duplicate request never creates a
    -- second refund — it safely observes the one already in flight.
    select * into result from refunds
      where payment_order_id = po.id and status in ('REQUESTED', 'PROCESSING', 'PENDING')
      order by created_at desc limit 1;
    return result;
  end;

  return result;
end;
$$;

-- get_maintenance_overview (was 0068_maintenance_module.sql)
create or replace function get_maintenance_overview(p_facility_id uuid) returns jsonb
language plpgsql
stable
as $$
declare
  month_start date := date_trunc('month', current_date)::date;
begin
  perform require_page_access_any(p_facility_id, array['MAINTENANCE_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'openIssues', (select count(*) from maintenance_tickets where facility_id = p_facility_id and status in ('REPORTED')),
    'inProgress', (select count(*) from maintenance_tickets where facility_id = p_facility_id and status = 'IN_PROGRESS'),
    'scheduled', (select count(*) from maintenance_tickets where facility_id = p_facility_id and status = 'SCHEDULED'),
    'resolvedThisMonth', (select count(*) from maintenance_tickets where facility_id = p_facility_id and status in ('RESOLVED', 'CLOSED') and resolved_at >= month_start),
    'courtsBlocked', (select count(distinct court_id) from maintenance_blocks where facility_id = p_facility_id and status = 'ACTIVE' and tstzrange(start_time, end_time) @> now()),
    'repairCostThisMonthMinor', coalesce((select sum(actual_cost_minor) from maintenance_tickets where facility_id = p_facility_id and actual_cost_minor is not null and reported_at >= month_start), 0),
    'courtStatus', coalesce((select jsonb_agg(jsonb_build_object('courtId', s.court_id, 'courtName', s.court_name, 'sportName', s.sport_name, 'status', s.status)) from get_maintenance_court_status(p_facility_id) s), '[]'::jsonb),
    'recentTickets', coalesce((
      select jsonb_agg(jsonb_build_object(
        'ticketId', r.ticket_id, 'code', r.code, 'courtName', r.court_name, 'title', r.title,
        'priority', r.priority, 'status', r.status, 'reportedAt', r.reported_at, 'assignedToName', r.assigned_to_name
      )) from list_maintenance_tickets(p_facility_id, null, null, null, null, null, null, null, null, null, 'NEWEST', 8, 0) r
    ), '[]'::jsonb),
    'upcomingSchedule', coalesce((
      select jsonb_agg(jsonb_build_object('ticketId', mb.ticket_id, 'courtName', c.name, 'title', t.title, 'startTime', mb.start_time, 'endTime', mb.end_time) order by mb.start_time)
      from maintenance_blocks mb join courts c on c.id = mb.court_id join maintenance_tickets t on t.id = mb.ticket_id
      where mb.facility_id = p_facility_id and mb.status = 'ACTIVE' and mb.end_time > now()
    ), '[]'::jsonb),
    'recentActivity', coalesce((
      select jsonb_agg(jsonb_build_object('id', e.id, 'ticketId', e.ticket_id, 'eventType', e.event_type, 'note', e.note, 'actorName', p.full_name, 'createdAt', e.created_at) order by e.created_at desc)
      from (select * from maintenance_ticket_activity where facility_id = p_facility_id order by created_at desc limit 8) e
      left join profiles p on p.id = e.actor_id
    ), '[]'::jsonb)
  );
end;
$$;

-- get_maintenance_court_status (was 0068_maintenance_module.sql)
create or replace function get_maintenance_court_status(p_facility_id uuid) returns table (
  court_id uuid, court_name text, sport_name text, status text
)
language plpgsql
stable
as $$
begin
  perform require_page_access_any(p_facility_id, array['MAINTENANCE_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;

  return query
  select
    c.id, c.name, coalesce(fs.custom_sport_name, sp.name),
    case
      when not c.booking_enabled or c.archived or c.status <> 'ACTIVE' then 'BLOCKED'
      when exists (select 1 from maintenance_blocks mb where mb.court_id = c.id and mb.status = 'ACTIVE' and tstzrange(mb.start_time, mb.end_time) @> now()) then 'UNDER_MAINTENANCE'
      when exists (select 1 from bookings b where b.court_id = c.id and b.status in ('pending', 'confirmed') and tstzrange(b.start_time, b.end_time) @> now()) then 'IN_USE'
      else 'AVAILABLE'
    end
  from courts c
  join facility_sports fs on fs.id = c.facility_sport_id
  join sports sp on sp.id = fs.sport_id
  where c.facility_id = p_facility_id and not c.archived
  order by c.display_order, c.name;
end;
$$;

-- list_maintenance_tickets (was 0068_maintenance_module.sql)
create or replace function list_maintenance_tickets(
  p_facility_id uuid,
  p_search text default null,
  p_status text default null,
  p_priority text default null,
  p_court_id uuid default null,
  p_facility_sport_id uuid default null,
  p_issue_category_id uuid default null,
  p_assigned_to uuid default null,
  p_from date default null,
  p_to date default null,
  p_sort text default 'NEWEST',
  p_limit integer default 20,
  p_offset integer default 0
) returns table (
  ticket_id uuid, code text, court_id uuid, court_name text, sport_name text,
  issue_category_id uuid, category_name text, title text, priority text, status text,
  reported_by_name text, assigned_to_name text, scheduled_start timestamptz,
  reported_at timestamptz, actual_cost_minor integer, estimated_cost_minor integer,
  total_count bigint
)
language plpgsql
stable
as $$
begin
  perform require_page_access_any(p_facility_id, array['MAINTENANCE_VIEW']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;

  return query
  select
    t.id, 'MT-' || upper(substr(replace(t.id::text, '-', ''), 1, 4)),
    c.id, c.name, coalesce(fs.custom_sport_name, sp.name),
    cat.id, cat.name, t.title, t.priority, t.status,
    rp.full_name, ap.full_name, t.scheduled_start, t.reported_at,
    t.actual_cost_minor, t.estimated_cost_minor,
    count(*) over () as total_count
  from maintenance_tickets t
  join courts c on c.id = t.court_id
  left join facility_sports fs on fs.id = t.facility_sport_id
  left join sports sp on sp.id = fs.sport_id
  join maintenance_issue_categories cat on cat.id = t.issue_category_id
  join profiles rp on rp.id = t.reported_by
  left join profiles ap on ap.id = t.assigned_to
  where t.facility_id = p_facility_id
    and (p_status is null or t.status = p_status)
    and (p_priority is null or t.priority = p_priority)
    and (p_court_id is null or t.court_id = p_court_id)
    and (p_facility_sport_id is null or t.facility_sport_id = p_facility_sport_id)
    and (p_issue_category_id is null or t.issue_category_id = p_issue_category_id)
    and (p_assigned_to is null or t.assigned_to = p_assigned_to)
    and (p_from is null or t.reported_at::date >= p_from)
    and (p_to is null or t.reported_at::date <= p_to)
    and (
      p_search is null or trim(p_search) = '' or
      t.title ilike '%' || trim(p_search) || '%' or
      c.name ilike '%' || trim(p_search) || '%' or
      ('MT-' || upper(substr(replace(t.id::text, '-', ''), 1, 4))) ilike '%' || trim(p_search) || '%'
    )
  order by
    case when p_sort = 'PRIORITY' then
      case t.priority when 'CRITICAL' then 0 when 'HIGH' then 1 when 'MEDIUM' then 2 else 3 end
    end asc nulls last,
    case when p_sort = 'OLDEST' then t.reported_at end asc nulls last,
    t.reported_at desc
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- list_maintenance_issue_categories (was 0068_maintenance_module.sql)
create or replace function list_maintenance_issue_categories(p_facility_id uuid, p_include_inactive boolean default true)
returns table (
  id uuid, facility_id uuid, name text, icon text, description text,
  is_active boolean, sort_order integer, issue_count bigint, is_shared boolean
)
language plpgsql
stable
as $$
begin
  perform require_page_access_any(p_facility_id, array['MAINTENANCE_CATEGORIES_VIEW', 'MAINTENANCE_VIEW']);
  return query
  select
    c.id, c.facility_id, c.name, c.icon, c.description, c.is_active, c.sort_order,
    coalesce((select count(*) from maintenance_tickets t where t.issue_category_id = c.id and t.facility_id = p_facility_id), 0)::bigint,
    c.facility_id is null
  from maintenance_issue_categories c
  where (c.facility_id is null or c.facility_id = p_facility_id)
    and (p_include_inactive or c.is_active)
  order by c.sort_order, c.name;
end;
$$;

-- create_maintenance_ticket (was 0068_maintenance_module.sql)
create or replace function create_maintenance_ticket(
  p_facility_id uuid,
  p_court_id uuid,
  p_issue_category_id uuid,
  p_priority text,
  p_title text,
  p_description text,
  p_scheduled_start timestamptz default null,
  p_scheduled_end timestamptz default null,
  p_assigned_to uuid default null,
  p_estimated_cost_minor integer default null,
  p_notes text default null
) returns maintenance_tickets
language plpgsql
as $$
declare
  result maintenance_tickets;
  category maintenance_issue_categories;
  v_status text := 'REPORTED';
begin
  perform require_page_access_any(p_facility_id, array['MAINTENANCE_CREATE']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if trim(coalesce(p_title, '')) = '' then
    raise exception 'Title is required.' using errcode = '23514';
  end if;
  if trim(coalesce(p_description, '')) = '' then
    raise exception 'Description is required.' using errcode = '23514';
  end if;
  if p_priority not in ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL') then
    raise exception 'Unknown priority: %', p_priority using errcode = '23514';
  end if;
  select * into category from maintenance_issue_categories
    where id = p_issue_category_id and (facility_id is null or facility_id = p_facility_id) and is_active;
  if category.id is null then
    raise exception 'That issue category is not available for this facility.' using errcode = '23503';
  end if;
  if not exists (select 1 from courts where id = p_court_id and facility_id = p_facility_id) then
    raise exception 'That court does not belong to this facility.' using errcode = '23503';
  end if;
  if p_scheduled_start is not null and p_scheduled_end is not null then
    if p_scheduled_end <= p_scheduled_start then
      raise exception 'Scheduled end must be after scheduled start.' using errcode = '23514';
    end if;
    v_status := 'SCHEDULED';
  elsif p_assigned_to is not null then
    v_status := 'ASSIGNED';
  end if;

  insert into maintenance_tickets (
    facility_id, court_id, issue_category_id, priority, title, description,
    reported_by, assigned_to, scheduled_start, scheduled_end, estimated_cost_minor, notes, status
  ) values (
    p_facility_id, p_court_id, p_issue_category_id, p_priority, trim(p_title), trim(p_description),
    auth.uid(), p_assigned_to, p_scheduled_start, p_scheduled_end, p_estimated_cost_minor, nullif(trim(coalesce(p_notes, '')), ''), v_status
  ) returning * into result;

  perform log_maintenance_activity(result.id, p_facility_id, 'CREATED', 'Ticket reported: ' || result.title);
  if p_assigned_to is not null then
    perform log_maintenance_activity(result.id, p_facility_id, 'ASSIGNED', null, jsonb_build_object('assignedTo', p_assigned_to));
  end if;

  if v_status = 'SCHEDULED' then
    begin
      insert into maintenance_blocks (facility_id, court_id, ticket_id, start_time, end_time, created_by)
      values (p_facility_id, p_court_id, result.id, p_scheduled_start, p_scheduled_end, auth.uid());
    exception when exclusion_violation then
      raise exception 'Another maintenance block already exists for this court and time.' using errcode = '23514';
    end;
    perform log_maintenance_activity(result.id, p_facility_id, 'SCHEDULED', null,
      jsonb_build_object('start', p_scheduled_start, 'end', p_scheduled_end));
    perform log_maintenance_activity(result.id, p_facility_id, 'COURT_BLOCKED');

    if exists (select 1 from detect_maintenance_affected_bookings(p_court_id, p_scheduled_start, p_scheduled_end)) then
      perform log_maintenance_activity(result.id, p_facility_id, 'BOOKING_CONFLICT_DETECTED', null,
        jsonb_build_object('count', (select count(*) from detect_maintenance_affected_bookings(p_court_id, p_scheduled_start, p_scheduled_end))));
    end if;
  end if;

  return result;
end;
$$;

-- create_maintenance_issue_category (was 0068_maintenance_module.sql)
create or replace function create_maintenance_issue_category(
  p_facility_id uuid, p_name text, p_icon text, p_description text default null, p_sort_order integer default 0
) returns maintenance_issue_categories
language plpgsql
as $$
declare result maintenance_issue_categories;
begin
  perform require_page_access_any(p_facility_id, array['MAINTENANCE_CATEGORIES_EDIT']);
  if not has_facility_role(p_facility_id, array['owner', 'manager']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if trim(coalesce(p_name, '')) = '' then
    raise exception 'Category name is required.' using errcode = '23514';
  end if;
  insert into maintenance_issue_categories (facility_id, name, icon, description, sort_order)
  values (p_facility_id, trim(p_name), coalesce(nullif(trim(p_icon), ''), 'wrench'), nullif(trim(coalesce(p_description, '')), ''), coalesce(p_sort_order, 0))
  returning * into result;
  return result;
end;
$$;

-- update_maintenance_issue_category (was 0068_maintenance_module.sql)
create or replace function update_maintenance_issue_category(
  p_category_id uuid, p_name text, p_icon text, p_description text default null, p_sort_order integer default 0, p_is_active boolean default true
) returns maintenance_issue_categories
language plpgsql
as $$
declare existing maintenance_issue_categories; result maintenance_issue_categories;
begin
  perform require_page_access_any((select t.facility_id from maintenance_issue_categories t where t.id = p_category_id), array['MAINTENANCE_CATEGORIES_EDIT']);
  select * into existing from maintenance_issue_categories where id = p_category_id;
  if existing.id is null then
    raise exception 'Issue category not found' using errcode = 'P0002';
  end if;
  if existing.facility_id is null or not has_facility_role(existing.facility_id, array['owner', 'manager']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if trim(coalesce(p_name, '')) = '' then
    raise exception 'Category name is required.' using errcode = '23514';
  end if;
  update maintenance_issue_categories
  set name = trim(p_name),
      icon = coalesce(nullif(trim(p_icon), ''), 'wrench'),
      description = nullif(trim(coalesce(p_description, '')), ''),
      sort_order = coalesce(p_sort_order, 0),
      is_active = coalesce(p_is_active, true),
      updated_at = now()
  where id = p_category_id
  returning * into result;
  return result;
end;
$$;

-- get_maintenance_ticket_detail (was 0068_maintenance_module.sql)
create or replace function get_maintenance_ticket_detail(p_ticket_id uuid) returns jsonb
language plpgsql
stable
as $$
declare
  t maintenance_tickets;
  fac facilities;
begin
  perform require_page_access_any((select t.facility_id from maintenance_tickets t where t.id = p_ticket_id), array['MAINTENANCE_VIEW']);
  select * into t from maintenance_tickets where id = p_ticket_id;
  if t.id is null then
    raise exception 'Maintenance ticket not found' using errcode = 'P0002';
  end if;
  if not is_facility_member(t.facility_id) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  select * into fac from facilities where id = t.facility_id;

  return jsonb_build_object(
    'id', t.id,
    'code', 'MT-' || upper(substr(replace(t.id::text, '-', ''), 1, 4)),
    'facilityId', t.facility_id,
    'court', (select jsonb_build_object('id', c.id, 'name', c.name) from courts c where c.id = t.court_id),
    'sportName', (select coalesce(fs.custom_sport_name, sp.name) from facility_sports fs join sports sp on sp.id = fs.sport_id where fs.id = t.facility_sport_id),
    'category', (select jsonb_build_object('id', cat.id, 'name', cat.name, 'icon', cat.icon) from maintenance_issue_categories cat where cat.id = t.issue_category_id),
    'title', t.title,
    'description', t.description,
    'priority', t.priority,
    'status', t.status,
    'reportedBy', (select jsonb_build_object('id', p.id, 'name', p.full_name) from profiles p where p.id = t.reported_by),
    'reportedAt', t.reported_at,
    'assignedTo', (select jsonb_build_object('id', p.id, 'name', p.full_name) from profiles p where p.id = t.assigned_to),
    'scheduledStart', t.scheduled_start,
    'scheduledEnd', t.scheduled_end,
    'actualStart', t.actual_start,
    'actualEnd', t.actual_end,
    'estimatedCostMinor', t.estimated_cost_minor,
    'actualCostMinor', t.actual_cost_minor,
    'expenseId', t.expense_id,
    'notes', t.notes,
    'currency', coalesce(fac.currency, 'INR'),
    'activeBlock', (
      select jsonb_build_object('id', mb.id, 'startTime', mb.start_time, 'endTime', mb.end_time, 'status', mb.status)
      from maintenance_blocks mb where mb.ticket_id = t.id and mb.status = 'ACTIVE' order by mb.created_at desc limit 1
    ),
    'attachments', coalesce((
      select jsonb_agg(jsonb_build_object('id', a.id, 'storagePath', a.storage_path, 'fileName', a.file_name, 'contentType', a.content_type, 'sizeBytes', a.size_bytes, 'createdAt', a.created_at) order by a.created_at)
      from maintenance_ticket_attachments a where a.ticket_id = t.id
    ), '[]'::jsonb),
    'activity', coalesce((
      select jsonb_agg(jsonb_build_object('id', e.id, 'eventType', e.event_type, 'note', e.note, 'metadata', e.metadata, 'actorName', p.full_name, 'createdAt', e.created_at) order by e.created_at desc)
      from maintenance_ticket_activity e left join profiles p on p.id = e.actor_id where e.ticket_id = t.id
    ), '[]'::jsonb),
    'affectedBookings', coalesce((
      select jsonb_agg(jsonb_build_object(
        'bookingId', b.booking_id, 'customerType', b.customer_type, 'guestName', b.guest_name, 'memberId', b.member_id,
        'startTime', b.start_time, 'endTime', b.end_time, 'status', b.status, 'paymentStatus', b.payment_status, 'amountMinor', b.amount_minor
      ))
      from detect_maintenance_affected_bookings(t.court_id, coalesce(t.scheduled_start, now()), coalesce(t.scheduled_end, now())) b
      where t.scheduled_start is not null and t.scheduled_end is not null
    ), '[]'::jsonb),
    'affectedSessions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'batchId', s.batch_id, 'batchName', s.batch_name, 'sessionDate', s.session_date,
        'startTime', s.start_time, 'endTime', s.end_time, 'memberBookedCount', s.member_booked_count, 'guestBookedCount', s.guest_booked_count
      ))
      from detect_maintenance_affected_membership_sessions(t.court_id, coalesce(t.scheduled_start, now()), coalesce(t.scheduled_end, now()), coalesce(fac.timezone, 'Asia/Kolkata')) s
      where t.scheduled_start is not null and t.scheduled_end is not null
    ), '[]'::jsonb)
  );
end;
$$;

-- add_maintenance_note (was 0068_maintenance_module.sql)
create or replace function add_maintenance_note(p_ticket_id uuid, p_note text) returns maintenance_ticket_activity
language plpgsql
as $$
