  if existing.status <> 'RESOLVED' then
    raise exception 'Only a resolved ticket can be reopened.' using errcode = '23514';
  end if;

  update maintenance_tickets set status = 'IN_PROGRESS', resolved_at = null
  where id = p_ticket_id
  returning * into result;

  perform log_maintenance_activity(result.id, result.facility_id, 'REOPENED');
  return result;
end;
$$;

-- assign_maintenance_ticket (was 0068_maintenance_module.sql)
create or replace function assign_maintenance_ticket(p_ticket_id uuid, p_assigned_to uuid) returns maintenance_tickets
language plpgsql
as $$
declare existing maintenance_tickets; result maintenance_tickets; v_status text;
begin
  perform require_page_access_any((select t.facility_id from maintenance_tickets t where t.id = p_ticket_id), array['MAINTENANCE_ASSIGN']);
  select * into existing from maintenance_tickets where id = p_ticket_id;
  if existing.id is null then
    raise exception 'Maintenance ticket not found' using errcode = 'P0002';
  end if;
  if existing.status in ('RESOLVED', 'CLOSED') then
    raise exception 'Cannot assign a % ticket.', existing.status using errcode = '23514';
  end if;
  if not exists (select 1 from facility_users where facility_id = existing.facility_id and user_id = p_assigned_to) then
    raise exception 'That user is not a member of this facility.' using errcode = '23503';
  end if;

  v_status := case when existing.status = 'REPORTED' then 'ASSIGNED' else existing.status end;

  update maintenance_tickets set assigned_to = p_assigned_to, status = v_status
  where id = p_ticket_id
  returning * into result;

  perform log_maintenance_activity(result.id, result.facility_id, 'ASSIGNED', null, jsonb_build_object('assignedTo', p_assigned_to));
  return result;
end;
$$;

-- schedule_maintenance (was 0068_maintenance_module.sql)
create or replace function schedule_maintenance(p_ticket_id uuid, p_start timestamptz, p_end timestamptz) returns maintenance_tickets
language plpgsql
as $$
declare existing maintenance_tickets; result maintenance_tickets;
begin
  perform require_page_access_any((select t.facility_id from maintenance_tickets t where t.id = p_ticket_id), array['MAINTENANCE_SCHEDULE']);
  select * into existing from maintenance_tickets where id = p_ticket_id for update;
  if existing.id is null then
    raise exception 'Maintenance ticket not found' using errcode = 'P0002';
  end if;
  if existing.status in ('RESOLVED', 'CLOSED') then
    raise exception 'Cannot schedule a % ticket.', existing.status using errcode = '23514';
  end if;
  if p_end <= p_start then
    raise exception 'Scheduled end must be after scheduled start.' using errcode = '23514';
  end if;

  update maintenance_blocks set status = 'ENDED', updated_at = now()
  where ticket_id = p_ticket_id and status = 'ACTIVE';

  begin
    insert into maintenance_blocks (facility_id, court_id, ticket_id, start_time, end_time, created_by)
    values (existing.facility_id, existing.court_id, p_ticket_id, p_start, p_end, auth.uid());
  exception when exclusion_violation then
    raise exception 'Another maintenance block already exists for this court and time.' using errcode = '23514';
  end;

  update maintenance_tickets
  set scheduled_start = p_start, scheduled_end = p_end,
      status = case when status in ('REPORTED', 'ASSIGNED') then 'SCHEDULED' else status end
  where id = p_ticket_id
  returning * into result;

  perform log_maintenance_activity(result.id, result.facility_id, 'SCHEDULED', null, jsonb_build_object('start', p_start, 'end', p_end));
  perform log_maintenance_activity(result.id, result.facility_id, 'COURT_BLOCKED');

  if exists (select 1 from detect_maintenance_affected_bookings(existing.court_id, p_start, p_end, p_ticket_id)) then
    perform log_maintenance_activity(result.id, result.facility_id, 'BOOKING_CONFLICT_DETECTED', null,
      jsonb_build_object('count', (select count(*) from detect_maintenance_affected_bookings(existing.court_id, p_start, p_end, p_ticket_id))));
  end if;

  return result;
end;
$$;

-- start_maintenance_ticket (was 0068_maintenance_module.sql)
create or replace function start_maintenance_ticket(p_ticket_id uuid) returns maintenance_tickets
language plpgsql
as $$
declare existing maintenance_tickets; result maintenance_tickets;
begin
  perform require_page_access_any((select t.facility_id from maintenance_tickets t where t.id = p_ticket_id), array['MAINTENANCE_RESOLVE']);
  select * into existing from maintenance_tickets where id = p_ticket_id;
  if existing.id is null then
    raise exception 'Maintenance ticket not found' using errcode = 'P0002';
  end if;
  if existing.status not in ('ASSIGNED', 'SCHEDULED') then
    raise exception 'Only an assigned or scheduled ticket can be started.' using errcode = '23514';
  end if;

  update maintenance_tickets set status = 'IN_PROGRESS', actual_start = now()
  where id = p_ticket_id
  returning * into result;

  perform log_maintenance_activity(result.id, result.facility_id, 'MAINTENANCE_STARTED');
  return result;
end;
$$;

-- resolve_maintenance_ticket (was 0068_maintenance_module.sql)
create or replace function resolve_maintenance_ticket(p_ticket_id uuid, p_actual_end timestamptz default null) returns maintenance_tickets
language plpgsql
as $$
declare existing maintenance_tickets; result maintenance_tickets;
begin
  perform require_page_access_any((select t.facility_id from maintenance_tickets t where t.id = p_ticket_id), array['MAINTENANCE_RESOLVE']);
  select * into existing from maintenance_tickets where id = p_ticket_id for update;
  if existing.id is null then
    raise exception 'Maintenance ticket not found' using errcode = 'P0002';
  end if;
  if existing.status not in ('IN_PROGRESS', 'SCHEDULED', 'ASSIGNED') then
    raise exception 'Cannot resolve a % ticket.', existing.status using errcode = '23514';
  end if;

  update maintenance_tickets
  set status = 'RESOLVED',
      actual_start = coalesce(actual_start, now()),
      actual_end = coalesce(p_actual_end, now()),
      resolved_at = now()
  where id = p_ticket_id
  returning * into result;

  update maintenance_blocks set status = 'ENDED', updated_at = now()
  where ticket_id = p_ticket_id and status = 'ACTIVE';

  perform log_maintenance_activity(result.id, result.facility_id, 'RESOLVED');
  perform log_maintenance_activity(result.id, result.facility_id, 'COURT_REOPENED');
  return result;
end;
$$;

-- update_maintenance_cost (was 0068_maintenance_module.sql)
create or replace function update_maintenance_cost(
  p_ticket_id uuid,
  p_estimated_cost_minor integer default null,
  p_actual_cost_minor integer default null,
  p_post_to_expenses boolean default false,
  p_expense_category_id uuid default null,
  p_payment_method text default null,
  p_vendor text default null
) returns maintenance_tickets
language plpgsql
as $$
declare
  existing maintenance_tickets;
  result maintenance_tickets;
  cat_id uuid;
  exp expenses;
begin
  perform require_page_access_any((select t.facility_id from maintenance_tickets t where t.id = p_ticket_id), array['MAINTENANCE_RESOLVE']);
  select * into existing from maintenance_tickets where id = p_ticket_id;
  if existing.id is null then
    raise exception 'Maintenance ticket not found' using errcode = 'P0002';
  end if;

  update maintenance_tickets
  set estimated_cost_minor = coalesce(p_estimated_cost_minor, estimated_cost_minor),
      actual_cost_minor = coalesce(p_actual_cost_minor, actual_cost_minor)
  where id = p_ticket_id
  returning * into result;

  if p_post_to_expenses and result.actual_cost_minor is not null and result.expense_id is null then
    cat_id := p_expense_category_id;
    if cat_id is null then
      select id into cat_id from expense_categories
        where lower(name) = 'maintenance' and (facility_id is null or facility_id = result.facility_id)
        order by facility_id nulls last limit 1;
    end if;
    exp := create_expense(result.facility_id, cat_id, result.actual_cost_minor, current_date, p_payment_method, p_vendor, 'MT-' || substr(replace(result.id::text, '-', ''), 1, 8), 'Maintenance: ' || result.title);
    update maintenance_tickets set expense_id = exp.id where id = p_ticket_id returning * into result;
  end if;

  perform log_maintenance_activity(result.id, result.facility_id, 'COST_UPDATED', null,
    jsonb_build_object('estimatedCostMinor', result.estimated_cost_minor, 'actualCostMinor', result.actual_cost_minor, 'expenseId', result.expense_id));
  return result;
end;
$$;

-- list_memberships (was 0032_payment_incomplete.sql, plain SQL — now guarded through a private implementation)
create or replace function _list_memberships_impl(
  p_facility_id uuid,
  p_search text default null,
  p_status text default null,
  p_plan_id uuid default null,
  p_sort text default 'oldest',
  p_limit integer default 10,
  p_offset integer default 0
) returns table (
  membership_id uuid,
  member_id uuid,
  member_name text,
  member_phone text,
  member_email text,
  plan_id uuid,
  plan_name text,
  monthly_price_inr integer,
  display_status text,
  start_date date,
  end_date date,
  days_left integer,
  created_by uuid,
  created_by_name text,
  batch_name text,
  batch_days integer[],
  batch_start time,
  batch_end time,
  batch_court text,
  total_count bigint
)
language sql
stable
as $$
  with base as (
    select
      m.id as membership_id,
      m.member_id,
      mem.full_name as member_name,
      mem.phone as member_phone,
      mem.email as member_email,
      m.plan_id,
      coalesce(m.name, mp.name, 'Membership') as plan_name,
      coalesce(m.monthly_price_inr, m.membership_fee_inr, mp.price_inr, 0) as monthly_price_inr,
      membership_display_status(
        m.id, m.status::text, m.start_date, m.end_date, m.duration_days,
        coalesce(m.total_amount_inr, m.membership_fee_inr, mp.price_inr, 0)::integer
      ) as display_status,
      m.start_date,
      m.end_date,
      (m.end_date - current_date) as days_left,
      m.created_by,
      p.full_name as created_by_name,
      coalesce(b.name, case when m.time_slot_start is not null then 'Time slot' end) as batch_name,
      b.days_of_week as batch_days,
      coalesce(b.start_time, m.time_slot_start) as batch_start,
      coalesce(b.end_time, m.time_slot_end) as batch_end,
      bc.name as batch_court,
      m.created_at
    from memberships m
    join members mem on mem.id = m.member_id
    left join membership_plans mp on mp.id = m.plan_id
    left join profiles p on p.id = m.created_by
    left join lateral (
      select bm.batch_id
      from membership_batch_members bm
      where bm.membership_id = m.id
      order by bm.created_at
      limit 1
    ) bml on true
    left join membership_batches b on b.id = bml.batch_id
    left join courts bc on bc.id = b.court_id
    where m.facility_id = p_facility_id
      and (
        p_search is null
        or mem.full_name ilike '%' || p_search || '%'
        or mem.phone ilike '%' || p_search || '%'
        or coalesce(mem.email, '') ilike '%' || p_search || '%'
      )
      and (p_plan_id is null or m.plan_id = p_plan_id)
  ),
  filtered as (
    select * from base where p_status is null or display_status = p_status
  )
  select
    membership_id, member_id, member_name, member_phone, member_email,
    plan_id, plan_name, monthly_price_inr, display_status,
    start_date, end_date, days_left, created_by, created_by_name,
    batch_name, batch_days, batch_start, batch_end, batch_court,
    count(*) over () as total_count
  from filtered
  order by
    case when p_sort = 'next_payment' then end_date end asc nulls last,
    case when p_sort = 'name' then member_name end asc nulls last,
    created_at asc
  limit greatest(p_limit, 1)
  offset greatest(p_offset, 0);
$$;
revoke all on function _list_memberships_impl(uuid, text, text, uuid, text, integer, integer) from public, anon, authenticated;
create or replace function list_memberships(p_facility_id uuid, p_search text default null, p_status text default null, p_plan_id uuid default null, p_sort text default 'oldest', p_limit integer default 10, p_offset integer default 0)
returns table (
  membership_id uuid,
  member_id uuid,
  member_name text,
  member_phone text,
  member_email text,
  plan_id uuid,
  plan_name text,
  monthly_price_inr integer,
  display_status text,
  start_date date,
  end_date date,
  days_left integer,
  created_by uuid,
  created_by_name text,
  batch_name text,
  batch_days integer[],
  batch_start time,
  batch_end time,
  batch_court text,
  total_count bigint
) language plpgsql stable security definer set search_path = public as $w$
begin
  perform require_page_access_any(p_facility_id, array['MEMBERSHIPS_VIEW', 'MEMBERSHIP_SESSIONS_VIEW', 'DASHBOARD_VIEW']);
  return query select * from _list_memberships_impl(p_facility_id => p_facility_id, p_search => p_search, p_status => p_status, p_plan_id => p_plan_id, p_sort => p_sort, p_limit => p_limit, p_offset => p_offset);
end;
$w$;

-- get_membership_page_summary (was 0032_payment_incomplete.sql, plain SQL — now guarded through a private implementation)
create or replace function _get_membership_page_summary_impl(p_facility_id uuid)
returns table (
  total_members bigint,
  total_members_prev bigint,
  active_members bigint,
  payment_incomplete_members bigint,
  revenue_inr bigint,
  revenue_prev_inr bigint
)
language sql
stable
as $$
  with months as (
    select
      date_trunc('month', current_date)::date as cur_start,
      (date_trunc('month', current_date) - interval '1 month')::date as prev_start
  ),
  m as (
    select
      mm.member_id,
      mm.created_at,
      membership_display_status(
        mm.id, mm.status::text, mm.start_date, mm.end_date, mm.duration_days,
        coalesce(mm.total_amount_inr, mm.membership_fee_inr, mp.price_inr, 0)::integer
      ) as ds
    from memberships mm
    left join membership_plans mp on mp.id = mm.plan_id
    where mm.facility_id = p_facility_id
  )
  select
    (select count(distinct member_id) from m),
    (select count(distinct member_id) from m, months where m.created_at < months.cur_start),
    (select count(*) from m where ds = 'active'),
    (select count(*) from m where ds = 'payment_incomplete'),
    coalesce((
      select sum(amount_inr) from payments, months
      where facility_id = p_facility_id and membership_id is not null
        and status = 'paid' and paid_at is not null
        and paid_at >= months.cur_start
    ), 0),
    coalesce((
      select sum(amount_inr) from payments, months
      where facility_id = p_facility_id and membership_id is not null
        and status = 'paid' and paid_at is not null
        and paid_at >= months.prev_start and paid_at < months.cur_start
    ), 0);
$$;
revoke all on function _get_membership_page_summary_impl(uuid) from public, anon, authenticated;
create or replace function get_membership_page_summary(p_facility_id uuid)
returns table (
  total_members bigint,
  total_members_prev bigint,
  active_members bigint,
  payment_incomplete_members bigint,
  revenue_inr bigint,
  revenue_prev_inr bigint
) language plpgsql stable security definer set search_path = public as $w$
begin
  perform require_page_access_any(p_facility_id, array['MEMBERSHIPS_VIEW', 'MEMBERSHIP_SESSIONS_VIEW', 'DASHBOARD_VIEW']);
  return query select * from _get_membership_page_summary_impl(p_facility_id => p_facility_id);
end;
$w$;

-- get_membership_revenue_timeseries (was 0026_membership_subscriptions.sql, plain SQL — now guarded through a private implementation)
create or replace function _get_membership_revenue_timeseries_impl(
  p_facility_id uuid,
  p_granularity text default 'month',
  p_from date default null,
  p_to date default null
) returns table (bucket date, amount_inr bigint, payment_count bigint)
language sql
stable
as $$
  with bounds as (
    select
      coalesce(p_from, (current_date - interval '11 months')::date) as from_d,
      coalesce(p_to, current_date) as to_d,
      case when p_granularity in ('day', 'month', 'year') then p_granularity else 'month' end as grain
  )
  select
    date_trunc((select grain from bounds), p.created_at)::date as bucket,
    sum(p.amount_inr)::bigint as amount_inr,
    count(*)::bigint as payment_count
  from payments p, bounds
  where p.facility_id = p_facility_id
    and p.membership_id is not null
    and p.status = 'paid'
    and p.created_at >= bounds.from_d
    and p.created_at < (bounds.to_d + 1)
  group by 1
  order by 1;
$$;
revoke all on function _get_membership_revenue_timeseries_impl(uuid, text, date, date) from public, anon, authenticated;
create or replace function get_membership_revenue_timeseries(p_facility_id uuid, p_granularity text default 'month', p_from date default null, p_to date default null)
returns table (bucket date, amount_inr bigint, payment_count bigint) language plpgsql stable security definer set search_path = public as $w$
begin
  perform require_page_access_any(p_facility_id, array['MEMBERSHIPS_VIEW', 'MEMBERSHIP_SESSIONS_VIEW', 'DASHBOARD_VIEW']);
  return query select * from _get_membership_revenue_timeseries_impl(p_facility_id => p_facility_id, p_granularity => p_granularity, p_from => p_from, p_to => p_to);
end;
$w$;

-- get_member_stats (was 0012_memberships.sql, plain SQL — now guarded through a private implementation)
create or replace function _get_member_stats_impl(p_member_id uuid, p_facility_id uuid) returns table (
  total_visits bigint,
  total_bookings bigint,
  last_visit timestamptz,
  total_amount_minor bigint,
  pending_amount_minor bigint,
  sports jsonb
)
language sql
stable
as $$
  select
    count(*) filter (where b.status in ('confirmed', 'completed')) as total_visits,
    count(*) as total_bookings,
    max(b.start_time) filter (where b.status in ('confirmed', 'completed')) as last_visit,
    coalesce(sum(b.amount_minor) filter (where b.status in ('confirmed', 'completed')), 0) as total_amount_minor,
    coalesce(
      sum(b.amount_minor) filter (
        where b.status in ('confirmed', 'completed') and b.payment_status = 'PENDING'
      ), 0
    ) as pending_amount_minor,
    coalesce(
      jsonb_agg(distinct jsonb_build_object('sportId', s.id, 'sportName', s.name))
        filter (where s.id is not null),
      '[]'::jsonb
    ) as sports
  from bookings b
  left join facility_sports fs on fs.id = b.facility_sport_id
  left join sports s on s.id = fs.sport_id
