-- list_assignable_batches (was 0027_membership_batch_capacity.sql, plain SQL — now guarded through a private implementation)
create or replace function _list_assignable_batches_impl(p_facility_id uuid, p_plan_id uuid default null)
returns table (
  batch_id uuid,
  name text,
  plan_id uuid,
  court_id uuid,
  court_name text,
  facility_sport_id uuid,
  sport_name text,
  days_of_week integer[],
  start_time time,
  end_time time,
  capacity integer,
  enrolled_count integer,
  spare integer
)
language sql
stable
as $$
  select
    b.id,
    b.name,
    b.plan_id,
    b.court_id,
    c.name as court_name,
    b.facility_sport_id,
    coalesce(fs.custom_sport_name, s.name) as sport_name,
    b.days_of_week,
    b.start_time,
    b.end_time,
    b.capacity,
    coalesce(m.cnt, 0)::integer as enrolled_count,
    greatest(b.capacity - coalesce(m.cnt, 0), 0)::integer as spare
  from membership_batches b
  join courts c on c.id = b.court_id
  join facility_sports fs on fs.id = b.facility_sport_id
  join sports s on s.id = fs.sport_id
  left join (
    select batch_id, count(*)::integer as cnt
    from membership_batch_members
    group by batch_id
  ) m on m.batch_id = b.id
  where b.facility_id = p_facility_id
    and b.is_active
    and (p_plan_id is null or b.plan_id = p_plan_id)
  order by b.start_time, b.name;
$$;
