-- search_facility_members (was 0013_facility_members.sql, plain SQL — now guarded through a private implementation)
create or replace function _search_facility_members_impl(
  p_facility_id uuid,
  p_query text default null,
  p_limit integer default 50,
  p_offset integer default 0
) returns table (
  member_id uuid,
  full_name text,
  phone text,
  email text,
  membership_id uuid,
  plan_id uuid,
  plan_name text,
  start_date date,
  end_date date,
  status membership_status
)
language sql
stable
as $$
  with latest as (
    select distinct on (member_id) *
    from memberships
    where facility_id = p_facility_id
    order by member_id, end_date desc
  )
  select m.id, m.full_name, m.phone, m.email,
         l.id, l.plan_id, mp.name, l.start_date, l.end_date, l.status
  from members m
  left join latest l on l.member_id = m.id
  left join membership_plans mp on mp.id = l.plan_id
  where m.facility_id = p_facility_id
    and (
      p_query is null or trim(p_query) = ''
      or m.full_name ilike '%' || p_query || '%'
      or m.phone ilike '%' || p_query || '%'
      or m.email ilike '%' || p_query || '%'
    )
  order by l.end_date desc nulls last, m.full_name
  limit p_limit offset p_offset;
$$;
