-- create_member (was 0013_facility_members.sql)
create or replace function create_member(
  p_facility_id uuid,
  p_full_name text,
  p_phone text,
  p_email text default null,
  p_date_of_birth date default null,
  p_gender text default null,
  p_notes text default null
) returns members
language plpgsql
as $$
declare
  result members;
begin
  perform require_page_access_any(p_facility_id, array['MEMBERSHIPS_CREATE']);
  if trim(coalesce(p_full_name, '')) = '' then
    raise exception 'Member name is required.' using errcode = '23514';
  end if;
  if trim(coalesce(p_phone, '')) = '' then
    raise exception 'Member mobile number is required.' using errcode = '23514';
  end if;

  insert into members (facility_id, full_name, phone, email, date_of_birth, gender, notes)
  values (p_facility_id, trim(p_full_name), trim(p_phone), p_email, p_date_of_birth, p_gender, p_notes)
  returning * into result;

  return result;
end;
$$;

-- create_membership (was 0025_memberships_page.sql)
create or replace function create_membership(
  p_member_id uuid,
  p_facility_id uuid,
  p_plan_id uuid,
  p_start_date date,
  p_payment_status payment_status default 'created',
  p_monthly_price_inr integer default null
) returns memberships
language plpgsql
as $$
declare
  plan membership_plans;
  result memberships;
  computed_end date;
  computed_status membership_status;
  price integer;
begin
  perform require_page_access_any(p_facility_id, array['MEMBERSHIPS_CREATE']);
  select * into plan from membership_plans
    where id = p_plan_id and facility_id = p_facility_id and is_active;
  if plan.id is null then
    raise exception 'Membership plan not found for this facility.' using errcode = '23503';
  end if;

  computed_end := p_start_date + plan.duration_days;
  computed_status := case when computed_end >= current_date then 'active' else 'expired' end;
  price := coalesce(nullif(p_monthly_price_inr, 0), plan.price_inr);

  insert into memberships (facility_id, member_id, plan_id, status, start_date, end_date, created_by, monthly_price_inr)
  values (p_facility_id, p_member_id, p_plan_id, computed_status, p_start_date, computed_end, auth.uid(), price)
  returning * into result;

  if price > 0 then
    insert into payments (facility_id, member_id, membership_id, amount_inr, status)
    values (p_facility_id, p_member_id, result.id, price, p_payment_status);
  end if;

  return result;
end;
$$;

-- create_membership_full (was 0029_membership_time_slots.sql)
create or replace function create_membership_full(
  p_facility_id uuid,
  p_full_name text,
