  p_start_date date,
  p_duration_days integer,
  p_description text,
  p_membership_fee_inr integer,
  p_registration_fee_inr integer,
  p_gst_percent numeric,
  p_payment_mode text,
  p_payment_methods text,
  p_payment_reference text,
  p_referral_member_id uuid,
  p_discovery_source text,
  p_notes text,
  p_monthly_price_inr integer default null,
  p_batch_id uuid default null,
  p_new_batch jsonb default null
) returns memberships
language plpgsql
security definer
set search_path = public
as $$
declare
  v_member_id uuid;
  computed_end date;
  fee integer := greatest(coalesce(p_membership_fee_inr, 0), 0);
  reg integer := greatest(coalesce(p_registration_fee_inr, 0), 0);
  gst numeric := greatest(coalesce(p_gst_percent, 0), 0);
  gst_amount integer;
  total integer;
  result memberships;
  v_batch_id uuid;
  v_court courts;
  v_days smallint[];
  v_start time;
  v_end time;
  v_capacity integer;
  v_batch_name text;
begin
  perform require_page_access_any(p_facility_id, array['MEMBERSHIPS_CREATE']);
  if not has_facility_role(p_facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if trim(coalesce(p_full_name, '')) = '' or trim(coalesce(p_phone, '')) = '' then
    raise exception 'Member name and phone are required.' using errcode = '23514';
  end if;
  if coalesce(p_duration_days, 0) <= 0 then
    raise exception 'Choose a membership duration.' using errcode = '23514';
  end if;
  if p_batch_id is not null and p_new_batch is not null then
    raise exception 'Pick one time slot, not both.' using errcode = '23514';
  end if;

  -- Get-or-create the member by (facility, phone).
  select id into v_member_id from members
    where facility_id = p_facility_id and phone = trim(p_phone);
  if v_member_id is null then
    insert into members (facility_id, full_name, phone, email, date_of_birth, gender, address)
    values (p_facility_id, trim(p_full_name), trim(p_phone), nullif(trim(p_email), ''),
            p_date_of_birth, nullif(trim(p_gender), ''), nullif(trim(p_address), ''))
    returning id into v_member_id;
  else
    update members set
      email = coalesce(email, nullif(trim(p_email), '')),
      date_of_birth = coalesce(date_of_birth, p_date_of_birth),
      gender = coalesce(gender, nullif(trim(p_gender), '')),
      address = coalesce(address, nullif(trim(p_address), ''))
    where id = v_member_id;
  end if;

  computed_end := p_start_date + p_duration_days;
  gst_amount := round(fee * gst / 100.0);
  total := fee + gst_amount + reg;

  insert into memberships (
    facility_id, member_id, plan_id, status, start_date, end_date, created_by,
    name, membership_type, max_family_members, duration_days,
    description,
    membership_fee_inr, registration_fee_inr, gst_percent, total_amount_inr,
    monthly_price_inr, payment_reference, referral_member_id, discovery_source, notes
  )
  values (
    p_facility_id, v_member_id, null,
    (case when computed_end >= current_date then 'active' else 'expired' end)::membership_status,
    p_start_date, computed_end, auth.uid(),
    nullif(trim(p_name), ''),
    coalesce(nullif(trim(p_membership_type), ''), 'INDIVIDUAL'),
    greatest(coalesce(p_max_family_members, 1), 1),
    p_duration_days,
    nullif(trim(p_description), ''),
    fee, reg, gst, total,
    coalesce(p_monthly_price_inr, fee),
    nullif(trim(p_payment_reference), ''), p_referral_member_id, nullif(trim(p_discovery_source), ''),
    nullif(trim(p_notes), '')
  )
  returning * into result;

  if upper(coalesce(p_payment_mode, 'PENDING')) <> 'FREE' and total > 0 then
    insert into payments (facility_id, member_id, membership_id, amount_inr, status, payment_method)
    values (
      p_facility_id, v_member_id, result.id, total,
      case when upper(p_payment_mode) = 'PAID' then 'paid'::payment_status else 'created'::payment_status end,
      nullif(trim(p_payment_methods), '')
    );
  end if;

  -- ── Reserved court time slot ──────────────────────────────────────────
  if p_new_batch is not null then
    select array_agg(value::smallint) into v_days
      from jsonb_array_elements_text(p_new_batch->'daysOfWeek');
    v_start := (p_new_batch->>'startTime')::time;
    v_end := (p_new_batch->>'endTime')::time;
    v_capacity := (p_new_batch->>'capacity')::integer;

    if v_start is null or v_end is null then
      raise exception 'Time slot start and end are required.' using errcode = '23514';
    end if;
    if coalesce(array_length(v_days, 1), 0) = 0 or not (v_days <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]) then
      raise exception 'Select at least one valid access day for the time slot.' using errcode = '23514';
    end if;
    if v_end <= v_start then
      raise exception 'Time slot end must be after the start.' using errcode = '23514';
    end if;
    if coalesce(v_capacity, 0) < 1 then
      raise exception 'Time slot capacity must be at least 1.' using errcode = '23514';
    end if;

    select * into v_court from courts
      where id = (p_new_batch->>'courtId')::uuid
        and facility_id = p_facility_id
        and facility_sport_id = (p_new_batch->>'facilitySportId')::uuid;
    if v_court.id is null then
      raise exception 'That court does not belong to this facility/sport.' using errcode = '23503';
    end if;

    v_batch_name := coalesce(
      nullif(trim(p_new_batch->>'name'), ''),
      coalesce(nullif(trim(p_name), ''), 'Membership') || ' · '
        || to_char(v_start, 'FMHH12:MI') || '–' || to_char(v_end, 'FMHH12:MI AM')
    );

    insert into membership_batches (
      facility_id, plan_id, facility_sport_id, court_id, name,
      days_of_week, start_time, end_time, capacity, is_active
    ) values (
      p_facility_id, null, v_court.facility_sport_id, v_court.id, v_batch_name,
      v_days, v_start, v_end, v_capacity, true
    ) returning id into v_batch_id;
  elsif p_batch_id is not null then
    if not exists (
      select 1 from membership_batches
      where id = p_batch_id and facility_id = p_facility_id and is_active
    ) then
      raise exception 'That time slot is not available.' using errcode = '23503';
    end if;
    v_batch_id := p_batch_id;
  end if;

  if v_batch_id is not null then
    perform assign_batch_member(v_batch_id, v_member_id, result.id);
  end if;

  return result;
end;
$$;

-- set_facility_membership_access_days (was 0029_membership_time_slots.sql)
create or replace function set_facility_membership_access_days(
  p_facility_id uuid,
  p_days smallint[]
) returns facilities
language plpgsql
security definer
set search_path = public
as $$
declare
  result facilities;
begin
  perform require_page_access_any(p_facility_id, array['MEMBERSHIPS_EDIT', 'MEMBERSHIP_PLANS_EDIT']);
  if not has_facility_role(p_facility_id, array['owner', 'manager']::facility_role[]) then
    raise exception 'Not authorized to change membership settings.' using errcode = '42501';
  end if;
  if coalesce(array_length(p_days, 1), 0) = 0 then
    raise exception 'Select at least one access day.' using errcode = '23514';
  end if;
  if not (p_days <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]) then
    raise exception 'Invalid day value.' using errcode = '23514';
  end if;

  update facilities set membership_access_days = p_days
  where id = p_facility_id
  returning * into result;

  if result.id is null then
    raise exception 'Facility not found' using errcode = 'P0002';
  end if;
  return result;
end;
$$;

-- create_membership_batch (was 0037_membership_session_detail_page.sql)
create or replace function create_membership_batch(
  p_facility_id uuid,
  p_plan_id uuid,
  p_facility_sport_id uuid,
  p_court_id uuid,
  p_name text,
  p_days_of_week smallint[],
  p_start_time time,
  p_end_time time,
  p_capacity integer
) returns membership_batches
language plpgsql
as $$
declare
  result membership_batches;
  court courts;
begin
  perform require_page_access_any(p_facility_id, array['MEMBERSHIP_SESSIONS_EDIT', 'MEMBERSHIP_PLANS_EDIT']);
  if trim(coalesce(p_name, '')) = '' then
    raise exception 'Batch name is required.' using errcode = '23514';
  end if;

  select * into court from courts where id = p_court_id and facility_id = p_facility_id and facility_sport_id = p_facility_sport_id;
  if court.id is null then
    raise exception 'That court does not belong to this facility/sport.' using errcode = '23503';
  end if;

  insert into membership_batches (
    facility_id, plan_id, facility_sport_id, court_id, name, days_of_week, start_time, end_time, capacity, created_by
  ) values (
    p_facility_id, p_plan_id, p_facility_sport_id, p_court_id, trim(p_name), p_days_of_week, p_start_time, p_end_time, p_capacity, auth.uid()
  ) returning * into result;

  return result;
end;
$$;

-- update_member (was 0013_facility_members.sql)
create or replace function update_member(
  p_member_id uuid,
  p_full_name text,
  p_phone text,
  p_email text,
  p_date_of_birth date,
  p_gender text,
  p_notes text,
  p_status text default null
) returns members
language plpgsql
as $$
declare
  result members;
begin
  perform require_page_access_any((select t.facility_id from members t where t.id = p_member_id), array['MEMBERSHIPS_EDIT']);
  if trim(coalesce(p_full_name, '')) = '' then
    raise exception 'Member name is required.' using errcode = '23514';
  end if;
  if trim(coalesce(p_phone, '')) = '' then
    raise exception 'Member mobile number is required.' using errcode = '23514';
  end if;

  update members
  set full_name = trim(p_full_name),
      phone = trim(p_phone),
      email = p_email,
      date_of_birth = p_date_of_birth,
      gender = p_gender,
      notes = p_notes,
      status = coalesce(p_status, status),
      updated_at = now()
  where id = p_member_id
  returning * into result;

  if result.id is null then
    raise exception 'Member not found' using errcode = 'P0002';
  end if;

  return result;
end;
$$;

-- delete_member (was 0128_delete_member_and_student_after_cancel.sql)
create or replace function delete_member(p_member_id uuid) returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_facility uuid;
begin
  perform require_page_access_any((select t.facility_id from members t where t.id = p_member_id), array['MEMBERSHIPS_CANCEL', 'MEMBERSHIPS_EDIT']);
  select facility_id into v_facility from members where id = p_member_id;
  if v_facility is null then
    raise exception 'Member not found' using errcode = 'P0002';
  end if;
  if not has_facility_role(v_facility, array['owner', 'manager']::facility_role[]) then
    raise exception 'Not authorized to delete members.' using errcode = '42501';
  end if;

  if exists (
    select 1 from membership_subscriptions s
    where s.member_id = p_member_id and s.status in ('created', 'authenticated', 'active', 'pending', 'halted')
  ) then
    raise exception 'AutoPay is still active for this member. Cancel AutoPay first, then delete.' using errcode = '23514';
  end if;

  if exists (
    select 1 from bookings b
    where b.member_id = p_member_id and b.status in ('pending', 'confirmed') and b.start_time > now()
  ) then
    raise exception 'This member has upcoming bookings. Cancel them first, then delete.' using errcode = '23514';
  end if;

  if exists (select 1 from coaching_enrollments e where e.member_id = p_member_id) then
    raise exception 'This member is enrolled in coaching. Delete that student on the Students page first.' using errcode = '23514';
  end if;

  -- Money that changed hands stays on the books, just no longer tied to a deleted person.
  update payments set member_id = null where member_id = p_member_id and status in ('paid', 'refunded');

  delete from members where id = p_member_id;
end;
$$;

-- get_membership_detail (was 0038_update_membership_full.sql)
create or replace function get_membership_detail(p_membership_id uuid)
returns jsonb
language plpgsql
stable
as $$
declare
  m memberships;
  mem members;
  mp membership_plans;
  pay payments;
  ref_name text;
  creator_name text;
  slot_batch membership_batches;
  slot_court text;
  fee integer;
  settled boolean;
  v_status text;
  timeline jsonb := '[]'::jsonb;
begin
  perform require_page_access_any((select t.facility_id from memberships t where t.id = p_membership_id), array['MEMBERSHIPS_VIEW']);
  select * into m from memberships where id = p_membership_id;
  if m.id is null then
    raise exception 'Membership not found' using errcode = 'P0002';
  end if;

  select * into mem from members where id = m.member_id;
  if m.plan_id is not null then
    select * into mp from membership_plans where id = m.plan_id;
  end if;

  select * into pay from payments
    where membership_id = m.id
    order by coalesce(paid_at, created_at) desc
    limit 1;

  fee := coalesce(m.total_amount_inr, m.membership_fee_inr, mp.price_inr, 0);
  v_status := membership_display_status(m.id, m.status::text, m.start_date, m.end_date, m.duration_days, fee);
  settled := fee = 0 or membership_is_settled(m.id, membership_cycle_start(m.start_date, m.end_date, m.duration_days));

  if m.referral_member_id is not null then
    select full_name into ref_name from members where id = m.referral_member_id;
  end if;
  if m.created_by is not null then
    select full_name into creator_name from profiles where id = m.created_by;
  end if;

  select b.* into slot_batch
  from membership_batch_members bm
  join membership_batches b on b.id = bm.batch_id
  where bm.membership_id = m.id
  order by bm.created_at
  limit 1;
  if slot_batch.id is not null then
    select name into slot_court from courts where id = slot_batch.court_id;
  end if;

  timeline := timeline || jsonb_build_object(
    'label', 'Membership created',
    'actor', coalesce(creator_name, 'Self registered'),
    'at', m.created_at
  );
  if pay.id is not null and pay.paid_at is not null then
    timeline := timeline || jsonb_build_object(
      'label', 'Payment received',
      'actor', coalesce(pay.payment_method, 'Payment'),
      'at', pay.paid_at
    );
  end if;
  if v_status = 'active' and fee > 0 then
    timeline := timeline || jsonb_build_object(
      'label', 'Membership activated',
      'actor', 'System',
      'at', coalesce(pay.paid_at, m.created_at)
    );
  end if;

  return jsonb_build_object(
    'membershipId', m.id,
    'facilityId', m.facility_id,
    'displayStatus', v_status,
    'member', jsonb_build_object(
      'id', mem.id,
      'fullName', mem.full_name,
      'phone', mem.phone,
      'email', mem.email,
      'dateOfBirth', mem.date_of_birth,
      'gender', mem.gender,
      'address', mem.address,
      'status', mem.status,
      'memberSince', mem.created_at
    ),
    'membership', jsonb_build_object(
      'name', coalesce(m.name, mp.name, 'Membership'),
      'membershipType', m.membership_type,
      'rawStatus', m.status,
      'startDate', m.start_date,
      'endDate', m.end_date,
      'durationDays', m.duration_days,
      'maxFamilyMembers', m.max_family_members,
      'description', m.description,
      'membershipFeeInr', coalesce(m.membership_fee_inr, mp.price_inr, 0),
      'registrationFeeInr', coalesce(m.registration_fee_inr, 0),
      'gstPercent', coalesce(m.gst_percent, 0),
      'totalAmountInr', coalesce(m.total_amount_inr, m.membership_fee_inr, mp.price_inr, 0),
      'monthlyPriceInr', coalesce(m.monthly_price_inr, m.membership_fee_inr, mp.price_inr, 0),
      'autoRenew', m.auto_renew,
      'createdAt', m.created_at
    ),
    'payment', case when pay.id is null then null else jsonb_build_object(
      'amountInr', pay.amount_inr,
      'status', pay.status,
      'settled', pay.paid_at is not null,
      'method', pay.payment_method,
      'paidAt', pay.paid_at,
      'createdAt', pay.created_at,
      'transactionId', pay.razorpay_payment_id
    ) end,
    'referralName', ref_name,
    'referralMemberId', m.referral_member_id,
    'createdByName', creator_name,
    'discoverySource', m.discovery_source,
    'paymentReference', m.payment_reference,
    'notes', m.notes,
    'slot', case when slot_batch.id is null then null else jsonb_build_object(
      'batchId', slot_batch.id,
      'courtId', slot_batch.court_id,
      'facilitySportId', slot_batch.facility_sport_id,
      'courtName', slot_court,
      'capacity', slot_batch.capacity,
      'daysOfWeek', slot_batch.days_of_week,
      'startTime', slot_batch.start_time,
      'endTime', slot_batch.end_time
    ) end,
    'timeline', timeline
  );
end;
$$;

-- update_membership_full (was 0038_update_membership_full.sql)
create or replace function update_membership_full(
  p_membership_id uuid,
  p_full_name text,
  p_phone text,
  p_email text,
  p_date_of_birth date,
  p_gender text,
  p_address text,
  p_name text,
  p_membership_type text,
  p_max_family_members integer,
  p_start_date date,
  p_duration_days integer,
  p_description text,
  p_membership_fee_inr integer,
  p_registration_fee_inr integer,
  p_gst_percent numeric,
  p_referral_member_id uuid,
  p_discovery_source text,
  p_notes text,
  p_batch_id uuid default null,
  p_new_batch jsonb default null
) returns memberships
language plpgsql
security definer
set search_path = public
as $$
declare
  m memberships;
  v_member_id uuid;
  computed_end date;
  fee integer := greatest(coalesce(p_membership_fee_inr, 0), 0);
  reg integer := greatest(coalesce(p_registration_fee_inr, 0), 0);
  gst numeric := greatest(coalesce(p_gst_percent, 0), 0);
  gst_amount integer;
  total integer;
  result memberships;
  v_cur_batch_id uuid;
  v_batch_id uuid;
  v_court courts;
  v_days smallint[];
  v_start time;
  v_end time;
  v_capacity integer;
  v_batch_name text;
begin
  perform require_page_access_any((select t.facility_id from memberships t where t.id = p_membership_id), array['MEMBERSHIPS_EDIT']);
  select * into m from memberships where id = p_membership_id;
  if m.id is null then
    raise exception 'Membership not found' using errcode = 'P0002';
  end if;
  if not has_facility_role(m.facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized for this facility.' using errcode = '42501';
  end if;
  if trim(coalesce(p_full_name, '')) = '' or trim(coalesce(p_phone, '')) = '' then
    raise exception 'Member name and phone are required.' using errcode = '23514';
  end if;
  if coalesce(p_duration_days, 0) <= 0 then
    raise exception 'Choose a membership duration.' using errcode = '23514';
  end if;
  if p_batch_id is not null and p_new_batch is not null then
    raise exception 'Pick one time slot, not both.' using errcode = '23514';
  end if;

  v_member_id := m.member_id;

  -- Member — overwrite with the edited values (unlike create's coalesce merge).
  update members set
    full_name = trim(p_full_name),
    phone = trim(p_phone),
    email = nullif(trim(p_email), ''),
    date_of_birth = p_date_of_birth,
    gender = nullif(trim(p_gender), ''),
    address = nullif(trim(p_address), ''),
    updated_at = now()
  where id = v_member_id;

  computed_end := p_start_date + p_duration_days;
  gst_amount := round(fee * gst / 100.0);
  total := fee + gst_amount + reg;

  update memberships set
    name = nullif(trim(p_name), ''),
    membership_type = coalesce(nullif(trim(p_membership_type), ''), 'INDIVIDUAL'),
    max_family_members = greatest(coalesce(p_max_family_members, 1), 1),
    start_date = p_start_date,
    end_date = computed_end,
    duration_days = p_duration_days,
    description = nullif(trim(p_description), ''),
    membership_fee_inr = fee,
    registration_fee_inr = reg,
    gst_percent = gst,
    total_amount_inr = total,
    monthly_price_inr = coalesce(monthly_price_inr, fee),
    referral_member_id = p_referral_member_id,
    discovery_source = nullif(trim(p_discovery_source), ''),
    notes = nullif(trim(p_notes), '')
  where id = p_membership_id
  returning * into result;

  -- ── Reserved court time slot ────────────────────────────────────────────
  select bm.batch_id into v_cur_batch_id
  from membership_batch_members bm
  where bm.membership_id = p_membership_id
  order by bm.created_at
  limit 1;

  if p_new_batch is not null then
    select array_agg(value::smallint) into v_days
      from jsonb_array_elements_text(p_new_batch->'daysOfWeek');
    v_start := (p_new_batch->>'startTime')::time;
    v_end := (p_new_batch->>'endTime')::time;
    v_capacity := (p_new_batch->>'capacity')::integer;

    if v_start is null or v_end is null then
      raise exception 'Time slot start and end are required.' using errcode = '23514';
    end if;
    if coalesce(array_length(v_days, 1), 0) = 0 or not (v_days <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]) then
      raise exception 'Select at least one valid access day for the time slot.' using errcode = '23514';
    end if;
    if v_end <= v_start then
      raise exception 'Time slot end must be after the start.' using errcode = '23514';
    end if;
    if coalesce(v_capacity, 0) < 1 then
      raise exception 'Time slot capacity must be at least 1.' using errcode = '23514';
    end if;

    select * into v_court from courts
      where id = (p_new_batch->>'courtId')::uuid
        and facility_id = m.facility_id
        and facility_sport_id = (p_new_batch->>'facilitySportId')::uuid;
    if v_court.id is null then
      raise exception 'That court does not belong to this facility/sport.' using errcode = '23503';
    end if;

    v_batch_name := coalesce(
      nullif(trim(p_new_batch->>'name'), ''),
      coalesce(nullif(trim(p_name), ''), 'Membership') || ' · '
        || to_char(v_start, 'FMHH12:MI') || '–' || to_char(v_end, 'FMHH12:MI AM')
    );

    insert into membership_batches (
      facility_id, plan_id, facility_sport_id, court_id, name,
      days_of_week, start_time, end_time, capacity, is_active
    ) values (
      m.facility_id, null, v_court.facility_sport_id, v_court.id, v_batch_name,
      v_days, v_start, v_end, v_capacity, true
    ) returning id into v_batch_id;

    if v_cur_batch_id is not null then
      perform remove_batch_member(v_cur_batch_id, v_member_id);
    end if;
    perform assign_batch_member(v_batch_id, v_member_id, p_membership_id);

  elsif p_batch_id is not null then
    if v_cur_batch_id is distinct from p_batch_id then
      if not exists (
        select 1 from membership_batches
        where id = p_batch_id and facility_id = m.facility_id and is_active
      ) then
        raise exception 'That time slot is not available.' using errcode = '23503';
      end if;
      if v_cur_batch_id is not null then
        perform remove_batch_member(v_cur_batch_id, v_member_id);
      end if;
      perform assign_batch_member(p_batch_id, v_member_id, p_membership_id);
    end if;

  else
    -- Slot cleared.
    if v_cur_batch_id is not null then
      perform remove_batch_member(v_cur_batch_id, v_member_id);
    end if;
  end if;

  return result;
end;
$$;

-- cancel_membership (was 0023_cancellation_refunds.sql)
create or replace function cancel_membership(
  p_membership_id uuid,
  p_reason text default null,
  p_refund_amount_minor integer default null,
  p_override_reason text default null
) returns memberships
language plpgsql
as $$
declare
  m memberships;
  po payment_orders;
  max_refundable integer;
begin
  perform require_page_access_any((select t.facility_id from memberships t where t.id = p_membership_id), array['MEMBERSHIPS_CANCEL']);
  update memberships set status = 'cancelled'
    where id = p_membership_id and status in ('active', 'pending')
    returning * into m;
  if m.id is null then
    raise exception 'Membership not found or not cancellable.' using errcode = 'P0002';
  end if;

  if p_refund_amount_minor is not null and p_refund_amount_minor > 0 then
    select po2.* into po from payment_orders po2
      where po2.member_id = m.member_id and po2.plan_id = m.plan_id and po2.source_type = 'MEMBERSHIP'
        and po2.status in ('COMPLETED', 'SETTLEMENT_EXCEPTION', 'PARTIALLY_REFUNDED')
      order by po2.created_at desc limit 1;
    if po.id is null or po.razorpay_payment_id is null then
      raise exception 'No captured Razorpay payment found for this membership.' using errcode = '23514';
    end if;
    max_refundable := refundable_amount(po.id);
    if p_refund_amount_minor > max_refundable then
      raise exception 'The maximum refundable amount is %.', max_refundable using errcode = '23514';
    end if;
    perform request_refund(po.id, p_refund_amount_minor, 'OWNER_OVERRIDE'::refund_reason, po.source_type, m.id, true, p_override_reason, null);
  end if;

  return m;
end;
$$;

-- record_membership_payment (was 0119_membership_autopay.sql)
create or replace function record_membership_payment(p_membership_id uuid, p_method text default 'cash')
returns memberships
language plpgsql
security definer
set search_path = public
as $$
declare
  m memberships;
  mp membership_plans;
  amt integer;
  cyc integer;
  pending payments;
  result memberships;
begin
  perform require_page_access_any((select t.facility_id from memberships t where t.id = p_membership_id), array['FINANCE_RECORD_PAYMENT', 'MEMBERSHIPS_EDIT']);
  select * into m from memberships where id = p_membership_id;
  if m.id is null then
    raise exception 'Membership not found' using errcode = 'P0002';
  end if;
  if not has_facility_role(m.facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized to record payments.' using errcode = '42501';
  end if;
  if m.status = 'cancelled' then
    raise exception 'This membership is cancelled.' using errcode = '23514';
  end if;

  if m.plan_id is not null then
    select * into mp from membership_plans where id = m.plan_id;
  end if;
  amt := greatest(coalesce(m.total_amount_inr, m.monthly_price_inr, m.membership_fee_inr, mp.price_inr, 0), 0);
  cyc := coalesce(nullif(m.duration_days, 0), greatest(m.end_date - m.start_date, 30));

  select * into pending from payments
    where membership_id = m.id and (status <> 'paid' or paid_at is null)
    order by created_at desc
    limit 1;

  if pending.id is not null then
    update payments
      set status = 'paid',
          paid_at = now(),
          payment_method = coalesce(nullif(trim(p_method), ''), payment_method)
      where id = pending.id;
  else
    insert into payments (facility_id, member_id, membership_id, amount_inr, status, payment_method, paid_at)
    values (m.facility_id, m.member_id, m.id, amt, 'paid', coalesce(nullif(trim(p_method), ''), 'cash'), now());
  end if;

  if m.end_date < current_date then
    update memberships
      set end_date = add_membership_period(greatest(m.end_date, current_date), cyc),
          status = 'active'
      where id = m.id;
  elsif m.status <> 'active' then
    update memberships set status = 'active' where id = m.id;
  end if;

  select * into result from memberships where id = m.id;
  return result;
end;
$$;

-- get_membership_session_detail (was 0037_membership_session_detail_page.sql)
create or replace function get_membership_session_detail(p_batch_id uuid)
returns jsonb
language plpgsql
stable
as $$
declare
  b membership_batches;
  court_name text;
  sport_name text;
  plan_name text;
  creator text;
  facility_name text;
  facility_address text;
  roster integer;
  today_guests integer;
  today_mat_id uuid;
  today_released integer;
  next_date date;
  d date;
begin
  perform require_page_access_any((select t.facility_id from membership_batches t where t.id = p_batch_id), array['MEMBERSHIP_SESSIONS_VIEW']);
  select * into b from membership_batches where id = p_batch_id;
  if b.id is null then
    raise exception 'Session not found' using errcode = 'P0002';
  end if;

  select c.name into court_name from courts c where c.id = b.court_id;
  select coalesce(fs.custom_sport_name, sp.name) into sport_name
    from facility_sports fs join sports sp on sp.id = fs.sport_id where fs.id = b.facility_sport_id;
  if b.plan_id is not null then
    select name into plan_name from membership_plans where id = b.plan_id;
  end if;
  if b.created_by is not null then
    select full_name into creator from profiles where id = b.created_by;
  end if;
  select f.name,
         nullif(concat_ws(', ', nullif(trim(f.address), ''), nullif(trim(f.city), '')), '')
    into facility_name, facility_address
    from facilities f where f.id = b.facility_id;

  roster := membership_batch_roster_count(b.id);

  select s.id, s.released_capacity into today_mat_id, today_released
    from membership_sessions s where s.batch_id = b.id and s.session_date = current_date;
  select count(*) into today_guests from membership_session_bookings mb
    where mb.session_id = today_mat_id and mb.participant_type = 'GUEST' and mb.status = 'CONFIRMED';

  next_date := null;
  for i in 1..14 loop
    d := current_date + i;
    if extract(dow from d)::smallint = any(b.days_of_week)
       and not exists (select 1 from membership_batch_blocked_dates x where x.batch_id = b.id and x.blocked_date = d) then
      next_date := d;
      exit;
    end if;
  end loop;

  return jsonb_build_object(
    'batchId', b.id,
    'facilityId', b.facility_id,
    'facilityName', facility_name,
    'facilityAddress', facility_address,
    'name', b.name,
    'notes', b.notes,
    'courtId', b.court_id,
    'courtName', court_name,
    'facilitySportId', b.facility_sport_id,
    'sportName', sport_name,
    'planName', plan_name,
    'daysOfWeek', b.days_of_week,
    'startTime', b.start_time,
    'endTime', b.end_time,
    'capacity', b.capacity,
    'isActive', b.is_active,
    'createdByName', creator,
    'createdAt', b.created_at,
    'updatedAt', b.updated_at,
    'rosterCount', roster,
    'guestsBookedToday', coalesce(today_guests, 0),
    'releasedToday', coalesce(today_released, 0),
    'availableToRelease', greatest(b.capacity - roster - coalesce(today_released, 0), 0),
    'runsToday', (extract(dow from current_date)::smallint = any(b.days_of_week)
      and not exists (select 1 from membership_batch_blocked_dates x where x.batch_id = b.id and x.blocked_date = current_date)),
    'nextOccurrenceDate', next_date
  );
end;
$$;

-- list_membership_session_activity (was 0036_membership_sessions_dashboard.sql, plain SQL — now guarded through a private implementation)
create or replace function _list_membership_session_activity_impl(p_batch_id uuid, p_limit integer default 30)
returns table (
  kind text,
  actor text,
  detail text,
  at timestamptz
)
language sql
stable
as $$
  select * from (
    select 'created'::text as kind, null::text as actor,
           'Session created'::text as detail, b.created_at as at
    from membership_batches b where b.id = p_batch_id
    union all
    select 'member_added', null, mem.full_name || ' added to the session', bm.created_at
    from membership_batch_members bm join members mem on mem.id = bm.member_id
    where bm.batch_id = p_batch_id
    union all
    select
      case when mb.participant_type = 'GUEST' then 'guest_booking' else 'member_booking' end,
      p.full_name,
      coalesce(mem.full_name, g.name, 'Guest') || ' — ' || to_char(s.session_date, 'DD Mon'),
      mb.created_at
    from membership_session_bookings mb
    join membership_sessions s on s.id = mb.session_id
    left join members mem on mem.id = mb.member_id
    left join guest_players g on g.id = mb.guest_player_id
    left join profiles p on p.id = mb.created_by
    where s.batch_id = p_batch_id
  ) t
  order by at desc
  limit greatest(p_limit, 1);
$$;
revoke all on function _list_membership_session_activity_impl(uuid, integer) from public, anon, authenticated;
create or replace function list_membership_session_activity(p_batch_id uuid, p_limit integer default 30)
returns table (
  kind text,
  actor text,
  detail text,
  at timestamptz
) language plpgsql stable security definer set search_path = public as $w$
begin
  perform require_page_access_any((select t.facility_id from membership_batches t where t.id = p_batch_id), array['MEMBERSHIP_SESSIONS_VIEW']);
  return query select * from _list_membership_session_activity_impl(p_batch_id => p_batch_id, p_limit => p_limit);
end;
$w$;

