-- book_guest_slot (was 0014_membership_sessions.sql)
create or replace function book_guest_slot(p_batch_id uuid, p_session_date date, p_guest_player_id uuid)
returns membership_session_bookings
language plpgsql
as $$
declare
  session membership_sessions;
  guest guest_players;
  fac facilities;
  guest_booked_count integer;
  price integer;
  session_start timestamptz;
  session_end timestamptz;
  result membership_session_bookings;
begin
  perform require_page_access_any((select t.facility_id from membership_batches t where t.id = p_batch_id), array['MEMBERSHIP_SESSIONS_EDIT']);
  session := get_or_create_membership_session(p_batch_id, p_session_date);
  select * into session from membership_sessions where id = session.id for update;

  select * into fac from facilities where id = session.facility_id;
  select * into guest from guest_players where id = p_guest_player_id and facility_id = session.facility_id;
  if guest.id is null then
    raise exception 'That guest does not belong to this facility.' using errcode = '23503';
  end if;

  select count(*) into guest_booked_count from membership_session_bookings
    where session_id = session.id and participant_type = 'GUEST' and status = 'CONFIRMED';

  if guest_booked_count >= session.released_capacity then
    raise exception 'No guest slots are currently available for this session.' using errcode = '23514';
  end if;

  session_start := (p_session_date::text || ' ' || session.start_time::text)::timestamp at time zone coalesce(fac.timezone, 'Asia/Kolkata');
  session_end := (p_session_date::text || ' ' || session.end_time::text)::timestamp at time zone coalesce(fac.timezone, 'Asia/Kolkata');
  price := resolve_booking_price(session.facility_sport_id, session.court_id, session_start, session_end, fac.timezone);

  insert into membership_session_bookings (
    session_id, facility_id, participant_type, guest_player_id, status, slot_source, amount_minor, currency, created_by
  ) values (
    session.id, session.facility_id, 'GUEST', p_guest_player_id, 'CONFIRMED', 'RELEASED', price, fac.currency, auth.uid()
  ) returning * into result;

  return result;
end;
$$;

-- book_membership_slot (was 0035_membership_slot_roster_count.sql)
create or replace function book_membership_slot(p_batch_id uuid, p_session_date date, p_member_id uuid)
returns membership_session_bookings
language plpgsql
as $$
declare
  session membership_sessions;
  used integer;
  result membership_session_bookings;
begin
  perform require_page_access_any((select t.facility_id from membership_batches t where t.id = p_batch_id), array['MEMBERSHIP_SESSIONS_EDIT']);
  if not exists (select 1 from membership_batch_members where batch_id = p_batch_id and member_id = p_member_id) then
    raise exception 'This member is not assigned to this membership batch.' using errcode = '23514';
  end if;

  session := get_or_create_membership_session(p_batch_id, p_session_date);
  select * into session from membership_sessions where id = session.id for update;

  select greatest(
    (select count(*) from membership_session_bookings
       where session_id = session.id and participant_type = 'MEMBER' and status = 'CONFIRMED'),
    (select count(*) from membership_batch_members where batch_id = p_batch_id)
  ) into used;

  if used >= session.capacity then
    raise exception 'Membership capacity is full for this session.' using errcode = '23514';
  end if;

  insert into membership_session_bookings (session_id, facility_id, participant_type, member_id, status, slot_source, created_by)
  values (session.id, session.facility_id, 'MEMBER', p_member_id, 'CONFIRMED', 'MEMBERSHIP', auth.uid())
  returning * into result;

  return result;
end;
$$;

-- list_guest_bookings_admin (was 0054_guest_bookings_partial_payments.sql, plain SQL — now guarded through a private implementation)
create or replace function _list_guest_bookings_admin_impl(
  p_facility_id uuid,
  p_search text default null,
  p_facility_sport_id uuid default null,
  p_court_id uuid default null,
  p_status text default null,
  p_payment_status text default null,
  p_from date default null,
  p_to date default null,
  p_limit integer default 10,
  p_offset integer default 0
)
returns table (
  booking_id uuid,
  code text,
  guest_name text,
  guest_phone text,
  sport_name text,
  court_name text,
  start_time timestamptz,
  end_time timestamptz,
  party_size integer,
  amount_minor integer,
  paid_minor bigint,
  outstanding_minor bigint,
  currency text,
  payment_status text,
  payment_method text,
  status text,
  source text,
  total_count bigint
)
language sql
stable
as $$
  with rows as (
    select
      b.id,
      'GBK' || upper(substr(replace(b.id::text, '-', ''), 1, 4)) as code,
      coalesce(b.guest_name, 'Guest') as guest_name,
      b.guest_phone,
      coalesce(fs.custom_sport_name, sp.name) as sport_name,
      c.name as court_name,
      b.start_time,
      b.end_time,
      b.party_size,
      b.amount_minor,
      -- What actually arrived. A booking flagged PAID with no payments row
      -- behind it (create_booking accepts p_payment_status) still counts as
      -- settled, so historical rows are not reported as owing.
      greatest(
        coalesce((
          select sum(p.amount_inr) * 100 from payments p
          where p.booking_id = b.id and p.status = 'paid'
        ), 0),
        case when b.payment_status = 'PAID' then coalesce(b.amount_minor, 0) else 0 end
      )::bigint as paid_minor,
      b.currency,
      b.payment_method,
      b.status::text as status,
      'COURT'::text as source
    from bookings b
    join courts c on c.id = b.court_id
    left join facility_sports fs on fs.id = c.facility_sport_id
    left join sports sp on sp.id = fs.sport_id
    where b.facility_id = p_facility_id
      and b.customer_type = 'GUEST'
      and (p_facility_sport_id is null or c.facility_sport_id = p_facility_sport_id)
      and (p_court_id is null or b.court_id = p_court_id)
      and (p_status is null or b.status::text = p_status)
      and (p_from is null or b.start_time::date >= p_from)
      and (p_to is null or b.start_time::date <= p_to)
      and (
        p_search is null or trim(p_search) = '' or
        b.guest_name ilike '%' || trim(p_search) || '%' or
        b.guest_phone ilike '%' || trim(p_search) || '%' or
        ('GBK' || upper(substr(replace(b.id::text, '-', ''), 1, 4))) ilike '%' || trim(p_search) || '%'
      )

    union all

    select
      msb.id,
      'GSB' || upper(substr(replace(msb.id::text, '-', ''), 1, 4)),
      coalesce(gp.name, 'Guest'),
      gp.phone,
      coalesce(fs.custom_sport_name, sp.name),
      c.name,
      (ms.session_date::text || ' ' || ms.start_time::text)::timestamp
        at time zone coalesce(f.timezone, 'Asia/Kolkata'),
      (ms.session_date::text || ' ' || ms.end_time::text)::timestamp
        at time zone coalesce(f.timezone, 'Asia/Kolkata'),
      1,
      msb.amount_minor,
      greatest(
        coalesce((
          select sum(p.amount_inr) * 100 from payments p
          where p.membership_session_booking_id = msb.id and p.status = 'paid'
        ), 0),
        case when msb.payment_status = 'PAID' then coalesce(msb.amount_minor, 0) else 0 end
      )::bigint,
      msb.currency,
      msb.payment_method,
      case when msb.status = 'CANCELLED' then 'cancelled' else 'confirmed' end,
      'SESSION'::text
    from membership_session_bookings msb
    join membership_sessions ms on ms.id = msb.session_id
    join facilities f on f.id = msb.facility_id
    join courts c on c.id = ms.court_id
    left join guest_players gp on gp.id = msb.guest_player_id
    left join facility_sports fs on fs.id = ms.facility_sport_id
    left join sports sp on sp.id = fs.sport_id
    where msb.facility_id = p_facility_id
      and msb.participant_type = 'GUEST'
      and msb.slot_source = 'RELEASED'
      and (p_facility_sport_id is null or ms.facility_sport_id = p_facility_sport_id)
      and (p_court_id is null or ms.court_id = p_court_id)
      and (
        p_status is null
        or p_status = (case when msb.status = 'CANCELLED' then 'cancelled' else 'confirmed' end)
      )
      and (p_from is null or ms.session_date >= p_from)
      and (p_to is null or ms.session_date <= p_to)
      and (
        p_search is null or trim(p_search) = '' or
        gp.name ilike '%' || trim(p_search) || '%' or
        gp.phone ilike '%' || trim(p_search) || '%' or
        ('GSB' || upper(substr(replace(msb.id::text, '-', ''), 1, 4))) ilike '%' || trim(p_search) || '%'
      )
  ),
  settled as (
    select
      r.*,
      greatest(coalesce(r.amount_minor, 0) - r.paid_minor, 0)::bigint as outstanding_minor,
      -- Derived, so a part payment has somewhere to be reported without
      -- widening the stored flag.
      case
        when r.paid_minor >= coalesce(r.amount_minor, 0) and coalesce(r.amount_minor, 0) > 0 then 'PAID'
        when r.paid_minor > 0 then 'PARTIALLY_PAID'
        else 'PENDING'
      end as derived_payment_status
    from rows r
  ),
  filtered as (
    select * from settled s
    where p_payment_status is null or s.derived_payment_status = p_payment_status
  )
  select
    f.id, f.code, f.guest_name, f.guest_phone, f.sport_name, f.court_name,
    f.start_time, f.end_time, f.party_size, f.amount_minor,
    f.paid_minor, f.outstanding_minor, f.currency,
    f.derived_payment_status, f.payment_method, f.status, f.source,
    count(*) over () as total_count
  from filtered f
  order by f.start_time desc
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
$$;
revoke all on function _list_guest_bookings_admin_impl(uuid, text, uuid, uuid, text, text, date, date, integer, integer) from public, anon, authenticated;
create or replace function list_guest_bookings_admin(p_facility_id uuid, p_search text default null, p_facility_sport_id uuid default null, p_court_id uuid default null, p_status text default null, p_payment_status text default null, p_from date default null, p_to date default null, p_limit integer default 10, p_offset integer default 0)
returns table (
  booking_id uuid,
  code text,
  guest_name text,
  guest_phone text,
  sport_name text,
  court_name text,
  start_time timestamptz,
  end_time timestamptz,
  party_size integer,
  amount_minor integer,
  paid_minor bigint,
  outstanding_minor bigint,
  currency text,
  payment_status text,
  payment_method text,
  status text,
  source text,
  total_count bigint
) language plpgsql stable security definer set search_path = public as $w$
begin
  perform require_page_access_any(p_facility_id, array['GUEST_BOOKINGS_VIEW']);
  return query select * from _list_guest_bookings_admin_impl(p_facility_id => p_facility_id, p_search => p_search, p_facility_sport_id => p_facility_sport_id, p_court_id => p_court_id, p_status => p_status, p_payment_status => p_payment_status, p_from => p_from, p_to => p_to, p_limit => p_limit, p_offset => p_offset);
end;
$w$;

-- get_guest_bookings_summary (was 0054_guest_bookings_partial_payments.sql, plain SQL — now guarded through a private implementation)
create or replace function _get_guest_bookings_summary_impl(p_facility_id uuid, p_from date, p_to date)
returns jsonb
language sql
stable
as $$
  with span as (select (p_to - p_from) as days),
  all_rows as (
    select
      b.start_time::date as on_date,
      b.status::text as status,
      b.amount_minor,
      greatest(
        coalesce((
          select sum(p.amount_inr) * 100 from payments p
          where p.booking_id = b.id and p.status = 'paid'
        ), 0),
        case when b.payment_status = 'PAID' then coalesce(b.amount_minor, 0) else 0 end
      )::bigint as paid_minor
    from bookings b
    where b.facility_id = p_facility_id and b.customer_type = 'GUEST'
    union all
    select
      ms.session_date,
      case when msb.status = 'CANCELLED' then 'cancelled' else 'confirmed' end,
      msb.amount_minor,
      greatest(
        coalesce((
          select sum(p.amount_inr) * 100 from payments p
          where p.membership_session_booking_id = msb.id and p.status = 'paid'
        ), 0),
        case when msb.payment_status = 'PAID' then coalesce(msb.amount_minor, 0) else 0 end
      )::bigint
    from membership_session_bookings msb
    join membership_sessions ms on ms.id = msb.session_id
    where msb.facility_id = p_facility_id
      and msb.participant_type = 'GUEST'
      and msb.slot_source = 'RELEASED'
  ),
  gb as (select r.* from all_rows r, span where r.on_date between p_from and p_to),
  prev as (
    select r.* from all_rows r, span
    where r.on_date between (p_from - span.days - 1) and (p_from - 1)
  ),
  cur as (select count(*)::int as cnt, coalesce(sum(paid_minor), 0)::bigint as rev from gb),
  pre as (select count(*)::int as cnt, coalesce(sum(paid_minor), 0)::bigint as rev from prev)
  select jsonb_build_object(
    'total', (select cnt from cur),
    'confirmed', (select count(*) from gb where status = 'confirmed'),
    'completed', (select count(*) from gb where status = 'completed'),
    'cancelled', (select count(*) from gb where status = 'cancelled'),
    'pending', (select count(*) from gb where status = 'pending'),
    'totalRevenueMinor', (select rev from cur),
    'avgPerBookingMinor', coalesce((select round(avg(paid_minor)) from gb where paid_minor > 0), 0),
    'highestBookingMinor', coalesce((select max(paid_minor) from gb), 0),
    'totalChangePct', (select case when pre.cnt = 0 then null else round((cur.cnt - pre.cnt) * 100.0 / pre.cnt) end from cur, pre),
    'revenueChangePct', (select case when pre.rev = 0 then null else round((cur.rev - pre.rev) * 100.0 / pre.rev) end from cur, pre),
    'trend', coalesce((
      select jsonb_agg(jsonb_build_object('date', d, 'amountMinor', amt) order by d)
      from (
        select on_date as d, coalesce(sum(paid_minor), 0)::bigint as amt
        from gb group by on_date
      ) t
    ), '[]'::jsonb)
  );
$$;
revoke all on function _get_guest_bookings_summary_impl(uuid, date, date) from public, anon, authenticated;
create or replace function get_guest_bookings_summary(p_facility_id uuid, p_from date, p_to date)
returns jsonb language plpgsql stable security definer set search_path = public as $w$
begin
  perform require_page_access_any(p_facility_id, array['GUEST_BOOKINGS_VIEW']);
  return _get_guest_bookings_summary_impl(p_facility_id => p_facility_id, p_from => p_from, p_to => p_to);
end;
$w$;

-- find_or_create_guest (was 0011_guest_players.sql)
create or replace function find_or_create_guest(
  p_facility_id uuid,
  p_name text,
  p_phone text,
  p_email text default null,
  p_notes text default null
) returns guest_players
language plpgsql
as $$
declare
  result guest_players;
  normalized_phone text := nullif(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), '');
begin
  perform require_page_access_any(p_facility_id, array['GUEST_BOOKINGS_CREATE', 'BOOKINGS_CREATE', 'GUEST_PLAYERS_EDIT']);
  if trim(coalesce(p_name, '')) = '' then
    raise exception 'Guest name is required.' using errcode = '23514';
  end if;

  if normalized_phone is not null then
    select * into result from guest_players
      where facility_id = p_facility_id
        and regexp_replace(coalesce(phone, ''), '\D', '', 'g') = normalized_phone;
    if result.id is not null then
      return result;
    end if;
  end if;

  insert into guest_players (facility_id, name, phone, email, notes)
  values (p_facility_id, trim(p_name), p_phone, p_email, p_notes)
  returning * into result;

  return result;
end;
$$;

-- get_guest_stats (was 0011_guest_players.sql, plain SQL — now guarded through a private implementation)
create or replace function _get_guest_stats_impl(p_guest_id uuid) returns table (
  total_visits bigint,
  total_bookings bigint,
  last_visit timestamptz,
  total_amount_minor bigint,
  pending_amount_minor bigint,
  sports jsonb
)
language sql
stable
as $$
  select
    count(*) filter (where b.status in ('confirmed', 'completed')) as total_visits,
    count(*) as total_bookings,
    max(b.start_time) filter (where b.status in ('confirmed', 'completed')) as last_visit,
    coalesce(sum(b.amount_minor) filter (where b.status in ('confirmed', 'completed')), 0) as total_amount_minor,
    coalesce(
      sum(b.amount_minor) filter (
        where b.status in ('confirmed', 'completed') and b.payment_status = 'PENDING'
      ), 0
    ) as pending_amount_minor,
    coalesce(
      jsonb_agg(distinct jsonb_build_object('sportId', s.id, 'sportName', s.name))
        filter (where s.id is not null),
      '[]'::jsonb
    ) as sports
  from bookings b
  left join facility_sports fs on fs.id = b.facility_sport_id
  left join sports s on s.id = fs.sport_id
  where b.guest_player_id = p_guest_id;
$$;
revoke all on function _get_guest_stats_impl(uuid) from public, anon, authenticated;
create or replace function get_guest_stats(p_guest_id uuid)
returns table (
  total_visits bigint,
  total_bookings bigint,
  last_visit timestamptz,
  total_amount_minor bigint,
  pending_amount_minor bigint,
  sports jsonb
) language plpgsql stable security definer set search_path = public as $w$
begin
  perform require_page_access_any((select t.facility_id from guest_players t where t.id = p_guest_id), array['GUEST_PLAYERS_VIEW', 'GUEST_BOOKINGS_VIEW']);
  return query select * from _get_guest_stats_impl(p_guest_id => p_guest_id);
end;
$w$;

-- update_guest (was 0011_guest_players.sql)
create or replace function update_guest(
  p_guest_id uuid,
  p_name text,
  p_phone text,
  p_email text,
  p_notes text,
  p_status text
) returns guest_players
language plpgsql
as $$
declare
  result guest_players;
begin
  perform require_page_access_any((select t.facility_id from guest_players t where t.id = p_guest_id), array['GUEST_PLAYERS_EDIT']);
  if trim(coalesce(p_name, '')) = '' then
    raise exception 'Guest name is required.' using errcode = '23514';
  end if;

  update guest_players
  set name = trim(p_name),
      phone = p_phone,
      email = p_email,
      notes = p_notes,
      status = coalesce(p_status, status),
      updated_at = now()
  where id = p_guest_id
  returning * into result;

  if result.id is null then
    raise exception 'Guest not found' using errcode = 'P0002';
  end if;

  return result;
end;
$$;

-- create_booking (was 0083_coaching_sessions.sql)
create or replace function create_booking(
  p_facility_id uuid,
  p_court_id uuid,
  p_start_time timestamptz,
  p_end_time timestamptz,
  p_customer_type text,
  p_member_id uuid,
  p_guest_name text,
  p_guest_phone text,
  p_notes text,
  p_payment_status text default 'PENDING',
  p_guest_player_id uuid default null,
  p_party_size integer default 1,
  p_payment_method text default null
) returns bookings
language plpgsql
as $$
declare
  result bookings;
  fac facilities;
  court courts;
  price integer;
  guest guest_players;
  v_guest_name text := p_guest_name;
  v_guest_phone text := p_guest_phone;
begin
  perform require_page_access_any(p_facility_id, array['BOOKINGS_CREATE', 'GUEST_BOOKINGS_CREATE', 'COACHING_CREATE_SESSION', 'COACHING_EDIT_SESSION', 'MEMBERSHIPS_CREATE', 'MEMBERSHIP_SESSIONS_EDIT']);
  if p_end_time <= p_start_time then
    raise exception 'End time must be after start time.' using errcode = '23514';
  end if;

  select * into fac from facilities where id = p_facility_id;
  if fac.id is null then
    raise exception 'facility % does not exist', p_facility_id using errcode = '23503';
  end if;

  select * into court from courts where id = p_court_id and facility_id = p_facility_id;
  if court.id is null then
    raise exception 'court % does not exist for this facility', p_court_id using errcode = '23503';
  end if;

  -- Serialize against a coaching session being created for the same court at
  -- the same instant (spec §50). Released at transaction end.
  perform pg_advisory_xact_lock(_coaching_court_lock_key(p_court_id));

  if p_guest_player_id is not null then
    select * into guest from guest_players where id = p_guest_player_id and facility_id = p_facility_id;
    if guest.id is null then
      raise exception 'guest % does not exist for this facility', p_guest_player_id using errcode = '23503';
    end if;
    v_guest_name := guest.name;
    v_guest_phone := guest.phone;
  end if;

  if not booking_window_fits_operating_hours(p_facility_id, p_court_id, p_start_time, p_end_time) then
    raise exception 'Selected time is outside this court''s operating hours.' using errcode = '23514';
  end if;

  if court_has_active_membership_window(p_court_id, p_start_time, p_end_time, fac.timezone) then
    raise exception 'This time is reserved for a membership session. Use guest slot booking for this court/time instead.' using errcode = '23514';
  end if;

  if court_has_active_maintenance_block(p_court_id, p_start_time, p_end_time) then
    raise exception 'This court is under maintenance during the selected time.' using errcode = '23514';
  end if;

  if court_has_active_coaching_session(p_court_id, p_start_time, p_end_time) then
    raise exception 'This court is reserved for a coaching session during the selected time.' using errcode = '23514';
  end if;

  price := resolve_booking_price(court.facility_sport_id, p_court_id, p_start_time, p_end_time, fac.timezone);

  insert into bookings (
    facility_id, court_id, member_id, start_time, end_time, status,
    customer_type, guest_name, guest_phone, guest_player_id,
    amount_minor, currency, notes, created_by, payment_status,
    party_size, payment_method
  ) values (
    p_facility_id, p_court_id, p_member_id, p_start_time, p_end_time, 'confirmed',
    coalesce(p_customer_type, 'MEMBER'), v_guest_name, v_guest_phone, p_guest_player_id,
    price, fac.currency, p_notes, auth.uid(), coalesce(p_payment_status, 'PENDING'),
    greatest(coalesce(p_party_size, 1), 1), nullif(trim(p_payment_method), '')
  ) returning * into result;

  return result;
end;
$$;

-- reschedule_booking (was 0083_coaching_sessions.sql)
create or replace function reschedule_booking(
  p_booking_id uuid,
  p_new_court_id uuid,
  p_new_start_time timestamptz,
  p_new_end_time timestamptz
) returns bookings
language plpgsql
as $$
declare
  result bookings;
  fac facilities;
  court courts;
  price integer;
begin
  perform require_page_access_any((select t.facility_id from bookings t where t.id = p_booking_id), array['BOOKINGS_EDIT', 'GUEST_BOOKINGS_EDIT', 'COACHING_EDIT_SESSION', 'COACHING_CREATE_SESSION']);
  if p_new_end_time <= p_new_start_time then
    raise exception 'End time must be after start time.' using errcode = '23514';
  end if;

  select * into result from bookings where id = p_booking_id;
  if result.id is null then
    raise exception 'booking % does not exist', p_booking_id using errcode = '23503';
  end if;
  if result.status not in ('pending', 'confirmed') then
    raise exception 'Only a pending or confirmed booking can be rescheduled.' using errcode = '23514';
  end if;

  select * into fac from facilities where id = result.facility_id;
  select * into court from courts where id = p_new_court_id and facility_id = result.facility_id;
  if court.id is null then
    raise exception 'court % does not exist for this facility', p_new_court_id using errcode = '23503';
  end if;

  perform pg_advisory_xact_lock(_coaching_court_lock_key(p_new_court_id));

  if not booking_window_fits_operating_hours(result.facility_id, p_new_court_id, p_new_start_time, p_new_end_time) then
    raise exception 'Selected time is outside this court''s operating hours.' using errcode = '23514';
  end if;

  if court_has_active_membership_window(p_new_court_id, p_new_start_time, p_new_end_time, fac.timezone) then
    raise exception 'This time is reserved for a membership session. Use guest slot booking for this court/time instead.' using errcode = '23514';
  end if;

  if court_has_active_maintenance_block(p_new_court_id, p_new_start_time, p_new_end_time) then
    raise exception 'This court is under maintenance during the selected time.' using errcode = '23514';
  end if;

  if court_has_active_coaching_session(p_new_court_id, p_new_start_time, p_new_end_time) then
    raise exception 'This court is reserved for a coaching session during the selected time.' using errcode = '23514';
  end if;

  price := resolve_booking_price(court.facility_sport_id, p_new_court_id, p_new_start_time, p_new_end_time, fac.timezone);

  update bookings
  set court_id = p_new_court_id,
      start_time = p_new_start_time,
      end_time = p_new_end_time,
      amount_minor = price
  where id = p_booking_id
  returning * into result;

  return result;
end;
$$;

-- cancel_booking (was 0023_cancellation_refunds.sql)
create or replace function cancel_booking(
  p_booking_id uuid,
  p_reason text default null,
  p_refund_override_percent integer default null,
  p_override_reason text default null
) returns bookings
language plpgsql
as $$
declare
  b bookings;
  po payment_orders;
  pct integer;
  refund_amount integer;
  hours_until numeric;
begin
  perform require_page_access_any((select t.facility_id from bookings t where t.id = p_booking_id), array['BOOKINGS_CANCEL', 'GUEST_BOOKINGS_CANCEL', 'COACHING_CANCEL_SESSION', 'MEMBERSHIPS_CANCEL']);
  select * into b from bookings where id = p_booking_id for update;
  if b.id is null then
    raise exception 'Booking not found.' using errcode = 'P0002';
  end if;
  if b.status not in ('pending', 'confirmed') then
    raise exception 'This booking cannot be cancelled.' using errcode = '23514';
  end if;

  update bookings set status = 'cancelled', cancellation_reason = p_reason where id = b.id returning * into b;

  select * into po from payment_orders
    where booking_id = b.id and status in ('COMPLETED', 'SETTLEMENT_EXCEPTION', 'PARTIALLY_REFUNDED')
    order by created_at desc limit 1;

  if po.id is not null and po.razorpay_payment_id is not null then
    hours_until := extract(epoch from (b.start_time - now())) / 3600.0;
    if p_refund_override_percent is not null then
      pct := greatest(0, least(100, p_refund_override_percent));
    else
      pct := refund_percent_for_policy(b.facility_id, hours_until);
    end if;

    if pct > 0 then
      refund_amount := round(refundable_amount(po.id) * pct / 100.0)::integer;
      if refund_amount > 0 then
        perform request_refund(
          po.id, refund_amount,
          case when p_refund_override_percent is not null then 'OWNER_OVERRIDE' else 'CUSTOMER_CANCELLATION' end::refund_reason,
          po.source_type, b.id,
          p_refund_override_percent is not null, p_override_reason, pct
        );
      end if;
    end if;
  end if;

  return b;
end;
$$;

-- complete_guest_booking (was 0041_guest_booking_actions.sql)
create or replace function complete_guest_booking(p_booking_id uuid)
returns bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  b bookings;
begin
  perform require_page_access_any((select t.facility_id from bookings t where t.id = p_booking_id), array['GUEST_BOOKINGS_EDIT', 'BOOKINGS_EDIT']);
  select * into b from bookings where id = p_booking_id;
  if b.id is null then
    raise exception 'Booking not found' using errcode = 'P0002';
  end if;
  if not has_facility_role(b.facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized.' using errcode = '42501';
  end if;
  if b.status = 'cancelled' then
    raise exception 'A cancelled booking cannot be completed.' using errcode = '23514';
  end if;

  update bookings set status = 'completed', updated_at = now()
  where id = p_booking_id
  returning * into b;
  return b;
end;
$$;

-- duplicate_guest_booking (was 0041_guest_booking_actions.sql)
create or replace function duplicate_guest_booking(
  p_booking_id uuid,
  p_new_start timestamptz,
  p_new_end timestamptz
) returns bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  src bookings;
  fac facilities;
  court courts;
  price integer;
  result bookings;
begin
  perform require_page_access_any((select t.facility_id from bookings t where t.id = p_booking_id), array['GUEST_BOOKINGS_EDIT', 'BOOKINGS_EDIT']);
  select * into src from bookings where id = p_booking_id;
  if src.id is null then
    raise exception 'Booking not found' using errcode = 'P0002';
  end if;
  if not has_facility_role(src.facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized.' using errcode = '42501';
  end if;
  if p_new_end <= p_new_start then
    raise exception 'End time must be after start time.' using errcode = '23514';
  end if;

  select * into fac from facilities where id = src.facility_id;
  select * into court from courts where id = src.court_id;

  if not booking_window_fits_operating_hours(src.facility_id, src.court_id, p_new_start, p_new_end) then
    raise exception 'Selected time is outside this court''s operating hours.' using errcode = '23514';
  end if;
  if court_has_active_membership_window(src.court_id, p_new_start, p_new_end, fac.timezone) then
    raise exception 'This time is reserved for a membership session.' using errcode = '23514';
  end if;

  price := resolve_booking_price(court.facility_sport_id, src.court_id, p_new_start, p_new_end, fac.timezone);

  insert into bookings (
    facility_id, court_id, member_id, start_time, end_time, status,
    customer_type, guest_name, guest_phone, guest_player_id,
    amount_minor, currency, notes, created_by, payment_status,
    party_size, payment_method
  ) values (
    src.facility_id, src.court_id, null, p_new_start, p_new_end, 'confirmed',
    'GUEST', src.guest_name, src.guest_phone, src.guest_player_id,
    price, fac.currency, src.notes, auth.uid(), 'PENDING',
    src.party_size, null
  ) returning * into result;

  return result;
end;
$$;

-- update_guest_booking (was 0041_guest_booking_actions.sql)
create or replace function update_guest_booking(
  p_booking_id uuid,
  p_guest_name text,
  p_guest_phone text,
  p_party_size integer,
  p_notes text
) returns bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  b bookings;
begin
  perform require_page_access_any((select t.facility_id from bookings t where t.id = p_booking_id), array['GUEST_BOOKINGS_EDIT', 'BOOKINGS_EDIT']);
  select * into b from bookings where id = p_booking_id;
  if b.id is null then
    raise exception 'Booking not found' using errcode = 'P0002';
  end if;
  if b.customer_type <> 'GUEST' then
    raise exception 'Not a guest booking.' using errcode = '23514';
  end if;
  if not has_facility_role(b.facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized.' using errcode = '42501';
  end if;
  if trim(coalesce(p_guest_name, '')) = '' then
    raise exception 'Guest name is required.' using errcode = '23514';
  end if;

  update bookings set
    guest_name = trim(p_guest_name),
    guest_phone = nullif(trim(p_guest_phone), ''),
    party_size = greatest(coalesce(p_party_size, 1), 1),
    notes = nullif(trim(p_notes), ''),
    updated_at = now()
  where id = p_booking_id
  returning * into b;
  return b;
end;
$$;

-- delete_guest_booking (was 0041_guest_booking_actions.sql)
create or replace function delete_guest_booking(p_booking_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  b bookings;
begin
  perform require_page_access_any((select t.facility_id from bookings t where t.id = p_booking_id), array['GUEST_BOOKINGS_CANCEL', 'BOOKINGS_CANCEL']);
  select * into b from bookings where id = p_booking_id;
  if b.id is null then
    raise exception 'Booking not found' using errcode = 'P0002';
  end if;
  if b.customer_type <> 'GUEST' then
    raise exception 'Not a guest booking.' using errcode = '23514';
  end if;
  if not has_facility_role(b.facility_id, array['owner', 'manager']::facility_role[]) then
    raise exception 'Not authorized.' using errcode = '42501';
  end if;
  if b.payment_status = 'PAID' or exists (
    select 1 from payments p where p.booking_id = b.id and p.status in ('paid', 'refunded')
  ) then
    raise exception 'This booking has a settled payment. Cancel and refund it instead of deleting.' using errcode = '23514';
  end if;

  delete from bookings where id = p_booking_id;
end;
$$;

-- record_guest_booking_payment (was 0041_guest_booking_actions.sql)
create or replace function record_guest_booking_payment(
  p_booking_id uuid,
  p_method text,
  p_amount_minor integer
) returns bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  b bookings;
  amt integer;
begin
  perform require_page_access_any((select t.facility_id from bookings t where t.id = p_booking_id), array['BOOKINGS_MANAGE_PAYMENTS', 'FINANCE_RECORD_PAYMENT', 'GUEST_BOOKINGS_EDIT']);
  select * into b from bookings where id = p_booking_id;
  if b.id is null then
    raise exception 'Booking not found' using errcode = 'P0002';
  end if;
  if not has_facility_role(b.facility_id, array['owner', 'manager', 'staff']::facility_role[]) then
    raise exception 'Not authorized.' using errcode = '42501';
  end if;
  if b.payment_status = 'PAID' then
    raise exception 'This booking is already paid.' using errcode = '23514';
  end if;

  amt := greatest(coalesce(nullif(p_amount_minor, 0), b.amount_minor, 0), 0);

  insert into payments (facility_id, member_id, booking_id, amount_inr, status, payment_method, paid_at)
  values (b.facility_id, null, b.id, round(amt / 100.0), 'paid'::payment_status, nullif(trim(p_method), ''), now());

  update bookings set payment_status = 'PAID', payment_method = coalesce(nullif(trim(p_method), ''), payment_method), updated_at = now()
  where id = p_booking_id
  returning * into b;
  return b;
end;
$$;

-- upsert_cancellation_policy (was 0023_cancellation_refunds.sql)
create or replace function upsert_cancellation_policy(
  p_facility_id uuid,
  p_full_refund_hours integer,
  p_full_refund_percent integer,
  p_partial_refund_hours integer,
  p_partial_refund_percent integer
) returns cancellation_policies
language plpgsql
as $$
declare
  result cancellation_policies;
begin
  perform require_page_access_any(p_facility_id, array['FACILITY_SETTINGS_EDIT']);
  insert into cancellation_policies (facility_id, full_refund_hours, full_refund_percent, partial_refund_hours, partial_refund_percent)
  values (p_facility_id, p_full_refund_hours, p_full_refund_percent, p_partial_refund_hours, p_partial_refund_percent)
  on conflict (facility_id) do update set
    full_refund_hours = excluded.full_refund_hours,
    full_refund_percent = excluded.full_refund_percent,
    partial_refund_hours = excluded.partial_refund_hours,
    partial_refund_percent = excluded.partial_refund_percent,
    updated_at = now()
  returning * into result;
  return result;
end;
$$;

-- get_coaching_overview (was 0134_coaching_sport_selection.sql)
create or replace function get_coaching_overview(p_facility_id uuid, p_facility_sport_ids uuid[] default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_base jsonb;
  v_tz text;
  v_today date;
  v_day tstzrange;
  v_active integer;
  v_upcoming jsonb;
begin
  perform require_page_access_any(p_facility_id, array['COACHING_VIEW']);
  if coaching_scope_own(p_facility_id) then raise exception 'This is not available for your role.' using errcode = '42501'; end if;
  -- The base function does the permission check.
  v_base := _get_coaching_overview_base(p_facility_id, p_facility_sport_ids);

  v_tz := coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata');
  v_today := (now() at time zone v_tz)::date;
  v_day := tstzrange(v_today::timestamp at time zone v_tz, (v_today + 1)::timestamp at time zone v_tz);

  -- Active sessions: today's sessions that are scheduled and in an active status.
  select count(*)::integer into v_active
  from coaching_sessions cs
  left join coaching_programs cp on cp.id = cs.program_id
  where cs.facility_id = p_facility_id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids)
    and cs.status in ('SCHEDULED', 'CONFIRMED', 'IN_PROGRESS')
    and v_day @> cs.start_at
    and (
      cs.program_id is null
      or (
        cp.start_date is not null
        and cp.start_date <= v_today
        and exists (select 1 from coaching_enrollments e where e.program_id = cp.id and e.status = 'ACTIVE')
      )
    );

  -- The next two sessions still to happen, today or on a later day.
  select coalesce(jsonb_agg(r.row order by r.start_at), '[]'::jsonb) into v_upcoming
  from (
    select cs.start_at,
      jsonb_build_object(
        'id', cs.id,
        'startAt', cs.start_at,
        'endAt', cs.end_at,
        'programName', coalesce(cp.name, cs.title, 'Coaching Session'),
        'coachName', pr.full_name,
        'courtName', c.name,
        'enrolled', (select count(*) from coaching_session_students css where css.session_id = cs.id and css.status = 'ENROLLED'),
        'capacity', cs.capacity,
        'status', cs.status
      ) as row
    from coaching_sessions cs
    left join coaching_programs cp on cp.id = cs.program_id
    join coaches co on co.id = cs.coach_id
    join profiles pr on pr.id = co.user_id
    join courts c on c.id = cs.court_id
    where cs.facility_id = p_facility_id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids)
      and cs.status in ('SCHEDULED', 'CONFIRMED')
      and cs.start_at >= now()
      and (
        cs.program_id is null
        or (
          cp.start_date is not null
          and cp.start_date <= v_today
          and exists (select 1 from coaching_enrollments e where e.program_id = cp.id and e.status = 'ACTIVE')
        )
      )
    order by cs.start_at
    limit 2
  ) r;

  return jsonb_set(
    jsonb_set(v_base, '{kpis,activeSessions}', to_jsonb(v_active), true),
    '{upcomingSessions}', v_upcoming, true
  );
end;
$$;

-- get_coaching_card_stats (was 0134_coaching_sport_selection.sql)
create or replace function get_coaching_card_stats(p_facility_id uuid, p_facility_sport_ids uuid[] default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  tz text;
  month_start date;
begin
  perform require_page_access_any(p_facility_id, array['COACHING_VIEW']);
  if coaching_scope_own(p_facility_id) then raise exception 'This is not available for your role.' using errcode = '42501'; end if;
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  tz := coalesce((select timezone from facilities where id = p_facility_id), 'Asia/Kolkata');
  month_start := date_trunc('month', now() at time zone tz)::date;

  return jsonb_build_object(
    'totalCoaches', (select count(*) from coaches where facility_id = p_facility_id and coaching_sport_ok_coach(coaches.id, p_facility_sport_ids)),
    'coachingExpenseMinor', (
      select coalesce(sum(x.amount_minor), 0)::bigint
      from expenses x
      join expense_categories c on c.id = x.category_id
      where x.facility_id = p_facility_id
        and x.status = 'RECORDED'
        and lower(c.name) = 'coaching'
        and x.spent_on >= month_start
        and x.spent_on < (month_start + interval '1 month')::date
    )
  );
end;
$$;

-- get_coaching_insights (was 0134_coaching_sport_selection.sql)
create or replace function get_coaching_insights(p_facility_id uuid, p_days integer default 30, p_facility_sport_ids uuid[] default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  tz text;
  window_ tstzrange;
  completed_count integer;
  concluded_count integer;
begin
  perform require_page_access_any(p_facility_id, array['COACHING_VIEW']);
  if coaching_scope_own(p_facility_id) then raise exception 'This is not available for your role.' using errcode = '42501'; end if;
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  if p_days not in (30, 60, 90) then
    raise exception 'Unsupported window — expected 30, 60 or 90 days.' using errcode = '22023';
  end if;
  tz := coalesce((select timezone from facilities where id = p_facility_id), 'Asia/Kolkata');
  window_ := tstzrange(
    (date_trunc('day', now() at time zone tz) - (p_days - 1) * interval '1 day') at time zone tz,
    (date_trunc('day', now() at time zone tz) + interval '1 day') at time zone tz
  );

  select
    count(*) filter (where cs.status = 'COMPLETED'),
    count(*) filter (where cs.status in ('COMPLETED', 'CANCELLED'))
  into completed_count, concluded_count
  from coaching_sessions cs
  where cs.facility_id = p_facility_id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and window_ @> cs.start_at;

  return jsonb_build_object(
    'windowDays', p_days,
    'totalStudents', (
      select count(distinct e.member_id)
      from coaching_session_students css
      join coaching_sessions cs on cs.id = css.session_id
      join coaching_enrollments e on e.id = css.enrollment_id
      where cs.facility_id = p_facility_id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and css.status = 'ENROLLED'
        and cs.status <> 'CANCELLED' and window_ @> cs.start_at
    ),
    'sessionAttendancePct', case when concluded_count > 0 then round(100.0 * completed_count / concluded_count, 1) else null end,
    'coachingRevenueMinor', (
      select coalesce(sum(p.amount_inr) * 100, 0)::bigint from payments p
      where p.facility_id = p_facility_id and p.status = 'paid'
        and p.coaching_enrollment_id is not null and coaching_sport_ok_enrollment(p.coaching_enrollment_id, p_facility_sport_ids)
        and window_ @> coalesce(p.paid_at, p.created_at)
    ),
    'averageRating', (
      select round(avg(c.rating), 1) from coaches c
      where c.facility_id = p_facility_id and coaching_sport_ok_coach(c.id, p_facility_sport_ids) and c.status = 'ACTIVE' and c.rating is not null
        and not exists (
          select 1 from facility_users fu
          where fu.facility_id = c.facility_id and fu.user_id = c.user_id and fu.status = 'INACTIVE'
        )
    )
  );
end;
$$;

-- get_coaching_total_revenue (was 0134_coaching_sport_selection.sql)
create or replace function get_coaching_total_revenue(p_facility_id uuid, p_facility_sport_ids uuid[] default null)
returns bigint
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform require_page_access_any(p_facility_id, array['COACHING_VIEW']);
  if coaching_scope_own(p_facility_id) then raise exception 'This is not available for your role.' using errcode = '42501'; end if;
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  return (
