      and p.coaching_enrollment_id is not null and coaching_sport_ok_enrollment(p.coaching_enrollment_id, p_facility_sport_ids)
  );
end;
$$;

-- list_coaching_programs (was 0134_coaching_sport_selection.sql)
create or replace function list_coaching_programs(
  p_facility_id uuid,
  p_search text default null,
  p_status text default null,
  p_limit integer default 20,
  p_offset integer default 0,
  p_facility_sport_id uuid default null,
  p_program_type text default null,
  p_level text default null,
  p_facility_sport_ids uuid[] default null
)
returns table (
  id uuid,
  name text,
  level text,
  age_group text,
  category text,
  default_duration_minutes integer,
  default_capacity integer,
  session_count integer,
  default_price_minor integer,
  is_membership_included boolean,
  status text,
  image_url text,
  program_type text,
  sports_per_week integer,
  student_count bigint,
  scheduled_session_count bigint,
  batch_count bigint,
  facility_sport_id uuid,
  start_date date,
  end_date date,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform require_page_access_any(p_facility_id, array['COACHING_PROGRAMS_VIEW']);
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  return query
  select
    cp.id, cp.name, cp.level, cp.age_group, cp.category,
    cp.default_duration_minutes, cp.default_capacity, cp.session_count,
    cp.default_price_minor, cp.is_membership_included, cp.status,
    cp.image_url, cp.program_type, cp.sessions_per_week,
    (select count(*) from coaching_enrollments e where e.program_id = cp.id and e.status = 'ACTIVE')::bigint,
    (select count(*) from coaching_sessions cs where cs.program_id = cp.id and cs.status <> 'CANCELLED')::bigint,
    (select count(*) from coaching_program_batches b where b.program_id = cp.id and b.status = 'ACTIVE')::bigint,
    cp.facility_sport_id, cp.start_date, cp.end_date,
    count(*) over ()::bigint
  from coaching_programs cp
  where cp.facility_id = p_facility_id and (not coaching_scope_own(p_facility_id) or exists (select 1 from coaching_sessions own_s where own_s.program_id = cp.id and own_s.coach_id = my_coach_id(p_facility_id)) or exists (select 1 from coaching_enrollments own_e where own_e.program_id = cp.id and own_e.coach_id = my_coach_id(p_facility_id))) and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids))
    and (p_status is null or cp.status = p_status)
    and (p_facility_sport_id is null or cp.facility_sport_id = p_facility_sport_id)
    and (p_program_type is null or cp.program_type = p_program_type)
    and (p_level is null or cp.level = p_level)
    and (p_search is null or trim(p_search) = '' or cp.name ilike '%' || trim(p_search) || '%')
  order by cp.status, cp.name
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- get_program_card_stats (was 0134_coaching_sport_selection.sql)
create or replace function get_program_card_stats(p_facility_id uuid, p_facility_sport_ids uuid[] default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform require_page_access_any(p_facility_id, array['COACHING_PROGRAMS_VIEW']);
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'totalPrograms', (select count(*) from coaching_programs where facility_id = p_facility_id and (p_facility_sport_ids is null or facility_sport_id = any (p_facility_sport_ids))),
    'activePrograms', (select count(*) from coaching_programs where facility_id = p_facility_id and (p_facility_sport_ids is null or facility_sport_id = any (p_facility_sport_ids)) and status = 'ACTIVE'),
    'enrolledStudents', (select count(*) from coaching_enrollments where facility_id = p_facility_id and coaching_sport_ok_program(program_id, p_facility_sport_ids) and status = 'ACTIVE'),
    'availableSeats', (
      select coalesce(sum(seats), 0)::bigint from (
        select case
          when exists (select 1 from coaching_program_batches b where b.program_id = cp.id and b.status = 'ACTIVE')
          then (
            select coalesce(sum(greatest(
              b.capacity - (select count(*) from coaching_enrollments e
                            where e.batch_id = b.id and e.status in ('ACTIVE', 'PAUSED')), 0)), 0)
            from coaching_program_batches b
            where b.program_id = cp.id and b.status = 'ACTIVE'
          )
          else greatest(
            cp.default_capacity - (select count(*) from coaching_enrollments e
                                   where e.program_id = cp.id and e.status in ('ACTIVE', 'PAUSED')), 0)
        end as seats
        from coaching_programs cp
        where cp.facility_id = p_facility_id and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids)) and cp.status = 'ACTIVE'
      ) s
    )
  );
end;
$$;

-- get_program_insights (was 0134_coaching_sport_selection.sql)
create or replace function get_program_insights(p_facility_id uuid, p_facility_sport_ids uuid[] default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  enrolled_recent integer;
  enrolled_prior integer;
  featured coaching_programs;
  featured_json jsonb;
begin
  perform require_page_access_any(p_facility_id, array['COACHING_PROGRAMS_VIEW']);
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;

  select count(*) into enrolled_recent from coaching_enrollments e
  where e.facility_id = p_facility_id and coaching_sport_ok_program(e.program_id, p_facility_sport_ids) and e.created_at >= now() - interval '30 days';
  select count(*) into enrolled_prior from coaching_enrollments e
  where e.facility_id = p_facility_id and coaching_sport_ok_program(e.program_id, p_facility_sport_ids) and e.created_at >= now() - interval '60 days' and e.created_at < now() - interval '30 days';

  select * into featured from coaching_programs
  where facility_id = p_facility_id and status = 'ACTIVE' and (p_facility_sport_ids is null or facility_sport_id = any (p_facility_sport_ids))
  order by (select count(*) from coaching_enrollments e where e.program_id = coaching_programs.id and e.status = 'ACTIVE') desc, name
  limit 1;

  if featured.id is not null then
    featured_json := jsonb_build_object(
      'id', featured.id,
      'name', featured.name,
      'imageUrl', featured.image_url,
      'level', featured.level,
      'ageGroup', featured.age_group,
      'defaultCapacity', featured.default_capacity,
      'studentCount', (select count(*) from coaching_enrollments e where e.program_id = featured.id and e.status = 'ACTIVE'),
      'defaultPriceMinor', featured.default_price_minor,
      'isMembershipIncluded', featured.is_membership_included,
      'durationWeeks', case when featured.start_date is not null and featured.end_date is not null
        then greatest(1, round((featured.end_date - featured.start_date) / 7.0)::int) else null end
    );
  else
    featured_json := null;
  end if;

  return jsonb_build_object(
    'totalPrograms', (select count(*) from coaching_programs where facility_id = p_facility_id and (p_facility_sport_ids is null or facility_sport_id = any (p_facility_sport_ids))),
    'newProgramsThisMonth', (
      select count(*) from coaching_programs
      where facility_id = p_facility_id and created_at >= date_trunc('month', now())
    ),
    'enrolledStudents', (select count(*) from coaching_enrollments where facility_id = p_facility_id and coaching_sport_ok_program(program_id, p_facility_sport_ids) and status = 'ACTIVE'),
    'enrolledStudentsPctChange', case when enrolled_prior > 0 then round(100.0 * (enrolled_recent - enrolled_prior) / enrolled_prior) else null end,
    'avgCompletionPct', (
      select round(avg(
        (select count(*) from coaching_enrollments e where e.program_id = cp.id and e.status = 'ACTIVE')::numeric
        / nullif(cp.default_capacity, 0) * 100
      ), 0)
      from coaching_programs cp
      where cp.facility_id = p_facility_id and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids)) and cp.status = 'ACTIVE' and cp.default_capacity > 0
    ),
    'averageRating', (
      select round(avg(c.rating), 1) from coaches c
      where c.facility_id = p_facility_id and coaching_sport_ok_coach(c.id, p_facility_sport_ids) and c.status = 'ACTIVE' and c.rating is not null
        and not exists (
          select 1 from facility_users fu
          where fu.facility_id = c.facility_id and fu.user_id = c.user_id and fu.status = 'INACTIVE'
        )
    ),
    'activeBatches', (
      select count(*) from coaching_program_batches b
      join coaching_programs cp on cp.id = b.program_id
      where cp.facility_id = p_facility_id and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids)) and cp.status = 'ACTIVE' and b.status = 'ACTIVE'
    ),
    'featuredProgram', featured_json
  );
end;
$$;

-- get_coaching_program (was 0100_coaching_program_batches.sql)
create or replace function get_coaching_program(p_program_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare cp coaching_programs;
begin
  perform require_page_access_any((select t.facility_id from coaching_programs t where t.id = p_program_id), array['COACHING_PROGRAMS_VIEW', 'COACHING_SESSIONS_VIEW', 'COACHING_STUDENTS_VIEW']);
  select * into cp from coaching_programs where id = p_program_id;
  if cp.id is null then
    raise exception 'Program not found.' using errcode = 'P0002';
  end if;
  if not has_permission(cp.facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'id', cp.id, 'facilityId', cp.facility_id, 'name', cp.name, 'level', cp.level,
    'ageGroup', cp.age_group, 'category', cp.category, 'description', cp.description,
    'facilitySportId', cp.facility_sport_id,
    'defaultDurationMinutes', cp.default_duration_minutes, 'defaultCapacity', cp.default_capacity,
    'sessionCount', cp.session_count, 'defaultPriceMinor', cp.default_price_minor,
    'isMembershipIncluded', cp.is_membership_included, 'status', cp.status,
    'imageUrl', cp.image_url, 'programType', cp.program_type, 'minCapacity', cp.min_capacity,
    'programStructure', to_jsonb(cp.program_structure), 'sessionFormat', cp.session_format,
    'sessionsPerWeek', cp.sessions_per_week, 'startDate', cp.start_date, 'endDate', cp.end_date,
    'paymentMode', cp.payment_mode, 'earlyBirdDiscountMinor', cp.early_bird_discount_minor,
    'discountValidTill', cp.discount_valid_till, 'taxPercent', cp.tax_percent,
    'paymentNotes', cp.payment_notes, 'allowWaitlist', cp.allow_waitlist,
    'allowTrialSession', cp.allow_trial_session, 'autoEnrollNextBatch', cp.auto_enroll_next_batch,
    'sendNotifications', cp.send_notifications, 'visibleInBooking', cp.visible_in_booking,
    'enrollmentDeadline', cp.enrollment_deadline,
    'createdAt', cp.created_at,
    'batches', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', b.id, 'name', b.name, 'daysOfWeek', b.days_of_week, 'startTime', b.start_time,
        'endTime', b.end_time, 'capacity', b.capacity, 'status', b.status,
        'courtId', b.court_id, 'courtName', c.name,
        'coachId', b.coach_id, 'coachName', pr.full_name
      ) order by b.created_at)
      from coaching_program_batches b
      join courts c on c.id = b.court_id
      left join coaches co on co.id = b.coach_id
      left join profiles pr on pr.id = co.user_id
      where b.program_id = cp.id
    ), '[]'::jsonb),
    'stats', jsonb_build_object(
      'activeStudents', (select count(*) from coaching_enrollments e where e.program_id = cp.id and e.status = 'ACTIVE'),
      'totalEnrollments', (select count(*) from coaching_enrollments e where e.program_id = cp.id),
      'scheduledSessions', (select count(*) from coaching_sessions cs where cs.program_id = cp.id and cs.status in ('SCHEDULED','CONFIRMED')),
      'completedSessions', (select count(*) from coaching_sessions cs where cs.program_id = cp.id and cs.status = 'COMPLETED')
    )
  );
end;
$$;

-- list_coaching_program_options (was 0086_coaching_read_rpcs.sql)
create or replace function list_coaching_program_options(p_facility_id uuid)
returns table (id uuid, name text, default_capacity integer, default_duration_minutes integer, default_price_minor integer, is_membership_included boolean, session_count integer)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform require_page_access_any(p_facility_id, array['COACHING_PROGRAMS_VIEW', 'COACHING_SESSIONS_VIEW', 'COACHING_STUDENTS_VIEW', 'COACHING_CREATE_SESSION']);
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  return query
  select cp.id, cp.name, cp.default_capacity, cp.default_duration_minutes,
         cp.default_price_minor, cp.is_membership_included, cp.session_count
  from coaching_programs cp
  where cp.facility_id = p_facility_id and cp.status = 'ACTIVE'
  order by cp.name;
end;
$$;

-- list_coaching_enrollments (was 0134_coaching_sport_selection.sql)
create or replace function list_coaching_enrollments(
  p_facility_id uuid,
  p_search text default null,
  p_program_id uuid default null,
  p_status text default null,
  p_limit integer default 20,
  p_offset integer default 0,
  p_coach_id uuid default null,
  p_level text default null,
  p_facility_sport_ids uuid[] default null
)
returns table (
  id uuid,
  member_id uuid,
  student_name text,
  student_phone text,
  student_age integer,
  program_id uuid,
  program_name text,
  program_level text,
  coach_id uuid,
  coach_name text,
  coach_avatar_url text,
  start_date date,
  end_date date,
  sessions_total integer,
  price_minor integer,
  paid_minor bigint,
  status text,
  payment_status text,
  batch_id uuid,
  batch_name text,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform require_page_access_any(p_facility_id, array['COACHING_STUDENTS_VIEW']);
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  return query
  with rows as (
    select
      e.id, e.member_id, m.full_name as student_name, m.phone as student_phone,
      case when m.date_of_birth is null then null else extract(year from age(current_date, m.date_of_birth))::int end as student_age,
      e.program_id, cp.name as program_name, cp.level as program_level,
      e.coach_id, pr.full_name as coach_name, pr.avatar_url as coach_avatar_url,
      e.start_date, e.end_date, e.sessions_total, e.price_minor,
      coalesce((select sum(p.amount_inr) * 100 from payments p where p.coaching_enrollment_id = e.id and p.status = 'paid'), 0)::bigint as paid_minor,
      e.status, e.batch_id, b.name as batch_name
    from coaching_enrollments e
    join members m on m.id = e.member_id
    join coaching_programs cp on cp.id = e.program_id
    left join coaches co on co.id = e.coach_id
    left join profiles pr on pr.id = co.user_id
    left join coaching_program_batches b on b.id = e.batch_id
    where e.facility_id = p_facility_id and (not coaching_scope_own(p_facility_id) or e.coach_id = my_coach_id(p_facility_id)) and coaching_sport_ok_program(e.program_id, p_facility_sport_ids)
      and (p_program_id is null or e.program_id = p_program_id)
      and (p_coach_id is null or e.coach_id = p_coach_id)
      and (p_level is null or cp.level = p_level)
      and (
        p_status is null
        or (p_status = 'NOT_ACTIVE' and e.status <> 'ACTIVE')
        or e.status = p_status
      )
      and (
        p_search is null or trim(p_search) = ''
        or m.full_name ilike '%' || trim(p_search) || '%'
        or m.phone ilike '%' || trim(p_search) || '%'
        or m.email ilike '%' || trim(p_search) || '%'
        or cp.name ilike '%' || trim(p_search) || '%'
      )
  )
  select
    r.id, r.member_id, r.student_name, r.student_phone, r.student_age,
    r.program_id, r.program_name, r.program_level, r.coach_id, r.coach_name, r.coach_avatar_url,
    r.start_date, r.end_date, r.sessions_total, r.price_minor, r.paid_minor, r.status,
    case
      when r.price_minor = 0 then 'INCLUDED'
      when r.paid_minor >= r.price_minor then 'PAID'
      when r.paid_minor > 0 then 'PARTIAL'
      else 'PENDING'
    end as payment_status,
    r.batch_id, r.batch_name,
    count(*) over ()::bigint as total_count
  from rows r
  order by r.start_date desc, r.student_name
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- get_student_card_stats (was 0134_coaching_sport_selection.sql)
create or replace function get_student_card_stats(p_facility_id uuid, p_facility_sport_ids uuid[] default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  tz text;
  month_start timestamptz;
begin
  perform require_page_access_any(p_facility_id, array['COACHING_STUDENTS_VIEW']);
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  tz := coalesce((select timezone from facilities where id = p_facility_id), 'Asia/Kolkata');
  month_start := date_trunc('month', now() at time zone tz) at time zone tz;

  return jsonb_build_object(
    'totalStudents', (select count(distinct member_id) from coaching_enrollments where facility_id = p_facility_id and coaching_sport_ok_program(program_id, p_facility_sport_ids)),
    'enrolledStudents', (
      select count(distinct member_id) from coaching_enrollments where facility_id = p_facility_id and coaching_sport_ok_program(program_id, p_facility_sport_ids) and status = 'ACTIVE'
    ),
    'revenueMinor', (
      select coalesce(sum(p.amount_inr) * 100, 0)::bigint from payments p
      where p.facility_id = p_facility_id and p.status = 'paid' and p.coaching_enrollment_id is not null and coaching_sport_ok_enrollment(p.coaching_enrollment_id, p_facility_sport_ids)
        and coalesce(p.paid_at, p.created_at) >= month_start
        and coalesce(p.paid_at, p.created_at) < month_start + interval '1 month'
    ),
    'pendingMinor', (
      select coalesce(sum(greatest(e.price_minor - coalesce((
        select sum(p.amount_inr) * 100 from payments p
        where p.coaching_enrollment_id = e.id and p.status = 'paid'), 0), 0)), 0)::bigint
      from coaching_enrollments e
      where e.facility_id = p_facility_id and coaching_sport_ok_program(e.program_id, p_facility_sport_ids) and e.status <> 'CANCELLED' and e.pricing_type <> 'MEMBERSHIP_INCLUDED'
    )
  );
end;
$$;

-- get_coaching_enrollment (was 0107_coaching_enrollment_batch.sql)
create or replace function get_coaching_enrollment(p_enrollment_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  e coaching_enrollments;
  v_can_progress boolean;
  v_paid bigint;
begin
  perform require_page_access_any((select t.facility_id from coaching_enrollments t where t.id = p_enrollment_id), array['COACHING_STUDENTS_VIEW']);
  select * into e from coaching_enrollments where id = p_enrollment_id;
  if e.id is null then
    raise exception 'Enrollment not found.' using errcode = 'P0002';
  end if;
  if not has_permission(e.facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  v_can_progress := has_permission(e.facility_id, 'COACHING_VIEW_PROGRESS');
  select coalesce(sum(p.amount_inr) * 100, 0)::bigint into v_paid
    from payments p where p.coaching_enrollment_id = e.id and p.status = 'paid';

  return (
      jsonb_build_object(
      'id', e.id,
      'facilityId', e.facility_id,
      'memberId', e.member_id,
      'studentName', (select full_name from members where id = e.member_id),
      'studentPhone', (select phone from members where id = e.member_id),
      'studentEmail', (select email from members where id = e.member_id),
      'programId', e.program_id,
      'programName', (select name from coaching_programs where id = e.program_id),
      'programLevel', (select level from coaching_programs where id = e.program_id),
      'coachId', e.coach_id,
      'coachName', (select pr.full_name from coaches co join profiles pr on pr.id = co.user_id where co.id = e.coach_id),
      'batchId', e.batch_id,
      'batchName', (select name from coaching_program_batches where id = e.batch_id),
      'startDate', e.start_date,
      'endDate', e.end_date,
      'sessionsTotal', e.sessions_total,
      'priceMinor', e.price_minor,
      'paidMinor', v_paid,
      'outstandingMinor', greatest(e.price_minor - v_paid, 0),
      'pricingType', e.pricing_type,
      'status', e.status,
      'notes', e.notes,
      'cancelReason', e.cancel_reason,
      'createdAt', e.created_at,
      'sessions', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', cs.id, 'startAt', cs.start_at, 'endAt', cs.end_at,
          'programName', cp2.name, 'courtName', c.name, 'status', cs.status
        ) order by cs.start_at desc)
        from coaching_session_students css
        join coaching_sessions cs on cs.id = css.session_id
        join coaching_programs cp2 on cp2.id = cs.program_id
        join courts c on c.id = cs.court_id
        where css.enrollment_id = e.id and css.status = 'ENROLLED'
      ), '[]'::jsonb),
      'payments', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', p.id, 'amountMinor', (p.amount_inr * 100), 'paidAt', coalesce(p.paid_at, p.created_at),
          'method', p.payment_method, 'reference', p.reference
        ) order by coalesce(p.paid_at, p.created_at) desc)
        from payments p where p.coaching_enrollment_id = e.id and p.status = 'paid'
      ), '[]'::jsonb),
      'progressNotes', case when v_can_progress then coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', spn.id, 'skillOrGoal', spn.skill_or_goal, 'note', spn.note,
          'progressStatus', spn.progress_status, 'coachName', cpr.full_name,
          'sessionId', spn.session_id, 'createdAt', spn.created_at
        ) order by spn.created_at desc)
        from student_progress_notes spn
        left join coaches sco on sco.id = spn.coach_id
        left join profiles cpr on cpr.id = sco.user_id
        where spn.enrollment_id = e.id
      ), '[]'::jsonb) else null end
    )
  );
end;
$$;

-- list_coaching_sessions (was 0134_coaching_sport_selection.sql)
create or replace function list_coaching_sessions(
  p_facility_id uuid,
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_coach_id uuid default null,
  p_program_id uuid default null,
  p_court_id uuid default null,
  p_status text default null,
  p_limit integer default 200,
  p_offset integer default 0,
  p_facility_sport_ids uuid[] default null
)
returns table (
  id uuid,
  program_id uuid,
  program_name text,
  coach_id uuid,
  coach_name text,
  court_id uuid,
  court_name text,
  start_at timestamptz,
  end_at timestamptz,
  capacity integer,
  enrolled_count bigint,
  status text,
  session_type text,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_today date;
begin
  perform require_page_access_any(p_facility_id, array['COACHING_SESSIONS_VIEW', 'COACHING_SCHEDULE_VIEW']);
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  v_today := (now() at time zone coalesce((select f.timezone from facilities f where f.id = p_facility_id), 'Asia/Kolkata'))::date;
  return query
  select
    cs.id, cs.program_id, coalesce(cp.name, cs.title, 'Coaching Session'), cs.coach_id, pr.full_name, cs.court_id, c.name,
    cs.start_at, cs.end_at, cs.capacity,
    (select count(*) from coaching_session_students css where css.session_id = cs.id and css.status = 'ENROLLED')::bigint,
    cs.status, cs.session_type,
    count(*) over ()::bigint
  from coaching_sessions cs
  left join coaching_programs cp on cp.id = cs.program_id
  join coaches co on co.id = cs.coach_id
  join profiles pr on pr.id = co.user_id
  join courts c on c.id = cs.court_id
  where cs.facility_id = p_facility_id and (not coaching_scope_own(p_facility_id) or cs.coach_id = my_coach_id(p_facility_id)) and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids)
    and (
      cs.program_id is null
      or (
        cp.start_date is not null
        and cp.start_date <= v_today
        and exists (select 1 from coaching_enrollments e where e.program_id = cp.id and e.status = 'ACTIVE')
      )
    )
    and (p_from is null or cs.end_at >= p_from)
    and (p_to is null or cs.start_at < p_to)
    and (p_coach_id is null or cs.coach_id = p_coach_id)
    and (p_program_id is null or cs.program_id = p_program_id)
    and (p_court_id is null or cs.court_id = p_court_id)
    and (p_status is null or cs.status = p_status)
  order by cs.start_at
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- get_coaching_session (was 0112_fix_get_coaching_session_ambiguity.sql)
create or replace function get_coaching_session(p_session_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  sess coaching_sessions;
  v_can_progress boolean;
begin
  perform require_page_access_any((select t.facility_id from coaching_sessions t where t.id = p_session_id), array['COACHING_SESSIONS_VIEW', 'COACHING_SCHEDULE_VIEW']);
  select * into sess from coaching_sessions where id = p_session_id;
  if sess.id is null then
    raise exception 'Session not found.' using errcode = 'P0002';
  end if;
  if not has_permission(sess.facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  v_can_progress := has_permission(sess.facility_id, 'COACHING_VIEW_PROGRESS');

  return (
    select jsonb_build_object(
      'id', cs.id,
      'facilityId', cs.facility_id,
      'programId', cs.program_id,
      'programName', coalesce(cp.name, cs.title, 'Coaching Session'),
      'programLevel', coalesce(cp.level, cs.level),
      'coachId', cs.coach_id,
      'coachName', pr.full_name,
      'courtId', cs.court_id,
      'courtName', c.name,
      'startAt', cs.start_at,
      'endAt', cs.end_at,
      'capacity', cs.capacity,
      'status', cs.status,
      'notes', cs.notes,
      'objective', cs.objective,
      'objectiveResult', cs.objective_result,
      'completedAt', cs.completed_at,
      'cancelReason', cs.cancel_reason,
      'title', cs.title,
      'description', cs.description,
      'sessionType', cs.session_type,
      'facilitySportId', cs.facility_sport_id,
      'pricePerStudentMinor', cs.price_per_student_minor,
      'visibleForBooking', cs.visible_for_booking,
      'sendNotification', cs.send_notification,
      'allowWaitlist', cs.allow_waitlist,
      'enrolledCount', (select count(*) from coaching_session_students css where css.session_id = cs.id and css.status = 'ENROLLED'),
      'students', coalesce((
        select jsonb_agg(jsonb_build_object(
          'enrollmentId', e.id,
          'memberId', e.member_id,
          'name', m.full_name,
          'phone', m.phone,
          'status', css.status,
          'enrollmentStatus', e.status
        ) order by m.full_name)
        from coaching_session_students css
        join coaching_enrollments e on e.id = css.enrollment_id
        join members m on m.id = e.member_id
        where css.session_id = cs.id and css.status = 'ENROLLED'
      ), '[]'::jsonb),
      'progressNotes', case when v_can_progress then coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', spn.id, 'memberName', m.full_name, 'skillOrGoal', spn.skill_or_goal,
          'note', spn.note, 'progressStatus', spn.progress_status, 'createdAt', spn.created_at
        ) order by spn.created_at desc)
        from student_progress_notes spn
        join coaching_enrollments e on e.id = spn.enrollment_id
        join members m on m.id = e.member_id
        where spn.session_id = cs.id
      ), '[]'::jsonb) else null end,
      'events', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', ev.id, 'event', ev.event, 'summary', ev.summary,
          'actorName', ap.full_name, 'createdAt', ev.created_at
        ) order by ev.created_at desc)
        from coaching_events ev
        left join profiles ap on ap.id = ev.actor
        where ev.session_id = cs.id
      ), '[]'::jsonb)
    )
    from coaching_sessions cs
    left join coaching_programs cp on cp.id = cs.program_id
    join coaches co on co.id = cs.coach_id
    join profiles pr on pr.id = co.user_id
    join courts c on c.id = cs.court_id
    where cs.id = p_session_id
  );
end;
$$;

-- list_coaching_events (was 0086_coaching_read_rpcs.sql)
create or replace function list_coaching_events(
  p_facility_id uuid,
  p_event text default null,
  p_limit integer default 30,
  p_offset integer default 0
)
returns table (
  id uuid, event text, summary text, actor_name text, detail jsonb, created_at timestamptz, total_count bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform require_page_access_any(p_facility_id, array['COACHING_SESSIONS_VIEW', 'COACHING_SCHEDULE_VIEW', 'COACHING_VIEW']);
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  return query
  select ev.id, ev.event, ev.summary, ap.full_name, ev.detail, ev.created_at, count(*) over ()::bigint
  from coaching_events ev
  left join profiles ap on ap.id = ev.actor
  where ev.facility_id = p_facility_id
    and (p_event is null or ev.event = p_event)
  order by ev.created_at desc
  limit greatest(p_limit, 1) offset greatest(p_offset, 0);
end;
$$;

-- get_coaching_reports (was 0134_coaching_sport_selection.sql)
create or replace function get_coaching_reports(
  p_facility_id uuid,
  p_preset text default null,
  p_start_date date default null,
  p_end_date date default null,
  p_facility_sport_ids uuid[] default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  range_ tstzrange;
  tz text;
begin
  perform require_page_access_any(p_facility_id, array['COACHING_REPORTS_VIEW']);
  if coaching_scope_own(p_facility_id) then raise exception 'This is not available for your role.' using errcode = '42501'; end if;
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  range_ := resolve_finance_date_range(p_facility_id, coalesce(p_preset, 'THIS_MONTH'), p_start_date, p_end_date);
  tz := coalesce((select timezone from facilities where id = p_facility_id), 'Asia/Kolkata');

  return jsonb_build_object(
    'kpis', jsonb_build_object(
      'activeStudents', (select count(distinct e.member_id) from coaching_enrollments e where e.facility_id = p_facility_id and coaching_sport_ok_program(e.program_id, p_facility_sport_ids) and e.status = 'ACTIVE'),
      'activePrograms', (select count(*) from coaching_programs where facility_id = p_facility_id and (p_facility_sport_ids is null or facility_sport_id = any (p_facility_sport_ids)) and status = 'ACTIVE'),
      'sessionsInRange', (select count(*) from coaching_sessions cs where cs.facility_id = p_facility_id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and cs.status <> 'CANCELLED' and range_ @> cs.start_at),
      'completedSessionsInRange', (select count(*) from coaching_sessions cs where cs.facility_id = p_facility_id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and cs.status = 'COMPLETED' and range_ @> cs.start_at),
      'coachingRevenueMinor', (
        select coalesce(sum(p.amount_inr) * 100, 0)::bigint from payments p
        where p.facility_id = p_facility_id and p.status = 'paid'
          and p.coaching_enrollment_id is not null and coaching_sport_ok_enrollment(p.coaching_enrollment_id, p_facility_sport_ids) and range_ @> coalesce(p.paid_at, p.created_at)
      ),
      'avgCapacityUtilization', (
        select coalesce(round(avg(
          case when cs.capacity > 0
            then 100.0 * (select count(*) from coaching_session_students css where css.session_id = cs.id and css.status = 'ENROLLED') / cs.capacity
            else 0 end
        ), 1), 0)
        from coaching_sessions cs
        where cs.facility_id = p_facility_id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and cs.status <> 'CANCELLED' and range_ @> cs.start_at
      )
    ),
    'programPerformance', coalesce((
      select jsonb_agg(row) from (
        select jsonb_build_object(
          'programId', cp.id,
          'programName', cp.name,
          'activeStudents', (select count(*) from coaching_enrollments e where e.program_id = cp.id and e.status = 'ACTIVE'),
          'sessions', (select count(*) from coaching_sessions cs where cs.program_id = cp.id and cs.status <> 'CANCELLED' and range_ @> cs.start_at),
          'capacityUtilization', (
            select coalesce(round(avg(
              case when cs.capacity > 0
                then 100.0 * (select count(*) from coaching_session_students css where css.session_id = cs.id and css.status = 'ENROLLED') / cs.capacity
                else 0 end), 1), 0)
            from coaching_sessions cs where cs.program_id = cp.id and cs.status <> 'CANCELLED' and range_ @> cs.start_at
          ),
          'revenueMinor', (
            select coalesce(sum(p.amount_inr) * 100, 0)::bigint from payments p
            join coaching_enrollments e on e.id = p.coaching_enrollment_id
            where e.program_id = cp.id and p.status = 'paid' and range_ @> coalesce(p.paid_at, p.created_at)
          )
        ) as row
        from coaching_programs cp
        where cp.facility_id = p_facility_id and (p_facility_sport_ids is null or cp.facility_sport_id = any (p_facility_sport_ids))
        order by (select count(*) from coaching_enrollments e where e.program_id = cp.id and e.status = 'ACTIVE') desc
      ) s
    ), '[]'::jsonb),
    'coachUtilization', coalesce((
      select jsonb_agg(row) from (
        select jsonb_build_object(
          'coachId', co.id,
          'coachName', pr.full_name,
          -- Scheduled coaching hours in range.
          'scheduledHours', coalesce(round((
            select sum(extract(epoch from (cs.end_at - cs.start_at)) / 3600.0)
            from coaching_sessions cs
            where cs.coach_id = co.id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and cs.status <> 'CANCELLED' and range_ @> cs.start_at
          )::numeric, 1), 0),
          -- Weekly recurring available hours (spec §30: from availability, not attendance).
          'weeklyAvailableHours', coalesce(round((
            select sum(extract(epoch from (ca.end_time - ca.start_time)) / 3600.0)
            from coach_availability ca where ca.coach_id = co.id
          )::numeric, 1), 0),
          'sessions', (select count(*) from coaching_sessions cs where cs.coach_id = co.id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and cs.status <> 'CANCELLED' and range_ @> cs.start_at)
        ) as row
        from coaches co join profiles pr on pr.id = co.user_id
        where co.facility_id = p_facility_id and coaching_sport_ok_coach(co.id, p_facility_sport_ids) and co.status = 'ACTIVE'
        order by pr.full_name
      ) s
    ), '[]'::jsonb),
    'studentGrowth', coalesce((
      select jsonb_agg(row order by (row->>'monthKey')) from (
        select jsonb_build_object(
          'month', to_char(gs.m, 'Mon'),
          'monthKey', to_char(gs.m, 'YYYY-MM'),
          'students', (
            select count(distinct e.member_id) from coaching_enrollments e
            where e.facility_id = p_facility_id and coaching_sport_ok_program(e.program_id, p_facility_sport_ids)
              and e.start_date <= (gs.m + interval '1 month' - interval '1 day')::date
              and (e.end_date is null or e.end_date >= gs.m::date)
              and e.status <> 'CANCELLED'
          )
        ) as row
        from generate_series(
          date_trunc('month', (now() at time zone tz)) - interval '5 months',
          date_trunc('month', (now() at time zone tz)),
          interval '1 month'
        ) as gs(m)
      ) s
    ), '[]'::jsonb)
  );
end;
$$;

-- get_coach (was 0095_coaching_add_coach_wizard.sql)
create or replace function get_coach(p_coach_id uuid)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = public
  as $$
  declare
    co coaches;
    tz text;
    month_ tstzrange;
  begin
  perform require_page_access_any((select t.facility_id from coaches t where t.id = p_coach_id), array['COACHING_VIEW']);
  if coaching_scope_own((select t.facility_id from coaches t where t.id = p_coach_id)) and p_coach_id is distinct from my_coach_id((select t.facility_id from coaches t where t.id = p_coach_id)) then raise exception 'You can only view your own coach profile.' using errcode = '42501'; end if;
    select * into co from coaches where id = p_coach_id;
    if co.id is null then
      raise exception 'Coach not found.' using errcode = 'P0002';
    end if;
    if not has_permission(co.facility_id, 'COACHING_VIEW') then
      raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
    end if;
    tz := coalesce((select timezone from facilities where id = co.facility_id), 'Asia/Kolkata');
    month_ := _coaching_month_range(co.facility_id);

    return (
      select jsonb_build_object(
        'id', co.id,
        'userId', co.user_id,
        'fullName', pr.full_name,
        'email', pr.email,
        'phone', pr.phone,
        'avatarUrl', pr.avatar_url,
        'specialization', co.specialization,
        'experienceYears', co.experience_years,
        'certifications', co.certifications,
        'bio', co.bio,
        'hourlyRateMinor', co.hourly_rate_minor,
        'status', co.status,
        'joinedOn', co.joined_on,
        'expertiseLevels', co.expertise_levels,
        'defaultSessionDurationMinutes', co.default_session_duration_minutes,
        'dateOfBirth', co.date_of_birth,
        'rating', co.rating,
        'sports', coalesce((
          select jsonb_agg(jsonb_build_object('id', fs.id, 'name', coalesce(fs.custom_sport_name, s.name)) order by coalesce(fs.custom_sport_name, s.name))
          from coach_sports cst
          join facility_sports fs on fs.id = cst.facility_sport_id
          join sports s on s.id = fs.sport_id
          where cst.coach_id = co.id
        ), '[]'::jsonb),
        'title', (select title from facility_users fu where fu.facility_id = co.facility_id and fu.user_id = co.user_id),
        'stats', jsonb_build_object(
          'sessionsThisMonth', (select count(*) from coaching_sessions cs where cs.coach_id = co.id and cs.status <> 'CANCELLED' and month_ @> cs.start_at),
          'activeStudents', (select count(distinct e.member_id) from coaching_enrollments e where e.coach_id = co.id and e.status = 'ACTIVE'),
          'programs', (select count(distinct cs.program_id) from coaching_sessions cs where cs.coach_id = co.id and cs.status <> 'CANCELLED')
        ),
        'todaySchedule', coalesce((
          select jsonb_agg(row order by (row->>'startAt')) from (
            select jsonb_build_object(
              'id', cs.id, 'startAt', cs.start_at, 'endAt', cs.end_at,
              'programName', cp.name, 'courtName', c.name, 'status', cs.status
            ) as row
            from coaching_sessions cs
            join coaching_programs cp on cp.id = cs.program_id
            join courts c on c.id = cs.court_id
            where cs.coach_id = co.id
              and cs.status <> 'CANCELLED'
              and (cs.start_at at time zone tz)::date = (now() at time zone tz)::date
          ) s
        ), '[]'::jsonb),
        'programs', coalesce((
          select jsonb_agg(distinct jsonb_build_object('id', cp.id, 'name', cp.name, 'level', cp.level))
          from coaching_sessions cs join coaching_programs cp on cp.id = cs.program_id
          where cs.coach_id = co.id and cs.status <> 'CANCELLED'
        ), '[]'::jsonb),
        'students', coalesce((
          select jsonb_agg(jsonb_build_object(
            'enrollmentId', e.id, 'memberId', e.member_id, 'name', m.full_name,
            'programName', cp.name, 'status', e.status
          ))
          from coaching_enrollments e
          join members m on m.id = e.member_id
          join coaching_programs cp on cp.id = e.program_id
          where e.coach_id = co.id and e.status = 'ACTIVE'
        ), '[]'::jsonb),
        'availability', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', ca.id, 'dayOfWeek', ca.day_of_week, 'startTime', ca.start_time, 'endTime', ca.end_time
          ) order by ca.day_of_week, ca.start_time)
          from coach_availability ca where ca.coach_id = co.id
        ), '[]'::jsonb),
        'availabilityExceptions', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', ce.id, 'date', ce.exception_date, 'isAvailable', ce.is_available,
            'startTime', ce.start_time, 'endTime', ce.end_time, 'reason', ce.reason
          ) order by ce.exception_date)
          from coach_availability_exceptions ce
          where ce.coach_id = co.id and ce.exception_date >= (now() at time zone tz)::date
        ), '[]'::jsonb)
      )
      from profiles pr where pr.id = co.user_id
    );
  end;
  $$;

-- list_coaches (was 0134_coaching_sport_selection.sql) — own-coach filter
create or replace function list_coaches(
    p_facility_id uuid,
    p_search text default null,
    p_status text default null,
    p_specialization text default null,
    p_limit integer default 20,
    p_offset integer default 0,
    p_sport_id uuid default null,
    -- 'name_asc' (default) | 'name_desc' | 'experience_desc' | 'sessions_desc'
    p_sort text default 'name_asc',
  p_facility_sport_ids uuid[] default null
)
  returns table (
    id uuid,
    user_id uuid,
    full_name text,
    email text,
    phone text,
    avatar_url text,
    specialization text,
    experience_years numeric,
    status text,
    expertise_levels text[],
    rating numeric,
    sports jsonb,
    program_count bigint,
    session_count bigint,
    student_count bigint,
    total_count bigint
  )
  language plpgsql
  stable
  security definer
  set search_path = public
  as $$
  declare month_ tstzrange;
  begin
    if not has_permission(p_facility_id, 'COACHING_VIEW') then
      raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
    end if;
    month_ := _coaching_month_range(p_facility_id);

    return query
    select
      co.id, co.user_id, pr.full_name, pr.email, pr.phone, pr.avatar_url,
      co.specialization, co.experience_years, co.status, co.expertise_levels, co.rating,
      coalesce((
        select jsonb_agg(jsonb_build_object('id', fs.id, 'name', coalesce(fs.custom_sport_name, s.name)) order by coalesce(fs.custom_sport_name, s.name))
        from coach_sports cst
        join facility_sports fs on fs.id = cst.facility_sport_id
        join sports s on s.id = fs.sport_id
        where cst.coach_id = co.id
      ), '[]'::jsonb),
      (select count(distinct cs.program_id) from coaching_sessions cs where cs.coach_id = co.id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and cs.status <> 'CANCELLED')::bigint,
      (select count(*) from coaching_sessions cs where cs.coach_id = co.id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and cs.status <> 'CANCELLED' and month_ @> cs.start_at)::bigint,
      (select count(distinct e.member_id) from coaching_enrollments e where e.coach_id = co.id and e.status = 'ACTIVE')::bigint,
      count(*) over ()::bigint
    from coaches co
    join profiles pr on pr.id = co.user_id
    where co.facility_id = p_facility_id and (not coaching_scope_own(p_facility_id) or co.id = my_coach_id(p_facility_id)) and coaching_sport_ok_coach(co.id, p_facility_sport_ids)
      and (p_status is null or co.status = p_status)
      and (p_specialization is null or co.specialization ilike '%' || p_specialization || '%')
      and (p_sport_id is null or exists (select 1 from coach_sports cst where cst.coach_id = co.id and cst.facility_sport_id = p_sport_id))
      and (
        p_search is null or trim(p_search) = ''
        or pr.full_name ilike '%' || trim(p_search) || '%'
        or pr.email ilike '%' || trim(p_search) || '%'
        or pr.phone ilike '%' || trim(p_search) || '%'
      )
    -- Exactly one CASE below is non-null for every row (p_sort is a single constant for the whole
    -- query), so it alone drives the order; the rest evaluate to null-for-every-row and are
    -- effectively no-ops. full_name is always the final tiebreaker.
    order by
      case when p_sort = 'name_asc' then pr.full_name end asc,
      case when p_sort = 'name_desc' then pr.full_name end desc,
      case when p_sort = 'experience_desc' then co.experience_years end desc nulls last,
      case when p_sort = 'sessions_desc' then (
        select count(*) from coaching_sessions cs where cs.coach_id = co.id and coaching_sport_ok_court(cs.court_id, p_facility_sport_ids) and cs.status <> 'CANCELLED' and month_ @> cs.start_at
      ) end desc,
      pr.full_name asc
    limit greatest(p_limit, 1) offset greatest(p_offset, 0);
  end;
  $$;

-- list_coach_options (was 0104_fix_active_coaches_stale_staff.sql) — own-coach filter
create or replace function list_coach_options(p_facility_id uuid)
returns table (id uuid, name text, specialization text)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not has_permission(p_facility_id, 'COACHING_VIEW') then
    raise exception 'You don''t have permission to view coaching.' using errcode = '42501';
  end if;
  return query
  select c.id, pr.full_name, c.specialization
  from coaches c join profiles pr on pr.id = c.user_id
  where c.facility_id = p_facility_id and (not coaching_scope_own(p_facility_id) or c.id = my_coach_id(p_facility_id)) and c.status = 'ACTIVE'
    and not exists (
      select 1 from facility_users fu
      where fu.facility_id = c.facility_id and fu.user_id = c.user_id and fu.status = 'INACTIVE'
    )
  order by pr.full_name;
end;
$$;
